var e=JSON.parse(`[{"id":"aut.legislacao_tj.eproc_963.0001","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 963/2025, NÃO constitui princípio para utilização, implementação, sustentação, desenvolvimento e evolução do sistema eproc no Tribunal de Justiça","alternativas":{"A":"a personalização do sistema para atender às preferências individuais de cada unidade judiciária.","B":"a aderência à versão nacional.","C":"o desenvolvimento colaborativo.","D":"a automação e simplificação.","E":"a instrumentalidade e autonomia."},"gabarito":"A","explicacao":"O art. 2º elenca cinco princípios: aderência à versão nacional (I); desenvolvimento colaborativo (II); automação e simplificação (III); pragmatismo e efetividade (IV); instrumentalidade e autonomia (V). O inciso IV, aliás, afasta o foco em casos excepcionais ou preferências individuais, e o inciso I busca prevenir fragmentações do sistema.","explicacoes":{"A":"Correta: a resolução rejeita o foco em preferências individuais (art. 2º, IV) e evita fragmentações (art. 2º, I).","B":"É princípio (art. 2º, I).","C":"É princípio (art. 2º, II).","D":"É princípio (art. 2º, III).","E":"É princípio (art. 2º, V)."},"fonte":"Resolução TJSP 963/2025, art. 2º, I a V","mastigado":"A resposta é a letra A. O eproc deve seguir a versão nacional, ser desenvolvido em colaboração, automatizar o que der e valer para a maioria dos casos. Adaptar o sistema ao gosto de cada vara vai contra essas ideias.","teSitua":{"termos":[{"termo":"eproc","significado":"sistema de processo judicial eletrônico adotado pelo TJSP a partir de 2025."},{"termo":"aderência à versão nacional","significado":"manutenção do sistema igual à versão usada nacionalmente, sem alterações locais que o fragmentem."},{"termo":"instrumentalidade","significado":"ideia de que o sistema é ferramenta a serviço do processo, e não um fim em si."}],"exemplo":"Um cartório pediu que o eproc ganhasse uma tela especial só para ele, do jeito que o chefe gosta. O pedido foi negado, porque o sistema deve seguir a versão nacional e priorizar soluções úteis para a maioria das unidades."}},{"id":"aut.legislacao_tj.eproc_963.0002","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 963/2025, pelo princípio do pragmatismo e efetividade, as definições de regras e evoluções do eproc seguirão a lógica do impacto amplo, priorizando soluções aplicáveis à maioria dos casos, sem foco em casos excepcionais ou preferências individuais.","gabarito":"C","explicacao":"É o texto do art. 2º, IV. O parágrafo único do art. 2º atribui a todos os usuários do sistema a responsabilidade pelo fomento e pela manutenção desses princípios.","fonte":"Resolução TJSP 963/2025, art. 2º, IV e parágrafo único","mastigado":"Certo. O eproc é pensado para resolver bem a maioria das situações. Casos raros ou o gosto pessoal de alguém não guiam as mudanças do sistema.","teSitua":{"termos":[{"termo":"pragmatismo","significado":"postura que privilegia soluções práticas e úteis."},{"termo":"impacto amplo","significado":"efeito que alcança a maior parte dos usuários e situações."}],"exemplo":"Ao decidir uma nova funcionalidade do eproc, o comitê escolheu a solução que atende a quase todas as varas cíveis, em vez de uma alternativa pensada para um único tipo raro de processo."}},{"id":"aut.legislacao_tj.eproc_963.0003","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Resolução TJSP nº 963/2025, a governança do sistema eproc será exercida pelos seguintes órgãos:","alternativas":{"A":"Comitê Gestor do eproc (CGe), Núcleo de Gestão Negocial (NGN) e Núcleo de Gestão Técnica (NGT).","B":"Órgão Especial, Conselho Superior da Magistratura e Corregedoria Geral da Justiça.","C":"Secretaria de Tecnologia da Informação, Secretaria de Gestão de Pessoas e Comitê Interinstitucional.","D":"Comitê Gestor do eproc e Comitê Interinstitucional, apenas.","E":"Presidência, Vice-Presidência e Núcleo de Gestão Técnica."},"gabarito":"A","explicacao":"O art. 4º atribui a governança ao Comitê Gestor do eproc (CGe), ao Núcleo de Gestão Negocial (NGN) e ao Núcleo de Gestão Técnica (NGT). O Comitê Interinstitucional (art. 8º) cuida da interlocução com entidades externas e não integra o rol do art. 4º.","explicacoes":{"A":"Correta: art. 4º, I a III.","B":"Esses órgãos não constam do art. 4º.","C":"Essas secretarias integram os núcleos, mas não são os órgãos de governança; o Comitê Interinstitucional trata de demandas externas (art. 8º).","D":"Faltam o NGN e o NGT, e o Comitê Interinstitucional não está no art. 4º.","E":"Presidência e Vice-Presidência não estão no rol do art. 4º."},"fonte":"Resolução TJSP 963/2025, arts. 4º e 8º","mastigado":"A resposta é a letra A. Três órgãos cuidam do eproc: um comitê gestor, que coordena, e dois núcleos que o apoiam, um pela visão do negócio e outro pela visão da tecnologia.","teSitua":{"termos":[{"termo":"governança","significado":"conjunto de órgãos e regras que dirigem e controlam o sistema."},{"termo":"Gestão Negocial","significado":"visão das regras de trabalho e das necessidades das unidades que usam o sistema."},{"termo":"Gestão Técnica","significado":"visão tecnológica, ligada à infraestrutura e à programação do sistema."}],"exemplo":"Uma nova regra de intimação no eproc foi discutida pelo Núcleo de Gestão Negocial, que analisou o impacto no trabalho dos cartórios, e pelo Núcleo de Gestão Técnica, que avaliou a viabilidade. A decisão final ficou com o Comitê Gestor."}},{"id":"aut.legislacao_tj.eproc_963.0004","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a Resolução TJSP nº 963/2025, o Comitê Gestor do eproc (CGe)","alternativas":{"A":"é o órgão coordenador da governança e será composto por, no mínimo, um Juiz assessor da Presidência, um da Vice-Presidência e um da Corregedoria Geral da Justiça.","B":"é composto exclusivamente por servidores da Secretaria de Tecnologia da Informação.","C":"tem composição e funcionamento regulados por lei estadual.","D":"é o único canal pelo qual advogados podem apresentar demandas sobre o sistema.","E":"é composto por desembargadores eleitos pelo Órgão Especial."},"gabarito":"A","explicacao":"Pelo art. 5º, o CGe coordena a governança e é interlocutor das demandas locais a serem incorporadas à versão nacional; compõe-se de, no mínimo, um juiz assessor da Presidência, um da Vice-Presidência e um da Corregedoria (§ 1º); sua composição, atribuições e funcionamento são regulados por Provimento do Conselho Superior da Magistratura (§ 2º). Demandas de usuários externos vão ao Comitê Interinstitucional (art. 8º, parágrafo único).","explicacoes":{"A":"Correta: art. 5º, caput e § 1º.","B":"O CGe tem juízes assessores; servidores da STI integram o NGT (art. 7º).","C":"A regulamentação é por Provimento do Conselho Superior da Magistratura (§ 2º).","D":"Os externos usam exclusivamente o Comitê Interinstitucional (art. 8º).","E":"A composição mínima é de juízes assessores, não de desembargadores eleitos."},"fonte":"Resolução TJSP 963/2025, art. 5º, §§ 1º e 2º","mastigado":"A resposta é a letra A. O comitê que coordena o eproc tem pelo menos três juízes assessores: um da Presidência, um da Vice-Presidência e um da Corregedoria. As regras detalhadas dele saem em provimento do Conselho Superior da Magistratura.","teSitua":{"termos":[{"termo":"Juiz assessor","significado":"juiz designado para auxiliar diretamente um órgão de direção do Tribunal."},{"termo":"Corregedoria Geral da Justiça","significado":"órgão que orienta e fiscaliza os serviços judiciais de primeira instância."},{"termo":"Vice-Presidência","significado":"órgão de direção do Tribunal, ocupado pelo Vice-Presidente, que auxilia e substitui o Presidente."}],"exemplo":"O CGe do TJSP foi formado com a juíza assessora Renata, da Presidência, o juiz assessor Hélio, da Vice-Presidência, e a juíza assessora Lúcia, da Corregedoria. O funcionamento do comitê foi detalhado em provimento do Conselho Superior da Magistratura."}},{"id":"aut.legislacao_tj.eproc_963.0005","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":3,"enunciado":"Pela Resolução TJSP nº 963/2025, incumbe ao Núcleo de Gestão Técnica subsidiar o Comitê Gestor pela ótica negocial do sistema, e ao Núcleo de Gestão Negocial subsidiá-lo pela ótica tecnológica.","gabarito":"E","explicacao":"A afirmativa inverte as funções. O NGN subsidia o CGe pela ótica negocial (art. 6º) e é integrado por representantes das Secretarias de Governança de Sistemas, Primeira Instância, Judiciária, Gestão de Pessoas e da Corregedoria; o NGT subsidia pela ótica tecnológica (art. 7º) e tem, no mínimo, dois servidores da STI e um da Secretaria de Governança de Sistemas.","fonte":"Resolução TJSP 963/2025, arts. 6º e 7º","mastigado":"Errado. Os nomes já dizem tudo: o núcleo negocial cuida da visão de negócio, das regras de trabalho; o núcleo técnico cuida da visão da tecnologia. A afirmativa trocou um pelo outro.","teSitua":{"termos":[{"termo":"Núcleo de Gestão Técnica","significado":"grupo que analisa as demandas do eproc pela visão tecnológica."},{"termo":"Núcleo de Gestão Negocial","significado":"grupo que analisa as demandas do eproc pela visão das regras de trabalho."},{"termo":"ótica negocial","significado":"ponto de vista das necessidades e rotinas das unidades que usam o sistema."}],"exemplo":"Para avaliar se o eproc poderia gerar certidões automaticamente, o NGN estudou como os cartórios as usam, e o NGT verificou se os servidores do Tribunal suportariam a nova função."}},{"id":"aut.legislacao_tj.eproc_963.0006","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com a Resolução TJSP nº 963/2025, os usuários externos poderão apresentar demandas relacionadas ao sistema eproc exclusivamente por meio do Comitê Interinstitucional, que exercerá o primeiro filtro de pertinência e relevância.","gabarito":"C","explicacao":"É o que diz o parágrafo único do art. 8º. O Comitê Interinstitucional é criado pela Presidência, por ato próprio, para a interlocução com as entidades externas.","fonte":"Resolução TJSP 963/2025, art. 8º e parágrafo único","mastigado":"Certo. Advogados, promotores e outros usuários de fora do Tribunal não levam pedidos sobre o eproc direto ao comitê gestor. Tudo passa pelo Comitê Interinstitucional, que faz uma primeira triagem.","teSitua":{"termos":[{"termo":"usuários externos","significado":"pessoas de fora do Tribunal que usam o sistema, como advogados e promotores."},{"termo":"Comitê Interinstitucional","significado":"grupo criado pela Presidência para dialogar com instituições externas sobre o eproc."},{"termo":"pertinência e relevância","significado":"ligação com o assunto e importância da demanda."}],"exemplo":"A seccional da OAB quis sugerir uma melhoria no peticionamento do eproc. A sugestão foi encaminhada ao Comitê Interinstitucional, que avaliou sua relevância antes de levá-la adiante."}},{"id":"aut.legislacao_tj.eproc_963.0007","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":2,"enunciado":"Implantado o sistema eproc em determinada competência de uma unidade judiciária, segundo a Resolução TJSP nº 963/2025,","alternativas":{"A":"o ajuizamento de novos processos nessa competência será admitido exclusivamente por meio do eproc.","B":"novos processos poderão ser ajuizados no eproc ou no sistema legado, à escolha do peticionante.","C":"todos os processos antigos migram automaticamente para o eproc no mesmo dia.","D":"os processos novos continuam sendo ajuizados no sistema legado por 90 dias.","E":"o cumprimento de sentença de processos do sistema legado passa a ser iniciado no eproc imediatamente."},"gabarito":"A","explicacao":"O art. 10 determina que, implantado o eproc em uma competência, novos processos só podem ser ajuizados nele. A implantação é gradativa, por competências e unidades, conforme cronograma da Presidência (art. 9º). Os processos anteriores continuam no sistema legado, salvo migração (art. 11), e o cumprimento de sentença de processo do legado nele se inicia até haver funcionalidade no eproc (art. 11, § 2º).","explicacoes":{"A":"Correta: art. 10, caput.","B":"Não há escolha: o eproc é exclusivo para os novos.","C":"A migração é gradativa e segue ato conjunto da Presidência e da Corregedoria (arts. 9º e 12).","D":"Não há esse prazo.","E":"O cumprimento de sentença de processo do legado começa no legado até haver funcionalidade específica (art. 11, § 2º)."},"fonte":"Resolução TJSP 963/2025, arts. 9º, 10 e 11","mastigado":"A resposta é a letra A. Quando o eproc chega a uma vara para certo tipo de processo, todo processo novo daquele tipo entra só pelo eproc. Os antigos continuam no sistema anterior até terminarem, a não ser que sejam migrados.","teSitua":{"termos":[{"termo":"competência","significado":"tipo de causa que a unidade julga, como cível, família ou criminal."},{"termo":"ajuizamento","significado":"ato de dar início a um processo na Justiça."},{"termo":"sistema legado","significado":"sistema antigo de processo eletrônico, usado antes do eproc."}],"exemplo":"O eproc foi implantado nas varas de família de Santo André em março. A advogada Telma tentou ajuizar um divórcio pelo sistema antigo em abril e não conseguiu: a partir da implantação, ações de família ali só entram pelo eproc."}},{"id":"aut.legislacao_tj.eproc_963.0008","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 963/2025, os processos ajuizados antes da implantação do sistema eproc, bem como os recursos, incidentes e processos dependentes ou conexos, continuarão tramitando no sistema legado até o seu encerramento, ressalvada a hipótese de migração.","gabarito":"C","explicacao":"É a regra do art. 11, caput. Nesses processos, petições intermediárias, incidentes e recursos só são protocolados pelo próprio sistema legado, salvo regulamentação da Presidência em contrário (§ 1º). A migração segue ato conjunto da Presidência e da Corregedoria (art. 12).","fonte":"Resolução TJSP 963/2025, art. 11, caput e § 1º; art. 12","mastigado":"Certo. O processo que começou no sistema antigo termina nele, junto com seus recursos e incidentes, a não ser que seja oficialmente migrado para o eproc.","teSitua":{"termos":[{"termo":"sistema legado","significado":"sistema antigo de processo eletrônico, usado antes do eproc."},{"termo":"incidentes","significado":"questões secundárias que surgem durante o processo e são resolvidas à parte."},{"termo":"processos dependentes ou conexos","significado":"processos ligados a outro por terem relação de origem, causa ou objeto."}],"exemplo":"O processo de cobrança de Danilo foi ajuizado em 2023, no sistema antigo. Mesmo com a chegada do eproc à vara, a petição de recurso dele é protocolada no sistema antigo, onde o processo segue até acabar."}},{"id":"aut.legislacao_tj.eproc_963.0009","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Resolução TJSP nº 963/2025, a identificação do sistema processual correto e a prática do respectivo ato processual competem ao cartório judicial, que deverá redirecionar as petições protocoladas no sistema errado.","gabarito":"E","explicacao":"O art. 14 atribui exclusivamente ao peticionante a identificação do sistema correto e a prática do ato, sob pena de não produção dos efeitos jurídicos. Não há dever do cartório de redirecionar petições.","fonte":"Resolução TJSP 963/2025, art. 14","mastigado":"Errado. Quem peticiona é que tem de saber se o processo está no eproc ou no sistema antigo. Se protocolar no lugar errado, a petição não produz efeito, e o cartório não tem obrigação de consertar.","teSitua":{"termos":[{"termo":"sistema processual","significado":"sistema eletrônico em que o processo tramita, como o eproc ou o sistema legado."},{"termo":"peticionante","significado":"pessoa que apresenta a petição, geralmente o advogado."}],"exemplo":"O advogado Rogério protocolou a contestação no eproc, mas o processo do cliente tramitava no sistema antigo. Como a escolha do sistema é responsabilidade dele, a contestação não produziu efeitos e o prazo correu."}},{"id":"aut.legislacao_tj.eproc_963.0010","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Resolução TJSP nº 963/2025, são usuários internos do sistema eproc","alternativas":{"A":"magistrados, servidores, estagiários, servidores cedidos por outros órgãos, voluntários e outros auxiliares autorizados pelo Tribunal.","B":"partes, advogados e membros do Ministério Público.","C":"peritos, tradutores e leiloeiros.","D":"defensores públicos e procuradores.","E":"administradores judiciais de recuperação judicial e falência."},"gabarito":"A","explicacao":"O art. 15, I, define os usuários internos. Os externos (inciso II) são partes, advogados, procuradores, defensores públicos, membros do Ministério Público, policiais, peritos, tradutores, intérpretes, leiloeiros, administradores de recuperação judicial ou falência e outros interessados. O acesso às funcionalidades depende do perfil atribuído (parágrafo único).","explicacoes":{"A":"Correta: art. 15, I.","B":"São usuários externos (art. 15, II).","C":"São usuários externos (art. 15, II).","D":"São usuários externos (art. 15, II).","E":"São usuários externos (art. 15, II)."},"fonte":"Resolução TJSP 963/2025, art. 15","mastigado":"A resposta é a letra A. Usuário interno é quem trabalha dentro do Tribunal: juízes, servidores, estagiários, cedidos e voluntários. Advogados, promotores, peritos e partes são usuários externos.","teSitua":{"termos":[{"termo":"usuários internos","significado":"pessoas que trabalham para o Tribunal e usam o sistema."},{"termo":"servidores cedidos","significado":"servidores de outro órgão emprestados para trabalhar no Tribunal."},{"termo":"leiloeiros","significado":"profissionais que conduzem a venda de bens em leilão judicial."}],"exemplo":"No cartório de Bianca, ela, o estagiário Lucas e uma servidora cedida pela Prefeitura acessam o eproc como usuários internos. Já o perito Moacir, que entrega laudos nos processos, é usuário externo."}},{"id":"aut.legislacao_tj.eproc_963.0011","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"O chefe de cartório, que possui perfil de gestor do sistema eproc, foi informado de que um escrevente encerrou o vínculo com a unidade. Segundo a Resolução TJSP nº 963/2025, o gestor deverá interromper o acesso desse usuário","alternativas":{"A":"em até 24 horas, sob pena de responsabilidade.","B":"em até 5 dias úteis.","C":"em até 48 horas, apenas se houver pedido do próprio usuário.","D":"em até 30 dias, quando da atualização periódica dos perfis.","E":"somente após autorização da Secretaria de Tecnologia da Informação."},"gabarito":"A","explicacao":"O art. 16, § 1º, impõe ao usuário interno com perfil de gestor do sistema, ou a seu substituto, gerenciar o acesso dos subordinados e interrompê-lo em até 24 horas após o encerramento do vínculo com a unidade, sob pena de responsabilidade. O credenciamento dos demais usuários internos cabe à chefia com perfil de gestor (inciso II).","explicacoes":{"A":"Correta: art. 16, § 1º.","B":"O prazo é de até 24 horas.","C":"O prazo é de até 24 horas, independentemente de pedido.","D":"O prazo é de até 24 horas.","E":"A obrigação é do próprio gestor, sem depender da STI."},"fonte":"Resolução TJSP 963/2025, art. 16, II e § 1º","mastigado":"A resposta é a letra A. Saiu da unidade, perde o acesso. O chefe com perfil de gestor tem até vinte e quatro horas para cortar o login de quem deixou o setor, e responde se não fizer isso.","teSitua":{"termos":[{"termo":"perfil de gestor do sistema","significado":"nível de acesso que permite cadastrar e gerenciar outros usuários na unidade."},{"termo":"encerramento do vínculo","significado":"fim da ligação do servidor com aquela unidade, por remoção, exoneração ou outro motivo."}],"exemplo":"O escrevente Wilson foi removido para outra comarca na segunda-feira de manhã. A chefe Patrícia, gestora do eproc no cartório, retirou o acesso dele à unidade na mesma tarde, dentro do prazo de vinte e quatro horas."}},{"id":"aut.legislacao_tj.eproc_963.0012","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":4,"enunciado":"O sistema eproc ficou indisponível por 90 minutos, entre 14h e 15h30, no último dia de um prazo, por falha nos equipamentos do Tribunal. Conforme a Resolução TJSP nº 963/2025, esse prazo","alternativas":{"A":"será prorrogado para o dia útil seguinte à retomada do funcionamento.","B":"não será prorrogado, pois a indisponibilidade não ocorreu após as 23h.","C":"será prorrogado por 90 minutos, apenas.","D":"será prorrogado por 5 dias úteis.","E":"não será prorrogado, pois a indisponibilidade foi inferior a 2 horas."},"gabarito":"A","explicacao":"O art. 21 prorroga para o dia útil seguinte à retomada os prazos que vencem no dia da indisponibilidade quando ela for superior a 60 minutos, ininterruptos ou não, entre 12h e 23h (I), ou ocorrer por qualquer período entre 23h01 e 00h00 (II). Não há prorrogação para indisponibilidade entre 00h01 e 11h59, em feriados ou fins de semana (§ 1º), nem quando a falha é do equipamento ou da conexão do usuário (§ 3º).","explicacoes":{"A":"Correta: art. 21, I.","B":"Indisponibilidade superior a 60 minutos entre 12h e 23h também gera prorrogação.","C":"A prorrogação é para o dia útil seguinte à retomada.","D":"A prorrogação é para o dia útil seguinte à retomada.","E":"O limite é de 60 minutos, não de 2 horas."},"fonte":"Resolução TJSP 963/2025, art. 21, I e II, §§ 1º e 3º","mastigado":"A resposta é a letra A. Se o sistema do Tribunal cair por mais de uma hora entre meio-dia e onze da noite, no último dia do prazo, o prazo passa para o próximo dia útil. De madrugada e de manhã, a queda não muda o prazo.","teSitua":{"termos":[{"termo":"indisponibilidade","significado":"interrupção do acesso ao sistema por falha ou manutenção dos equipamentos do Tribunal."},{"termo":"prorrogado","significado":"estendido para uma data posterior à original."},{"termo":"retomada do funcionamento","significado":"volta do sistema a operar normalmente."}],"exemplo":"O prazo da advogada Dalva para recorrer vencia numa quarta-feira. O eproc ficou fora do ar das 14h às 15h30 por falha do Tribunal, certificada pelo administrador. O prazo dela passou para quinta-feira, primeiro dia útil após a volta do sistema."}},{"id":"aut.legislacao_tj.eproc_963.0013","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Resolução TJSP nº 963/2025, quando o ato for praticado no eproc para atender prazo processual, será considerado tempestivo aquele","alternativas":{"A":"transmitido integralmente até as 24 horas do seu último dia, considerado o horário oficial de Brasília.","B":"cuja transmissão tenha sido iniciada até as 24 horas do último dia, ainda que concluída depois.","C":"transmitido até as 18 horas do último dia, encerramento do expediente forense.","D":"registrado pelo relógio do computador do remetente até as 24 horas do último dia.","E":"transmitido até as 23h59 do dia seguinte ao do vencimento."},"gabarito":"A","explicacao":"O art. 26, § 1º, considera tempestivo o ato transmitido integralmente até as 24 horas do último dia; o § 2º manda usar o horário oficial de Brasília; o § 3º afasta, para tempestividade, o horário de início da conexão, de acesso ao eproc ou os registrados pelos equipamentos do remetente. Considera-se realizado o ato no dia e hora do seu envio ao sistema (caput).","explicacoes":{"A":"Correta: art. 26, §§ 1º e 2º.","B":"A transmissão deve estar concluída até as 24 horas; o horário de início não conta (§ 3º).","C":"O limite é 24 horas, não o fim do expediente.","D":"O horário do equipamento do remetente não é considerado (§ 3º).","E":"O prazo vence no próprio último dia."},"fonte":"Resolução TJSP 963/2025, art. 26, caput e §§ 1º a 3º","mastigado":"A resposta é a letra A. No último dia do prazo, a petição tem de chegar inteira ao eproc até a meia-noite, pelo horário de Brasília. Não adianta ter começado a enviar antes da meia-noite nem mostrar o relógio do próprio computador.","teSitua":{"termos":[{"termo":"tempestivo","significado":"praticado dentro do prazo fixado para o ato."},{"termo":"transmitido integralmente","significado":"enviado por completo e recebido pelo sistema."},{"termo":"horário oficial de Brasília","significado":"horário de referência nacional, usado pelo sistema para registrar os atos."}],"exemplo":"O advogado Ícaro começou a enviar o recurso às 23h58 do último dia, mas o arquivo só terminou de subir às 00h03. Como a transmissão não foi concluída até as 24 horas, o recurso foi considerado fora do prazo."}},{"id":"aut.legislacao_tj.eproc_963.0014","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 963/2025, os eventos registrados na movimentação do processo no eproc equivalem à certificação da prática do ato processual para todos os fins de direito, de modo que eventos como abertura de conclusão, publicação e trânsito em julgado, gerados pelo sistema, não serão objeto de certificação manual pelas unidades, salvo interrupção na funcionalidade de geração automática e apenas durante esse período.","gabarito":"C","explicacao":"É o que dispõem o art. 28, caput e § 1º. O § 2º dispensa o envio, por mensagens eletrônicas, de eventos realizados pelo sistema. Toda movimentação registra data, horário e usuário que lhe deu causa (art. 27).","fonte":"Resolução TJSP 963/2025, arts. 27 e 28","mastigado":"Certo. No eproc, o próprio registro do evento vale como certidão. O cartório não precisa lavrar certidão à mão dizendo que houve conclusão, publicação ou trânsito em julgado. Só faz isso se a geração automática falhar, e enquanto durar a falha.","teSitua":{"termos":[{"termo":"certificação","significado":"ato do servidor que atesta oficialmente que algo aconteceu no processo."},{"termo":"abertura de conclusão","significado":"envio do processo ao juiz para decisão."},{"termo":"trânsito em julgado","significado":"momento em que a decisão se torna definitiva, sem recurso possível."}],"exemplo":"No cartório de Ana, quando o processo vai concluso ao juiz, o eproc registra o evento automaticamente. Ela não precisa redigir certidão de conclusão. Só faria isso se a função automática estivesse com defeito."}},{"id":"aut.legislacao_tj.eproc_963.0015","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Havendo necessidade de documento comprobatório de qualquer evento do processo eletrônico no eproc, a parte, segundo a Resolução TJSP nº 963/2025, deverá fazer uso da funcionalidade","alternativas":{"A":"“certidão narratória”, que terá a mesma validade de certidão de objeto e pé para todos os fins de direito.","B":"“certidão de distribuição”, emitida exclusivamente pela Corregedoria.","C":"“relatório de movimentação”, sem valor de certidão.","D":"“print” da tela, que substitui qualquer certidão.","E":"“termo de juntada”, a ser assinado pelo escrivão."},"gabarito":"A","explicacao":"O parágrafo único do art. 31 indica a funcionalidade certidão narratória, com a mesma validade de certidão de objeto e pé. A emissão de certidões de distribuição será disciplinada por ato conjunto da Presidência e da Corregedoria (caput). A impressão de tela vale como comprovante apenas da juntada de petição intermediária (art. 26, § 4º).","explicacoes":{"A":"Correta: art. 31, parágrafo único.","B":"A certidão de distribuição é outra coisa e será disciplinada por ato conjunto da Presidência e da Corregedoria.","C":"A funcionalidade indicada é a certidão narratória, com valor de certidão.","D":"A impressão de tela só serve como comprovante de juntada de petição intermediária (art. 26, § 4º).","E":"Não é a funcionalidade prevista."},"fonte":"Resolução TJSP 963/2025, art. 31 e parágrafo único; art. 26, § 4º","mastigado":"A resposta é a letra A. Para provar o que aconteceu no processo eletrônico, a parte usa a certidão narratória do próprio eproc, que vale o mesmo que a tradicional certidão de objeto e pé.","teSitua":{"termos":[{"termo":"certidão narratória","significado":"documento gerado pelo sistema que narra os eventos do processo."},{"termo":"certidão de objeto e pé","significado":"certidão que informa o assunto do processo e a fase em que ele se encontra."},{"termo":"certidão de distribuição","significado":"documento que informa se há processos distribuídos em nome de alguém."}],"exemplo":"Joana precisava comprovar ao banco que seu processo de inventário estava em andamento. Ela gerou no eproc a certidão narratória, que o banco aceitou com o mesmo valor de uma certidão de objeto e pé."}},{"id":"aut.legislacao_tj.eproc_963.0016","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Interposto agravo de instrumento contra decisão proferida em processo que tramita no eproc, de acordo com a Resolução TJSP nº 963/2025,","alternativas":{"A":"ele será interposto no sistema de primeiro grau, por link apropriado, e enviado automaticamente ao segundo grau, cabendo ao agravante juntar apenas a petição com as razões, dispensadas as peças do processo de origem.","B":"o agravante deverá juntar cópia integral do processo de primeiro grau.","C":"ele será interposto diretamente no segundo grau, ainda que o agravante seja parte na origem.","D":"ele será processado nos próprios autos de primeiro grau, sem nova numeração.","E":"o agravante deverá protocolá-lo em meio físico no Tribunal."},"gabarito":"A","explicacao":"O art. 34 prevê a interposição no sistema de primeiro grau, por link apropriado, com envio automático ao segundo grau, onde é processado em autos apartados com nova numeração. O agravante junta apenas a petição com as razões, indicando a decisão agravada, dispensadas as peças da origem (§ 1º), e demonstra a tempestividade pelo evento da intimação (§ 2º). Só quem não é parte na origem interpõe direto no tribunal (§ 4º).","explicacoes":{"A":"Correta: art. 34, caput e § 1º.","B":"A juntada de peças do processo de origem é dispensada (§ 1º).","C":"A interposição direta no tribunal é só para quem não é parte na origem (§ 4º).","D":"O agravo é processado em autos apartados, com nova numeração.","E":"Não há protocolo físico; o meio físico é exceção do art. 41."},"fonte":"Resolução TJSP 963/2025, art. 34, caput e §§ 1º, 2º e 4º","mastigado":"A resposta é a letra A. No eproc, o agravo é apresentado pelo próprio processo de primeiro grau, por um link, e o sistema o manda sozinho ao Tribunal. Basta a petição com as razões; não é preciso anexar cópias do processo.","teSitua":{"termos":[{"termo":"agravo de instrumento","significado":"recurso contra decisão do juiz tomada no meio do processo, julgado pelo Tribunal."},{"termo":"autos apartados","significado":"processo separado do principal, com numeração própria."},{"termo":"razões","significado":"argumentos que fundamentam o recurso."}],"exemplo":"O juiz negou o pedido de urgência do cliente da advogada Sueli. Ela abriu o processo no eproc, clicou no link de agravo e anexou só a petição com as razões, indicando o evento da decisão. O sistema enviou o recurso ao Tribunal automaticamente."}},{"id":"aut.legislacao_tj.eproc_963.0017","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 963/2025, as petições iniciais, incidentes, cartas, mandados, recursos e demais atos serão distribuídos automaticamente pelo sistema, e, se necessário, a redistribuição em primeiro grau será feita diretamente no sistema pelo juízo que a determinar.","gabarito":"C","explicacao":"É o que diz o art. 25, caput e § 2º. A análise de prevenção e outros filtros não automáticos segue atos próprios (§ 1º).","fonte":"Resolução TJSP 963/2025, art. 25, caput e §§ 1º e 2º","mastigado":"Certo. No eproc, a distribuição é feita pelo próprio sistema, sem sorteio manual. Se o juiz decidir que o processo deve ir para outra vara de primeiro grau, a própria vara faz a redistribuição no sistema.","teSitua":{"termos":[{"termo":"distribuídos","significado":"repartidos entre os juízos competentes, definindo onde cada processo vai tramitar."},{"termo":"redistribuição","significado":"nova distribuição do processo a outro juízo."},{"termo":"cartas","significado":"pedidos de um juízo a outro para a prática de atos, como a carta precatória."}],"exemplo":"Uma ação foi distribuída automaticamente pelo eproc à 1ª Vara Cível. O juiz percebeu que a causa era da Vara da Fazenda Pública e determinou a redistribuição, que o próprio cartório fez no sistema."}},{"id":"aut.legislacao_tj.eproc_963.0018","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Identificado uso inadequado do sistema eproc por qualquer usuário, como ataque cibernético ou uso desproporcional dos recursos computacionais, a Resolução TJSP nº 963/2025 determina","alternativas":{"A":"o bloqueio preventivo do usuário, temporário e total, devendo a STI contatá-lo pelo e-mail do cadastro e, se for advogado, comunicar a respectiva Seccional da OAB.","B":"a exclusão definitiva do usuário, sem possibilidade de reativação.","C":"apenas advertência por e-mail, sem bloqueio.","D":"o bloqueio parcial, restrito às funcionalidades de consulta, por 30 dias.","E":"a instauração imediata de processo criminal pela Presidência."},"gabarito":"A","explicacao":"O art. 37 define uso inadequado e determina, no parágrafo único, o bloqueio preventivo, temporário e total. O art. 38 manda a STI contatar o usuário pelo e-mail do cadastro para eventual pedido de reativação e, sendo advogado, procurador, defensor ou membro do MP, comunicar a Seccional da OAB ou a corregedoria correspondente.","explicacoes":{"A":"Correta: arts. 37, parágrafo único, e 38.","B":"O bloqueio é temporário, com possibilidade de reativação.","C":"Há bloqueio preventivo.","D":"O bloqueio é total, não parcial.","E":"A resolução prevê bloqueio e comunicações, não processo criminal imediato."},"fonte":"Resolução TJSP 963/2025, arts. 37 e 38","mastigado":"A resposta é a letra A. Quem sobrecarrega ou ataca o eproc é bloqueado na hora, de forma total, mas temporária. A área de tecnologia avisa o usuário por e-mail e, se for advogado, comunica também a OAB.","teSitua":{"termos":[{"termo":"ataque cibernético","significado":"ação maliciosa contra sistemas de computador para invadi-los ou derrubá-los."},{"termo":"bloqueio preventivo","significado":"suspensão imediata do acesso para evitar danos, antes de decisão final."},{"termo":"Seccional da OAB","significado":"unidade estadual da Ordem dos Advogados do Brasil."}],"exemplo":"Um escritório usou um programa que fazia milhares de consultas por minuto ao eproc, deixando o sistema lento. O usuário do advogado responsável foi bloqueado de forma total e temporária, a STI o avisou por e-mail e a OAB-SP foi comunicada."}},{"id":"aut.legislacao_tj.eproc_963.0019","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 963/2025, em caso de indisponibilidade absoluta do sistema eproc, devidamente certificada, a petição poderá ser protocolizada em meio físico para distribuição manual","alternativas":{"A":"para evitar perecimento de direito ou ofensa à liberdade de locomoção, com posterior digitalização e inserção no sistema pelo juízo a que for distribuída.","B":"em qualquer caso, a critério do advogado.","C":"somente nos processos cíveis de valor inferior a 40 salários mínimos.","D":"desde que o próprio advogado digitalize e insira a petição no sistema no dia seguinte.","E":"apenas se a indisponibilidade durar mais de 5 dias úteis."},"gabarito":"A","explicacao":"O art. 41 admite o protocolo físico, em indisponibilidade absoluta certificada, para evitar perecimento de direito ou ofensa à liberdade de locomoção, cabendo ao juízo a que for distribuída a petição a posterior digitalização e inserção no sistema.","explicacoes":{"A":"Correta: art. 41.","B":"A hipótese é restrita a perecimento de direito ou ofensa à liberdade de locomoção.","C":"Não há esse critério de valor.","D":"A digitalização e a inserção cabem ao juízo.","E":"Não há esse prazo mínimo; exige-se indisponibilidade absoluta certificada."},"fonte":"Resolução TJSP 963/2025, art. 41","mastigado":"A resposta é a letra A. Se o eproc estiver totalmente fora do ar e houver risco de perder um direito ou de alguém continuar preso indevidamente, a petição pode ser entregue em papel. Depois, o próprio juízo digitaliza e coloca no sistema.","teSitua":{"termos":[{"termo":"indisponibilidade absoluta","significado":"queda total do sistema, sem nenhum acesso possível."},{"termo":"perecimento de direito","significado":"perda definitiva de um direito por não ter sido exercido a tempo."},{"termo":"liberdade de locomoção","significado":"direito de ir e vir, protegido, por exemplo, pelo habeas corpus."}],"exemplo":"Numa sexta-feira à noite, o eproc ficou totalmente fora do ar, com certificação do Tribunal. A advogada Rose precisava pedir a soltura de um cliente preso ilegalmente. Ela protocolou o habeas corpus em papel, e o juízo depois digitalizou e lançou o pedido no sistema."}},{"id":"aut.legislacao_tj.eproc_963.0020","subtopico":"legislacao_tj.resolucoes.eproc_963","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com a Resolução TJSP nº 963/2025, é diretriz geral de uso do sistema que os usuários se abstenham de práticas que causem sobrecarga ao sistema, incluindo o uso não autorizado, por usuários externos, de robôs de consulta.","gabarito":"C","explicacao":"É a diretriz do art. 18, V. O descumprimento das diretrizes do art. 18 sujeita o usuário às sanções administrativas, civis, criminais e processuais cabíveis, inclusive as dos arts. 37 e seguintes (parágrafo único).","fonte":"Resolução TJSP 963/2025, art. 18, V e parágrafo único","mastigado":"Certo. O usuário de fora do Tribunal não pode usar, sem autorização, programas automáticos que fazem consultas em massa ao eproc, porque isso deixa o sistema lento para todos.","teSitua":{"termos":[{"termo":"sobrecarga","significado":"excesso de uso que prejudica o funcionamento do sistema."},{"termo":"robôs de consulta","significado":"programas automáticos que fazem buscas repetidas no sistema sem intervenção humana."}],"exemplo":"Uma empresa de informações jurídicas instalou um robô que consultava automaticamente milhares de processos no eproc por hora, sem autorização. Essa prática viola as diretrizes de uso e pode levar ao bloqueio do usuário."}},{"id":"aut.legislacao_tj.funcao_correcional.0001","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (Tomo I), a função correcional consiste na orientação, reorganização e fiscalização dos órgãos e serviços judiciários de primeira instância, e é exercida, no Estado de São Paulo,","alternativas":{"A":"pelo Corregedor Geral da Justiça e, nos limites de suas atribuições, pelos Juízes de Primeiro Grau.","B":"exclusivamente pelo Corregedor Geral da Justiça.","C":"pelo Presidente do Tribunal de Justiça e pelo Conselho Nacional de Justiça.","D":"pelos escrivães judiciais de cada ofício.","E":"pelo Ministério Público, com auxílio dos juízes."},"gabarito":"A","explicacao":"O art. 5º define a função correcional como orientação, reorganização e fiscalização dos órgãos e serviços judiciários de primeira instância, da polícia judiciária, dos estabelecimentos prisionais e de outros sujeitos ao Judiciário por lei, exercida pelo Corregedor Geral da Justiça e, nos limites de suas atribuições, pelos Juízes de Primeiro Grau. No seu desempenho, podem ser editadas ordens de serviço e sancionadas infrações após regular procedimento (§ 1º).","explicacoes":{"A":"Correta: art. 5º, caput.","B":"Os juízes de primeiro grau também exercem a função correcional, nos limites de suas atribuições.","C":"Não é a previsão das Normas.","D":"O escrivão auxilia nas correições (art. 10), mas não exerce a função correcional.","E":"O Ministério Público não exerce a função correcional do Judiciário."},"fonte":"NSCGJ, Tomo I, art. 5º, caput e § 1º (consolidação de 2017)","mastigado":"A resposta é a letra A. Fiscalizar e orientar os cartórios e serviços de primeira instância é tarefa do Corregedor Geral da Justiça, mas cada juiz também faz isso nas unidades sob sua responsabilidade, como corregedor permanente.","teSitua":{"termos":[{"termo":"função correcional","significado":"atividade de orientar, organizar e fiscalizar os serviços judiciais."},{"termo":"reorganização","significado":"nova organização de um serviço para que funcione melhor."},{"termo":"primeira instância","significado":"primeiro nível da Justiça, onde atuam os juízes nas varas."}],"exemplo":"A juíza Paula, corregedora permanente do cartório da 1ª Vara Cível de Marília, verificou atrasos na expedição de mandados e editou ordem de serviço para corrigir o problema. Ela exerceu a função correcional nos limites de suas atribuições."}},{"id":"aut.legislacao_tj.funcao_correcional.0002","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, as ordens de serviço e demais atos administrativos editados pelo Juiz Corregedor Permanente serão encaminhados à Corregedoria Geral da Justiça para revisão hierárquica.","gabarito":"C","explicacao":"É a regra do art. 5º, § 2º. Também as consultas sobre aplicação ou interpretação das Normas são apreciadas pelo Juiz Corregedor Permanente, que submete suas decisões à Corregedoria Geral a requerimento do interessado ou, de ofício, se houver dúvida fundada (§ 3º).","fonte":"NSCGJ, Tomo I, art. 5º, §§ 2º e 3º (consolidação de 2017)","mastigado":"Certo. Quando o juiz corregedor da comarca baixa uma ordem de serviço para os cartórios, ela vai para a Corregedoria Geral, que pode revê-la. Assim as regras locais não contrariam as regras gerais do Estado.","teSitua":{"termos":[{"termo":"ordens de serviço","significado":"determinações escritas que organizam o trabalho de uma unidade."},{"termo":"Juiz Corregedor Permanente","significado":"juiz encarregado de fiscalizar, de forma contínua, determinado cartório ou serviço."},{"termo":"revisão hierárquica","significado":"nova análise feita pela autoridade superior, que pode manter ou alterar o ato."}],"exemplo":"O juiz corregedor permanente de Bauru editou ordem de serviço sobre o horário de atendimento no balcão do cartório. Uma cópia foi enviada à Corregedoria Geral da Justiça, que examinou se a ordem estava de acordo com as normas gerais."}},{"id":"aut.legislacao_tj.funcao_correcional.0003","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente tem dúvida sobre a interpretação de um artigo das Normas de Serviço. Conforme as Normas da Corregedoria Geral da Justiça, consultas sobre aplicação ou interpretação dessas normas","alternativas":{"A":"serão apreciadas pelo Juiz Corregedor Permanente, que submeterá sua decisão à Corregedoria Geral da Justiça a requerimento do interessado ou, de ofício, se houver dúvida fundada devidamente justificada.","B":"devem ser dirigidas diretamente ao Presidente do Tribunal.","C":"são decididas pelo escrivão judicial, sem recurso.","D":"devem ser feitas ao Conselho Nacional de Justiça.","E":"são sempre decididas pelo Corregedor Geral, sem passar pelo juiz."},"gabarito":"A","explicacao":"O art. 5º, § 3º, atribui ao Juiz Corregedor Permanente a apreciação das consultas, que submete sua decisão à Corregedoria Geral a requerimento do interessado ou de ofício, se houver dúvida fundada devidamente justificada.","explicacoes":{"A":"Correta: art. 5º, § 3º.","B":"Não é a regra das Normas.","C":"O escrivão não decide as consultas.","D":"Não é a regra das Normas.","E":"A consulta passa primeiro pelo Juiz Corregedor Permanente."},"fonte":"NSCGJ, Tomo I, art. 5º, § 3º (consolidação de 2017)","mastigado":"A resposta é a letra A. A dúvida sobre as Normas vai primeiro ao juiz corregedor da unidade. Ele decide e, se o interessado pedir ou se a dúvida for séria, manda a decisão para a Corregedoria Geral confirmar.","teSitua":{"termos":[{"termo":"consultas","significado":"pedidos de orientação sobre como aplicar uma norma."},{"termo":"dúvida fundada","significado":"dúvida séria, com base razoável, e não mera curiosidade."},{"termo":"de ofício","significado":"por iniciativa própria, sem pedido de ninguém."}],"exemplo":"A escrevente Rita não sabia como aplicar uma regra sobre arquivamento. O escrivão levou a consulta ao juiz corregedor permanente, que decidiu e, por haver dúvida fundada, submeteu a decisão à Corregedoria Geral da Justiça."}},{"id":"aut.legislacao_tj.funcao_correcional.0004","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, a correição extraordinária consiste em","alternativas":{"A":"fiscalização excepcional, realizada a qualquer momento e sem prévio anúncio, que poderá ser geral ou parcial.","B":"fiscalização anual, realizada de preferência em dezembro, anunciada por edital.","C":"fiscalização direcionada à verificação do saneamento de irregularidades, sem caráter excepcional.","D":"fiscalização feita exclusivamente pela via eletrônica.","E":"fiscalização realizada apenas a pedido das partes."},"gabarito":"A","explicacao":"O art. 6º prevê a função correcional permanente, as correições ordinárias e extraordinárias e as visitas correcionais. A correição extraordinária é a fiscalização excepcional, a qualquer momento e sem prévio anúncio, geral ou parcial (§ 2º). A ordinária é a fiscalização prevista nas normas (§ 1º), anual e anunciada por edital (art. 8º); a visita correcional verifica a regularidade de funcionamento e o saneamento de irregularidades (§ 3º).","explicacoes":{"A":"Correta: art. 6º, § 2º.","B":"Isso descreve a correição ordinária (art. 8º).","C":"Isso se aproxima da visita correcional (art. 6º, § 3º).","D":"A correição virtual é implantada gradativamente (§ 5º), mas não define a extraordinária.","E":"Não há essa restrição."},"fonte":"NSCGJ, Tomo I, art. 6º (consolidação de 2017)","mastigado":"A resposta é a letra A. A correição extraordinária é a fiscalização surpresa: acontece quando for necessário, sem aviso, e pode olhar a unidade inteira ou só uma parte. A ordinária, ao contrário, é anual e anunciada.","teSitua":{"termos":[{"termo":"correição extraordinária","significado":"fiscalização excepcional e sem aviso prévio de uma unidade judicial."},{"termo":"prévio anúncio","significado":"aviso dado com antecedência aos fiscalizados."},{"termo":"geral ou parcial","significado":"abrangendo todos os serviços da unidade ou apenas parte deles."}],"exemplo":"Após várias reclamações de advogados sobre atrasos num cartório, a Corregedoria fez uma correição extraordinária sem avisar ninguém, examinando apenas os processos de execução da unidade."}},{"id":"aut.legislacao_tj.funcao_correcional.0005","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, a visita correcional consiste na fiscalização direcionada à verificação da regularidade de funcionamento da unidade, do saneamento de irregularidades constatadas em correições ou ao exame de algum aspecto da regularidade ou da continuidade dos serviços.","gabarito":"C","explicacao":"É a definição do art. 6º, § 3º. A visita correcional independe de edital, e dela se lança sucinto termo no livro de visitas e correições (art. 9º, § 1º).","fonte":"NSCGJ, Tomo I, art. 6º, § 3º; art. 9º, § 1º (consolidação de 2017)","mastigado":"Certo. A visita correcional é uma fiscalização mais focada: serve para ver se a unidade está funcionando bem ou se os problemas apontados numa correição foram corrigidos. Não precisa de edital.","teSitua":{"termos":[{"termo":"visita correcional","significado":"fiscalização pontual da unidade, sem necessidade de edital."},{"termo":"saneamento de irregularidades","significado":"correção dos problemas encontrados na fiscalização."}],"exemplo":"Na correição de dezembro, o juiz apontou que o cartório tinha muitos mandados sem cumprimento. Em março, fez uma visita correcional só para verificar se o problema havia sido resolvido."}},{"id":"aut.legislacao_tj.funcao_correcional.0006","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, as atas das correições e visitas serão encaminhadas à Corregedoria Geral da Justiça nos seguintes prazos:","alternativas":{"A":"correição ordinária, até 60 dias após realizada; correição extraordinária ou visita correcional, até 15 dias após realizada.","B":"correição ordinária, até 15 dias; correição extraordinária, até 60 dias.","C":"todas, até 30 dias após realizadas.","D":"correição ordinária, até 90 dias; visita correcional, até 30 dias.","E":"todas, no mesmo dia da realização."},"gabarito":"A","explicacao":"O art. 6º, § 4º, fixa 60 dias para a ata da correição ordinária (I) e 15 dias para a da correição extraordinária ou visita correcional (II).","explicacoes":{"A":"Correta: art. 6º, § 4º.","B":"Os prazos estão invertidos.","C":"Os prazos são diferentes para cada tipo.","D":"Não são os prazos previstos.","E":"Não há essa exigência."},"fonte":"NSCGJ, Tomo I, art. 6º, § 4º (consolidação de 2017)","mastigado":"A resposta é a letra A. A correição ordinária, mais ampla, dá mais tempo: sessenta dias para mandar a ata. Na extraordinária e na visita, o prazo é curto: quinze dias.","teSitua":{"termos":[{"termo":"atas","significado":"registros escritos do que foi verificado e determinado na fiscalização."},{"termo":"correição ordinária","significado":"fiscalização anual e prevista da unidade, anunciada por edital."}],"exemplo":"A juíza Márcia fez a correição ordinária do cartório em 10 de dezembro e enviou a ata à Corregedoria em 20 de janeiro, dentro dos sessenta dias. Já a visita correcional de abril teve a ata enviada em uma semana."}},{"id":"aut.legislacao_tj.funcao_correcional.0007","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o Corregedor Geral da Justiça, com aprovação do Conselho Superior da Magistratura, poderá alterar a designação do Corregedor Permanente por motivo de interesse público ou conveniência da administração; se não houver alteração no início do ano judiciário, prevalecerão as designações do ano anterior.","gabarito":"C","explicacao":"É o que dispõe o art. 7º, §§ 1º e 2º. A Corregedoria Permanente é exercida pelo juiz a quem a normatividade correcional cometer essa atribuição (caput).","fonte":"NSCGJ, Tomo I, art. 7º (consolidação de 2017)","mastigado":"Certo. A Corregedoria Geral pode trocar o juiz corregedor de uma unidade, com aval do Conselho Superior da Magistratura, quando for melhor para o serviço. Se nada mudar no começo do ano, continua valendo a designação anterior.","teSitua":{"termos":[{"termo":"Corregedor Permanente","significado":"juiz encarregado de fiscalizar, de forma contínua, determinado cartório ou serviço."},{"termo":"Conselho Superior da Magistratura","significado":"órgão de cúpula do TJSP com funções administrativas."},{"termo":"ano judiciário","significado":"período anual de funcionamento do Judiciário, que começa após o recesso."}],"exemplo":"Em janeiro, nenhuma nova designação foi publicada para os cartórios de Taubaté. Assim, cada juiz continuou como corregedor permanente das mesmas unidades do ano anterior."}},{"id":"aut.legislacao_tj.funcao_correcional.0008","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, o Juiz Corregedor Permanente efetuará correição ordinária em todas as serventias, repartições e estabelecimentos sujeitos à sua fiscalização","alternativas":{"A":"uma vez por ano, de preferência no mês de dezembro.","B":"duas vezes por ano, em junho e dezembro.","C":"uma vez a cada dois anos, em qualquer mês.","D":"mensalmente, sem necessidade de edital.","E":"apenas quando determinado pelo Corregedor Geral."},"gabarito":"A","explicacao":"O art. 8º determina a correição ordinária uma vez por ano, de preferência em dezembro, lavrando-se termo no livro próprio. O juiz segue o termo padrão disponibilizado pela Corregedoria Geral (§ 2º).","explicacoes":{"A":"Correta: art. 8º, caput.","B":"A correição ordinária é anual.","C":"A correição ordinária é anual.","D":"Mensal é a visita a estabelecimentos prisionais (art. 13); a correição ordinária exige edital (art. 8º, § 1º).","E":"A correição ordinária é obrigatória e anual."},"fonte":"NSCGJ, Tomo I, art. 8º (consolidação de 2017)","mastigado":"A resposta é a letra A. Todo ano, o juiz corregedor faz uma fiscalização geral nas unidades sob sua responsabilidade, de preferência em dezembro. Essa é a correição ordinária.","teSitua":{"termos":[{"termo":"correição ordinária","significado":"fiscalização anual e prevista da unidade."},{"termo":"serventias","significado":"cartórios e ofícios que prestam serviços judiciais."}],"exemplo":"Todo mês de dezembro, o juiz Augusto faz a correição ordinária no cartório da Vara Criminal de que é corregedor permanente, examinando livros, processos e rotinas e lavrando o termo no livro de visitas e correições."}},{"id":"aut.legislacao_tj.funcao_correcional.0009","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Conforme as Normas de Serviço da Corregedoria Geral da Justiça, a correição ordinária será anunciada por edital","alternativas":{"A":"afixado no átrio do fórum e publicado no Diário da Justiça Eletrônico, com pelo menos quinze dias de antecedência, e comunicada à OAB da respectiva subseção.","B":"publicado no Diário Oficial com cinco dias de antecedência, apenas.","C":"afixado na porta do cartório com quarenta e oito horas de antecedência.","D":"publicado no Diário da Justiça Eletrônico com trinta dias de antecedência, dispensada a comunicação à OAB.","E":"enviado por e-mail aos advogados cadastrados, no dia anterior."},"gabarito":"A","explicacao":"O art. 8º, § 1º, exige edital afixado no átrio do fórum e publicado no DJE com pelo menos quinze dias de antecedência, além de comunicação à OAB da respectiva subseção. Na correição extraordinária, pode-se dispensar o edital (Regimento Interno, art. 28, X), e a visita correcional independe de edital (art. 9º, § 1º).","explicacoes":{"A":"Correta: art. 8º, § 1º.","B":"A antecedência é de pelo menos quinze dias, com afixação e comunicação à OAB.","C":"A antecedência é de quinze dias.","D":"A antecedência é de quinze dias e há comunicação à OAB.","E":"Não é a forma prevista."},"fonte":"NSCGJ, Tomo I, art. 8º, § 1º (consolidação de 2017)","mastigado":"A resposta é a letra A. A correição ordinária é anunciada com antecedência: o edital fica na entrada do fórum e sai no Diário da Justiça pelo menos quinze dias antes, e a OAB local também é avisada.","teSitua":{"termos":[{"termo":"edital","significado":"aviso oficial publicado e afixado para conhecimento de todos."},{"termo":"átrio do fórum","significado":"entrada ou saguão principal do prédio do fórum."},{"termo":"subseção","significado":"unidade local da Ordem dos Advogados do Brasil."}],"exemplo":"A correição ordinária do cartório de Jales foi marcada para 12 de dezembro. O edital foi publicado no Diário da Justiça e afixado no saguão do fórum em 20 de novembro, e a subseção local da OAB foi comunicada."}},{"id":"aut.legislacao_tj.funcao_correcional.0010","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Um juiz assumiu, em caráter definitivo, a corregedoria permanente de um cartório em abril. Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, ele deverá","alternativas":{"A":"fazer visita correcional às unidades sob sua corregedoria em até 30 dias, a qual independe de edital.","B":"fazer correição ordinária imediatamente, com edital de quinze dias.","C":"aguardar dezembro para qualquer fiscalização.","D":"fazer visita correcional em até 90 dias, mediante edital.","E":"pedir autorização ao Corregedor Geral para visitar o cartório."},"gabarito":"A","explicacao":"O art. 9º determina a visita correcional em até 30 dias depois de assumir a corregedoria permanente em caráter definitivo. Ela independe de edital, lançando-se sucinto termo no livro de visitas e correições (§ 1º). Se o juiz assumir a partir de novembro, a correição geral ordinária dispensa a visita (§ 2º).","explicacoes":{"A":"Correta: art. 9º, caput e § 1º.","B":"A providência inicial é a visita correcional, não a correição ordinária.","C":"Há visita em até 30 dias.","D":"O prazo é de 30 dias, e não há edital.","E":"Não há essa exigência."},"fonte":"NSCGJ, Tomo I, art. 9º (consolidação de 2017)","mastigado":"A resposta é a letra A. O juiz que assume definitivamente a corregedoria de um cartório tem trinta dias para visitá-lo e ver como está. Essa visita não precisa de edital. Se ele assumir em novembro ou dezembro, basta a correição anual.","teSitua":{"termos":[{"termo":"corregedoria permanente","significado":"função do juiz de fiscalizar continuamente determinado cartório ou serviço."},{"termo":"caráter definitivo","significado":"de forma permanente, e não como substituto temporário."},{"termo":"visita correcional","significado":"fiscalização pontual da unidade, sem necessidade de edital."}],"exemplo":"O juiz Fernando assumiu definitivamente a 2ª Vara de Família de Santos em 5 de abril. Em 28 de abril, ele visitou o cartório, verificou a rotina e registrou um termo resumido no livro de visitas e correições."}},{"id":"aut.legislacao_tj.funcao_correcional.0011","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o escrivão auxiliará o Juiz Corregedor Permanente nas diligências correcionais, facultada a nomeação de escrivão ad hoc entre os demais servidores da unidade.","gabarito":"C","explicacao":"É a regra do art. 10. Durante os serviços correcionais, todos os funcionários da unidade permanecem à disposição do Corregedor Geral, dos Juízes Assessores ou do Juiz Corregedor Permanente (art. 11).","fonte":"NSCGJ, Tomo I, arts. 10 e 11 (consolidação de 2017)","mastigado":"Certo. Na correição, o escrivão ajuda o juiz. Se ele não puder, o juiz pode nomear outro servidor da unidade para fazer esse papel naquele ato.","teSitua":{"termos":[{"termo":"diligências correcionais","significado":"atos praticados durante a fiscalização, como exame de livros e processos."},{"termo":"escrivão ad hoc","significado":"servidor nomeado para exercer a função de escrivão apenas naquele ato."}],"exemplo":"Na correição do cartório de Itu, o escrivão estava de férias. O juiz nomeou a escrevente Carla como escrivã ad hoc, e ela o auxiliou em todo o trabalho de fiscalização."}},{"id":"aut.legislacao_tj.funcao_correcional.0012","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":2,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, durante os serviços correcionais, apenas o escrivão permanecerá à disposição do Juiz Corregedor Permanente, sendo vedada a requisição de auxílio externo ou de força policial.","gabarito":"E","explicacao":"O art. 11 dispõe que todos os funcionários da unidade permanecerão à disposição do Corregedor Geral, dos Juízes Assessores da Corregedoria ou do Juiz Corregedor Permanente, sem prejuízo de requisição de auxílio externo ou de força policial.","fonte":"NSCGJ, Tomo I, art. 11 (consolidação de 2017)","mastigado":"Errado. Durante a correição, todos os servidores da unidade ficam à disposição de quem está fiscalizando, e não só o escrivão. Se precisar, pode-se até pedir ajuda de fora ou da polícia.","teSitua":{"termos":[{"termo":"serviços correcionais","significado":"trabalhos de fiscalização realizados na unidade judicial."},{"termo":"força policial","significado":"apoio da polícia para garantir a ordem ou o cumprimento de uma ordem."}],"exemplo":"Na correição extraordinária num cartório com suspeita de fraude, todos os servidores ficaram à disposição dos juízes assessores da Corregedoria, que também requisitaram apoio policial para garantir a segurança."}},{"id":"aut.legislacao_tj.funcao_correcional.0013","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, os livros e classificadores obrigatórios serão submetidos ao Juiz Corregedor Permanente para visto por ocasião das correições e sempre que requisitados. No caso de registros controlados exclusivamente pela via eletrônica,","alternativas":{"A":"os relatórios de pendências gerados pelo sistema informatizado serão vistados pelo juiz.","B":"fica dispensado qualquer visto do juiz.","C":"os registros deverão ser impressos integralmente e encadernados para visto.","D":"o visto será dado pelo escrivão.","E":"o visto caberá exclusivamente ao Corregedor Geral."},"gabarito":"A","explicacao":"O art. 12, parágrafo único, determina que, nos registros controlados exclusivamente pela via eletrônica, o juiz vistará os relatórios de pendências gerados pelo sistema informatizado.","explicacoes":{"A":"Correta: art. 12, parágrafo único.","B":"O visto não é dispensado; recai sobre os relatórios de pendências.","C":"Não se exige impressão integral.","D":"O visto é do juiz.","E":"O visto é do Juiz Corregedor Permanente."},"fonte":"NSCGJ, Tomo I, art. 12 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quando o controle é todo eletrônico e não há livro de papel, o juiz dá o visto nos relatórios de pendências que o sistema gera. Assim a fiscalização continua existindo.","teSitua":{"termos":[{"termo":"classificadores obrigatórios","significado":"pastas exigidas pelas Normas para arquivar documentos do cartório."},{"termo":"visto","significado":"assinatura do juiz atestando que examinou o livro ou documento."},{"termo":"relatórios de pendências","significado":"listas geradas pelo sistema com tarefas ou prazos ainda não cumpridos."}],"exemplo":"Na correição, o cartório da juíza Lúcia não tinha mais livro de carga em papel, porque o controle era só eletrônico. Ela vistou o relatório de pendências gerado pelo sistema, mostrando os processos com carga vencida."}},{"id":"aut.legislacao_tj.funcao_correcional.0014","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os estabelecimentos prisionais sujeitos à atividade correcional do juízo serão visitados","alternativas":{"A":"uma vez por mês, pessoalmente pelo Juiz Corregedor Permanente, ressalvado afastamento igual ou superior a trinta dias ou motivo relevante comunicado à Corregedoria Geral.","B":"uma vez por ano, por ocasião da correição ordinária.","C":"a cada seis meses, por qualquer servidor designado.","D":"semanalmente, pelo escrivão judicial.","E":"apenas quando houver denúncia de irregularidade."},"gabarito":"A","explicacao":"O art. 13 determina visita mensal aos estabelecimentos prisionais (art. 66, VII, da LEP), feita pelo Juiz Corregedor Permanente ou pelo juiz a quem a atribuição for delegada (§ 1º); a inspeção é registrada em termo sucinto no Livro de Visitas e Correições (§ 2º). O § 3º exige que o Corregedor Permanente a faça pessoalmente, salvo afastamento de trinta dias ou mais ou motivo relevante comunicado, vedada a atribuição a juiz que responda pela vara por período inferior.","explicacoes":{"A":"Correta: art. 13, caput e § 3º.","B":"A visita é mensal.","C":"A visita é mensal e feita por juiz.","D":"A visita é mensal e feita por juiz.","E":"A visita é periódica e obrigatória."},"fonte":"NSCGJ, Tomo I, art. 13 (consolidação de 2017)","mastigado":"A resposta é a letra A. Presídios e cadeias ligados ao juízo devem ser visitados todo mês, e o próprio juiz corregedor deve ir pessoalmente. Só não vai se estiver afastado por trinta dias ou mais ou por motivo relevante avisado à Corregedoria.","teSitua":{"termos":[{"termo":"estabelecimentos prisionais","significado":"presídios e cadeias onde ficam pessoas presas."},{"termo":"atividade correcional","significado":"fiscalização exercida pelo juiz sobre serviços e estabelecimentos."},{"termo":"Juiz Corregedor Permanente","significado":"juiz encarregado de fiscalizar continuamente determinado serviço."}],"exemplo":"O juiz Roberto, corregedor do presídio de sua comarca, visita a unidade todo mês. Em julho, estava em férias de trinta dias, e a visita daquele mês foi feita por outro juiz designado."}},{"id":"aut.legislacao_tj.funcao_correcional.0015","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, a sistemática de visitas mensais aos estabelecimentos prisionais não desobriga a visita mensal às Cadeias Públicas, sob responsabilidade tanto dos Juízes de Varas Privativas de Execuções Criminais como daqueles que acumulem outros serviços anexos.","gabarito":"C","explicacao":"É o que dispõe o art. 14, em complemento ao art. 13.","fonte":"NSCGJ, Tomo I, art. 14 (consolidação de 2017)","mastigado":"Certo. Além dos presídios, as cadeias públicas também precisam receber visita mensal do juiz. Isso vale tanto para o juiz que cuida só de execuções criminais quanto para o que acumula outros serviços.","teSitua":{"termos":[{"termo":"Cadeias Públicas","significado":"estabelecimentos que recebem presos provisórios, geralmente ligados à polícia."},{"termo":"Varas Privativas de Execuções Criminais","significado":"varas que cuidam exclusivamente do cumprimento das penas."},{"termo":"serviços anexos","significado":"atribuições acumuladas pelo juiz além de sua vara principal."}],"exemplo":"Numa comarca pequena, o juiz Elias acumula a vara criminal e as execuções. Todo mês, ele visita o centro de detenção e também a cadeia pública da cidade, como exigem as Normas."}},{"id":"aut.legislacao_tj.funcao_correcional.0016","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, as apurações preliminares, as sindicâncias e os processos administrativos relativos ao pessoal das serventias judiciais serão realizados","alternativas":{"A":"pelos Juízes Corregedores Permanentes a que, na atualidade do procedimento, estiverem subordinados os servidores.","B":"pelo Presidente do Tribunal de Justiça, exclusivamente.","C":"pela Procuradoria Geral do Estado.","D":"pelo juiz corregedor ao tempo da falta, ainda que o servidor tenha mudado de unidade.","E":"pelo escrivão judicial da unidade."},"gabarito":"A","explicacao":"O art. 15 atribui esses procedimentos aos Juízes Corregedores Permanentes a que, na atualidade do procedimento, estiverem subordinados os servidores. O Corregedor Geral pode avocá-los em qualquer fase, designar Juiz Corregedor Processante e atribuir serviços auxiliares em unidade diversa (parágrafo único).","explicacoes":{"A":"Correta: art. 15, caput.","B":"A atribuição é dos Juízes Corregedores Permanentes.","C":"Não é a regra das Normas para servidores das serventias judiciais.","D":"O critério é a subordinação na atualidade do procedimento.","E":"O escrivão não conduz esses procedimentos."},"fonte":"NSCGJ, Tomo I, art. 15 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quem apura falta de servidor de cartório é o juiz corregedor ao qual ele está subordinado no momento do procedimento. Se o servidor mudou de unidade, quem apura é o corregedor da unidade atual.","teSitua":{"termos":[{"termo":"apurações preliminares","significado":"investigações iniciais para esclarecer um fato antes de abrir procedimento disciplinar."},{"termo":"sindicâncias","significado":"procedimentos disciplinares para faltas de menor gravidade."},{"termo":"na atualidade do procedimento","significado":"no momento em que o procedimento é realizado."}],"exemplo":"A escrevente Bianca cometeu uma falta quando trabalhava na 1ª Vara Cível, mas foi removida para a 3ª Vara antes da apuração. A sindicância foi conduzida pelo juiz corregedor permanente da 3ª Vara, a que ela está subordinada agora."}},{"id":"aut.legislacao_tj.funcao_correcional.0017","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, o Corregedor Geral da Justiça poderá avocar procedimento disciplinar em qualquer fase, a pedido ou de ofício, designar Juiz Corregedor Processante para todos os atos pertinentes e atribuir serviços auxiliares à unidade diversa daquela a que estiver vinculado o servidor.","gabarito":"C","explicacao":"É o parágrafo único do art. 15. A regra corresponde ao art. 28, XXVII, do Regimento Interno do TJSP.","fonte":"NSCGJ, Tomo I, art. 15, parágrafo único (consolidação de 2017)","mastigado":"Certo. O Corregedor Geral pode trazer para si um procedimento disciplinar que está com o juiz da comarca, em qualquer momento, e nomear um juiz especial para conduzi-lo. Pode também mandar o servidor trabalhar em outra unidade enquanto isso.","teSitua":{"termos":[{"termo":"avocar","significado":"chamar para si um assunto que estava com outra autoridade."},{"termo":"Juiz Corregedor Processante","significado":"juiz designado especialmente para conduzir um procedimento disciplinar."},{"termo":"serviços auxiliares","significado":"tarefas de apoio atribuídas ao servidor em outra unidade."}],"exemplo":"Um processo administrativo contra um escrivão envolvia o próprio juiz corregedor da comarca como testemunha. O Corregedor Geral avocou o procedimento e designou um juiz corregedor processante de outra comarca."}},{"id":"aut.legislacao_tj.funcao_correcional.0018","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":4,"enunciado":"Instaurado procedimento administrativo contra servidor de serventia judicial, o Juiz Corregedor Permanente, segundo as Normas de Serviço da Corregedoria Geral da Justiça, comunicará à Corregedoria Geral a instauração, com cópia da portaria inaugural, para acompanhamento","alternativas":{"A":"das apurações preliminares pela Diretoria da Corregedoria (DICOGE) e das sindicâncias e processos administrativos pela Secretaria de Planejamento de Recursos Humanos (SPRH).","B":"de todos os procedimentos pela Presidência do Tribunal.","C":"apenas dos processos administrativos, dispensada a comunicação das sindicâncias.","D":"pelo Conselho Superior da Magistratura, exclusivamente.","E":"somente após a decisão final, dispensada a comunicação da instauração."},"gabarito":"A","explicacao":"O art. 16 manda comunicar a instauração, com cópia da portaria inaugural, para acompanhamento das apurações preliminares pela DICOGE (I) e das sindicâncias e processos administrativos pela SPRH (II). O mesmo se faz com os atos decisórios posteriores e, ao final, com a decisão, ciência ao servidor e certidão de trânsito em julgado (parágrafo único).","explicacoes":{"A":"Correta: art. 16, I e II.","B":"A comunicação é à Corregedoria Geral, com acompanhamento por DICOGE e SPRH.","C":"As sindicâncias também são comunicadas.","D":"Não é a previsão das Normas.","E":"A instauração deve ser comunicada desde logo."},"fonte":"NSCGJ, Tomo I, art. 16 (consolidação de 2017)","mastigado":"A resposta é a letra A. Todo procedimento disciplinar aberto na comarca é comunicado à Corregedoria Geral desde o começo. A apuração preliminar é acompanhada por uma diretoria da Corregedoria; sindicâncias e processos, pela secretaria de recursos humanos.","teSitua":{"termos":[{"termo":"portaria inaugural","significado":"ato que dá início ao procedimento e descreve o fato a apurar."},{"termo":"DICOGE","significado":"Diretoria da Corregedoria Geral da Justiça."},{"termo":"SPRH","significado":"Secretaria de Planejamento de Recursos Humanos do Tribunal."}],"exemplo":"O juiz corregedor de Lins instaurou sindicância contra um escrevente e enviou cópia da portaria à Corregedoria Geral, para acompanhamento pela SPRH. Ao final, enviou também a decisão e a certidão de trânsito em julgado."}},{"id":"aut.legislacao_tj.funcao_correcional.0019","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, eventuais recursos em procedimentos disciplinares conduzidos pela Corregedoria Permanente serão processados em autos apartados e julgados pelo próprio Juiz Corregedor Permanente.","gabarito":"E","explicacao":"O art. 17 determina que eventuais recursos sejam entranhados nos autos originais e remetidos à Corregedoria Geral da Justiça. Pelo Regimento Interno, o Corregedor Geral julga os recursos contra decisões dos juízes corregedores permanentes em matéria disciplinar do pessoal das serventias judiciais (art. 28, XIII).","fonte":"NSCGJ, Tomo I, art. 17 (consolidação de 2017); Regimento Interno do TJSP, art. 28, XIII","mastigado":"Errado. O recurso do servidor punido é juntado aos próprios autos do procedimento e enviado à Corregedoria Geral da Justiça. Quem decide não é o mesmo juiz que aplicou a pena.","teSitua":{"termos":[{"termo":"autos apartados","significado":"processo separado, com numeração própria."},{"termo":"Corregedoria Permanente","significado":"fiscalização contínua exercida pelo juiz sobre determinada unidade."}],"exemplo":"Punido com repreensão pelo juiz corregedor de Assis, o escrevente Ciro recorreu. O recurso foi juntado aos autos da sindicância e remetido à Corregedoria Geral da Justiça para julgamento."}},{"id":"aut.legislacao_tj.funcao_correcional.0020","subtopico":"legislacao_tj.nscgj.funcao_correcional","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, sem prejuízo da atribuição do Juiz Corregedor Permanente, o Corregedor Geral da Justiça poderá","alternativas":{"A":"aplicar, originariamente, as sanções cabíveis e, enquanto não prescrita a infração, reexaminar, de ofício ou mediante provocação, decisões absolutórias ou de arquivamento.","B":"reexaminar decisões absolutórias a qualquer tempo, ainda que prescrita a infração.","C":"apenas confirmar as decisões dos juízes corregedores, sem alterá-las.","D":"aplicar sanções somente após recurso do servidor.","E":"delegar a aplicação de penas ao escrivão judicial."},"gabarito":"A","explicacao":"O art. 18 permite ao Corregedor Geral aplicar originariamente as sanções cabíveis e, enquanto não prescrita a infração, reexaminar, de ofício ou mediante provocação, decisões absolutórias ou de arquivamento.","explicacoes":{"A":"Correta: art. 18.","B":"O reexame só é possível enquanto não prescrita a infração.","C":"Ele pode reexaminar e aplicar sanções.","D":"Ele pode aplicar sanções originariamente.","E":"Não há essa previsão."},"fonte":"NSCGJ, Tomo I, art. 18 (consolidação de 2017)","mastigado":"A resposta é a letra A. O Corregedor Geral pode punir diretamente e também pode rever uma absolvição ou um arquivamento feito pelo juiz da comarca, mas só enquanto a falta não estiver prescrita.","teSitua":{"termos":[{"termo":"originariamente","significado":"como primeira autoridade a decidir, e não em recurso."},{"termo":"decisões absolutórias","significado":"decisões que concluem que o servidor não deve ser punido."},{"termo":"prescrita","significado":"que não pode mais ser punida por causa do tempo passado."}],"exemplo":"O juiz corregedor arquivou uma sindicância contra um servidor apesar das provas. Meses depois, ainda dentro do prazo de prescrição, o Corregedor Geral reexaminou o caso de ofício e aplicou a pena de suspensão."}},{"id":"aut.legislacao_tj.lc1111.0001","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos da Lei Complementar estadual nº 1.111/2010, o Quadro de Pessoal do Tribunal de Justiça do Estado de São Paulo compreende cargos efetivos e cargos em comissão, constantes de anexos da própria lei.","gabarito":"C","explicacao":"O art. 2º diz que o Quadro de Pessoal do TJSP compreende os cargos efetivos do Anexo I e os cargos em comissão do Anexo II. O ingresso na carreira se dá por concurso público de provas ou de provas e títulos (art. 8º).","fonte":"LC 1.111/2010, art. 2º, I e II; art. 8º","mastigado":"Certo. O quadro do Tribunal tem dois tipos de cargo: os efetivos, ocupados por concursados, e os em comissão, de confiança. Cada grupo está listado num anexo da lei.","teSitua":{"termos":[{"termo":"Quadro de Pessoal","significado":"conjunto de todos os cargos de servidores de um órgão."},{"termo":"cargos em comissão","significado":"cargos de confiança, de livre nomeação e exoneração."}],"exemplo":"Na comarca de Bauru, a escrevente Lívia ocupa cargo efetivo, obtido por concurso. A coordenadora Sônia ocupa cargo em comissão. Ambos os cargos integram o Quadro de Pessoal do Tribunal, cada um num anexo da lei."}},{"id":"aut.legislacao_tj.lc1111.0002","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a LC nº 1.111/2010, a Escala de Vencimentos dos Cargos Efetivos (exceto a da Área Saúde) é constituída de","alternativas":{"A":"8 referências, identificadas por algarismos de 1 a 8, e 18 graus, representados pelas letras de A a R.","B":"14 referências, representadas por algarismos romanos de I a XIV.","C":"3 referências, de 11 a 13, e 10 graus, de A a J.","D":"8 referências e 14 graus, de A a N.","E":"18 referências e 8 graus, de A a H."},"gabarito":"A","explicacao":"O art. 3º, I, define a Escala dos Cargos Efetivos com 8 referências (1 a 8) e 18 graus (A a R). A Área Saúde tem 3 referências (11 a 13) e 18 graus (inciso II); a Escala dos Cargos em Comissão tem 2 níveis de 14 referências, de I a XIV (inciso III, redação da LC 1.217/2013).","explicacoes":{"A":"Correta: art. 3º, I.","B":"Essa é a escala dos cargos em comissão (inciso III).","C":"A Área Saúde tem 3 referências, mas 18 graus (inciso II).","D":"São 18 graus, de A a R.","E":"Os números estão invertidos."},"fonte":"LC 1.111/2010, art. 3º, I a III","mastigado":"A resposta é a letra A. Os cargos efetivos têm oito degraus de referência, numerados de um a oito, e dentro de cada um há dezoito graus, de A até R. É nessa tabela que o servidor sobe ao longo da carreira.","teSitua":{"termos":[{"termo":"Escala de Vencimentos","significado":"tabela que fixa os valores do vencimento de cada cargo."},{"termo":"referências","significado":"números que indicam a faixa de vencimento do cargo."},{"termo":"graus","significado":"letras que indicam a posição do servidor dentro da referência."}],"exemplo":"O escrevente Tiago entrou no Tribunal num padrão inicial da tabela de cargos efetivos. Com as progressões, ele foi avançando de grau, de A para B, depois C, dentro da mesma referência, numa escala que vai até a letra R."}},{"id":"aut.legislacao_tj.lc1111.0003","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com a LC nº 1.111/2010, os valores mensais de vencimento dos cargos efetivos previstos em seu Anexo III correspondem às jornadas de 40 e 30 horas semanais, enquanto os valores dos cargos em comissão correspondem à jornada de 40 horas semanais.","gabarito":"C","explicacao":"É o que dispõem o art. 4º, caput, e o § 2º. Os §§ 3º e 4º fixam a jornada de 30 horas semanais para Assistente Social Judiciário e Psicólogo Judiciário.","fonte":"LC 1.111/2010, art. 4º, caput e §§ 2º a 4º","mastigado":"Certo. Para os cargos efetivos, a tabela tem valores para quem trabalha quarenta ou trinta horas por semana. Os cargos em comissão têm sempre jornada de quarenta horas.","teSitua":{"termos":[{"termo":"vencimento","significado":"valor-base pago mensalmente pelo exercício do cargo."},{"termo":"jornadas","significado":"quantidade de horas de trabalho exigida por semana."}],"exemplo":"A psicóloga judiciária Fernanda trabalha trinta horas por semana e recebe pelo valor dessa jornada. Já o diretor Paulo, em cargo em comissão, cumpre quarenta horas semanais, como manda a lei."}},{"id":"aut.legislacao_tj.lc1111.0004","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":2,"enunciado":"Conforme a LC nº 1.111/2010, para os cargos de provimento em comissão de Secretário, Diretor, Coordenador, Supervisor de Serviço, Chefe de Seção Técnica Judiciário, Chefe de Seção Judiciário e Assistente Jurídico poderá haver substituição durante os impedimentos do titular.","gabarito":"C","explicacao":"É a regra do art. 5º. O servidor efetivo que exerce essa substituição, ou que é nomeado para cargo em comissão, pode optar pelo vencimento do seu cargo efetivo (art. 6º).","fonte":"LC 1.111/2010, arts. 5º e 6º","mastigado":"Certo. Quando o titular de um desses cargos de comando ou de assessoria jurídica se afasta, outro servidor pode substituí-lo. A lei lista quais cargos em comissão admitem essa substituição.","teSitua":{"termos":[{"termo":"provimento em comissão","significado":"forma de ocupar cargo de confiança, de livre nomeação e exoneração."},{"termo":"impedimentos do titular","significado":"afastamentos temporários de quem ocupa o cargo, como férias e licenças."}],"exemplo":"O Coordenador Renato saiu de férias por trinta dias. A supervisora Ana foi designada para substituí-lo nesse período, como permite a lei para o cargo de Coordenador."}},{"id":"aut.legislacao_tj.lc1111.0005","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a LC nº 1.111/2010, o servidor titular de cargo efetivo nomeado para cargo em comissão perde obrigatoriamente o vencimento do cargo efetivo, sem direito de opção.","gabarito":"E","explicacao":"O art. 6º assegura ao titular de cargo efetivo, quando nomeado para cargo em comissão ou no exercício da substituição do art. 5º, a opção pela percepção do vencimento do seu cargo efetivo.","fonte":"LC 1.111/2010, art. 6º","mastigado":"Errado. O servidor efetivo que vai para um cargo de confiança pode escolher continuar recebendo o vencimento do cargo efetivo, se for mais vantajoso. A lei garante essa opção.","teSitua":{"termos":[{"termo":"cargo efetivo","significado":"cargo permanente, ocupado por concursado."},{"termo":"direito de opção","significado":"possibilidade de escolher qual vencimento receber."}],"exemplo":"A escrevente Bruna, com muitos anos de casa, foi nomeada para um cargo em comissão cujo vencimento era menor que o seu. Ela optou por continuar recebendo o vencimento do cargo efetivo."}},{"id":"aut.legislacao_tj.lc1111.0006","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da LC nº 1.111/2010, a remuneração dos servidores abrangidos pelo Plano compreende, além do vencimento, vantagens pecuniárias como o adicional por tempo de serviço, calculado na base de","alternativas":{"A":"5% por quinquênio de serviço sobre o valor dos vencimentos, além da sexta-parte e do décimo terceiro salário.","B":"10% por quinquênio, sem direito à sexta-parte.","C":"1% por ano de serviço, sobre o vencimento e as gratificações.","D":"5% por triênio, sobre a remuneração total.","E":"20% a cada dez anos, sobre o padrão inicial do cargo."},"gabarito":"A","explicacao":"O art. 7º enumera, além do vencimento: adicional por tempo de serviço de 5% por quinquênio sobre os vencimentos (I); sexta-parte (II); décimo terceiro salário (III); salário-família e salário-esposa (IV); e outras vantagens previstas em lei, inclusive gratificações (V).","explicacoes":{"A":"Correta: art. 7º, I a III.","B":"O percentual é de 5% por quinquênio, e a sexta-parte é devida.","C":"O cálculo é por quinquênio, não por ano.","D":"O período é o quinquênio, e a base são os vencimentos.","E":"Não há essa previsão."},"fonte":"LC 1.111/2010, art. 7º","mastigado":"A resposta é a letra A. A cada cinco anos de serviço, o servidor ganha mais cinco por cento sobre o vencimento. Além disso, recebe a sexta-parte, o décimo terceiro e outras vantagens previstas em lei.","teSitua":{"termos":[{"termo":"vantagens pecuniárias","significado":"valores em dinheiro pagos além do vencimento."},{"termo":"quinquênio","significado":"período de cinco anos de serviço."},{"termo":"sexta-parte","significado":"acréscimo de um sexto nos vencimentos, garantido ao servidor estadual com vinte anos de serviço."}],"exemplo":"O escrevente Jonas completou dez anos de serviço, ou seja, dois quinquênios. Ele recebe adicional de 10% sobre os vencimentos, além do décimo terceiro salário, conforme o Plano de Cargos."}},{"id":"aut.legislacao_tj.lc1111.0007","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a LC nº 1.111/2010, o servidor nomeado para cargo de provimento efetivo ficará sujeito a Estágio Probatório durante o período de","alternativas":{"A":"36 meses, ao longo do qual serão avaliadas assiduidade, pontualidade, aptidão, capacidade e eficiência.","B":"24 meses, avaliando-se apenas a produtividade.","C":"12 meses, avaliando-se assiduidade e pontualidade.","D":"48 meses, avaliando-se aptidão e eficiência.","E":"36 meses, avaliando-se exclusivamente a disciplina."},"gabarito":"A","explicacao":"O art. 11 fixa o Estágio Probatório em 36 meses, com avaliação da assiduidade, pontualidade, aptidão, capacidade e eficiência, para a efetivação na carreira. O art. 40 dispensa do estágio o servidor que já o cumpriu em outro cargo efetivo do Anexo I.","explicacoes":{"A":"Correta: art. 11.","B":"O prazo é de 36 meses e os critérios são cinco.","C":"O prazo é de 36 meses.","D":"O prazo é de 36 meses.","E":"Os critérios são assiduidade, pontualidade, aptidão, capacidade e eficiência."},"fonte":"LC 1.111/2010, art. 11; art. 40","mastigado":"A resposta é a letra A. O servidor novo passa três anos em avaliação. Nesse tempo, o Tribunal observa se ele é assíduo, pontual, apto, capaz e eficiente antes de efetivá-lo na carreira.","teSitua":{"termos":[{"termo":"Estágio Probatório","significado":"período inicial em que o servidor novo é avaliado antes de ser efetivado."},{"termo":"assiduidade","significado":"comparecimento regular ao trabalho, sem faltas."},{"termo":"efetivação","significado":"confirmação do servidor no cargo após aprovação no estágio."}],"exemplo":"Davi tomou posse como escrevente em fevereiro de 2027. Até fevereiro de 2030, ele será avaliado quanto à frequência, aos horários, à aptidão, à capacidade e à eficiência. Aprovado, será efetivado na carreira."}},{"id":"aut.legislacao_tj.lc1111.0008","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":2,"enunciado":"Segundo a LC nº 1.111/2010, a evolução profissional dos servidores na carreira do Tribunal de Justiça dar-se-á por meio dos institutos da","alternativas":{"A":"Progressão, Promoção e Acesso.","B":"Progressão, Remoção e Readaptação.","C":"Promoção, Transferência e Reversão.","D":"Acesso, Aproveitamento e Readmissão.","E":"Promoção por antiguidade e Promoção por merecimento, apenas."},"gabarito":"A","explicacao":"O art. 12 prevê Progressão, Promoção e Acesso como institutos de evolução na carreira, com os objetivos de reconhecimento do resultado do trabalho e constante aproveitamento do servidor pela experiência adquirida.","explicacoes":{"A":"Correta: art. 12.","B":"Remoção (art. 51) e readaptação não são institutos de evolução na carreira.","C":"Transferência e reversão não constam do art. 12.","D":"Aproveitamento e readmissão não constam do art. 12.","E":"A lei não estrutura a evolução nesses termos."},"fonte":"LC 1.111/2010, art. 12","mastigado":"A resposta é a letra A. No Tribunal, o servidor cresce de três jeitos: pela progressão (sobe de grau), pela promoção (sobe de nível) e pelo acesso (vai para um cargo em comissão de chefia).","teSitua":{"termos":[{"termo":"Progressão","significado":"passagem do servidor para o grau imediatamente superior, na mesma referência e nível."},{"termo":"Promoção","significado":"passagem para o nível e grau imediatamente superior, na mesma referência."},{"termo":"Acesso","significado":"provimento de cargo em comissão de chefia por servidor efetivo."}],"exemplo":"Ao longo de vinte anos, a servidora Marta subiu de grau várias vezes por progressão, mudou de nível por promoção e, por fim, chegou a Chefe de Seção pelo acesso. Foram os três caminhos de evolução previstos no Plano."}},{"id":"aut.legislacao_tj.lc1111.0009","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da LC nº 1.111/2010, a Progressão é","alternativas":{"A":"a passagem do servidor de cargo efetivo de um grau para o imediatamente superior, dentro da mesma referência e nível.","B":"a passagem do servidor para o nível e grau imediatamente superior, dentro da mesma referência.","C":"a forma de provimento vertical de cargo em comissão de chefia.","D":"a mudança de posto de trabalho, a pedido do servidor.","E":"a passagem do servidor para referência superior, mediante novo concurso."},"gabarito":"A","explicacao":"Progressão é a passagem de um grau para o imediatamente superior, na mesma referência e nível (art. 13). Promoção é a passagem ao nível e grau imediatamente superior, na mesma referência (art. 21); Acesso é o provimento vertical de cargo em comissão de chefia (art. 29); a mudança de posto a pedido é a Remoção (art. 51).","explicacoes":{"A":"Correta: art. 13.","B":"É a definição de Promoção (art. 21).","C":"É a definição de Acesso (art. 29).","D":"É a Remoção (art. 51).","E":"Não é instituto previsto; o novo concurso leva a outro cargo (art. 39)."},"fonte":"LC 1.111/2010, arts. 13, 21, 29 e 51","mastigado":"A resposta é a letra A. Progredir é subir uma letra, de grau em grau, sem sair da mesma referência e do mesmo nível. Mudar de nível é promoção; ir para um cargo de chefia é acesso.","teSitua":{"termos":[{"termo":"grau","significado":"letra que indica a posição do servidor dentro da referência."},{"termo":"referência","significado":"número que indica a faixa de vencimento do cargo."},{"termo":"provimento vertical","significado":"ocupação de cargo mais alto na hierarquia por quem já é servidor."}],"exemplo":"No último processo anual, o escrevente Saulo foi avaliado positivamente e passou do grau D para o grau E, sem mudar de referência nem de nível. Isso foi uma progressão."}},{"id":"aut.legislacao_tj.lc1111.0010","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Para participar do processo de Progressão, segundo a redação vigente da LC nº 1.111/2010, o servidor deve","alternativas":{"A":"ter cumprido, no mesmo cargo efetivo e grau, interstício mínimo de 1 ano de efetivo exercício e ter o desempenho avaliado anualmente, obtendo resultado final positivo.","B":"ter cumprido interstício mínimo de 2 anos e obtido 2 resultados positivos na avaliação.","C":"ter cumprido interstício de 3 anos, independentemente de avaliação.","D":"ter concluído curso de pós-graduação.","E":"ter cumprido interstício de 5 anos e aprovação em prova escrita."},"gabarito":"A","explicacao":"Com a LC 1.217/2013, o art. 14, I, passou a exigir interstício mínimo de 1 ano no mesmo cargo e grau, e o art. 16 passou a exigir resultado final positivo no processo anual de Avaliação de Desempenho. O inciso II exige avaliação anual por critérios do Comitê de Recursos Humanos. A redação antiga previa 2 anos e 2 resultados positivos.","explicacoes":{"A":"Correta: arts. 14 e 16, redação da LC 1.217/2013.","B":"Era a redação original, alterada em 2013.","C":"Não é o interstício vigente, e a avaliação é exigida.","D":"Pós-graduação dá direito ao Adicional de Qualificação, não é requisito da progressão.","E":"Não há essa exigência."},"fonte":"LC 1.111/2010, arts. 14 e 16 (redação da LC 1.217/2013)","mastigado":"A resposta é a letra A. Para subir de grau, basta ficar um ano no grau atual e ter avaliação de desempenho positiva naquele ano. Os antigos dois anos e duas avaliações não valem mais.","teSitua":{"termos":[{"termo":"interstício","significado":"tempo mínimo que o servidor precisa ficar num degrau antes de subir ao seguinte."},{"termo":"Avaliação de Desempenho","significado":"avaliação anual do trabalho do servidor por critérios definidos pelo Tribunal."}],"exemplo":"Kelly chegou ao grau C em janeiro de 2026. Em janeiro de 2027, com um ano no grau e avaliação de desempenho positiva, ela pode participar da progressão para o grau D."}},{"id":"aut.legislacao_tj.lc1111.0011","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a LC nº 1.111/2010, interrompe-se o interstício para a Progressão quando o servidor estiver afastado para ter exercício em cargo ou função de natureza diversa daquela que ocupa, EXCETO quando","alternativas":{"A":"nomeado para cargo em comissão.","B":"afastado para tratar de interesses particulares.","C":"cedido a outro Poder sem vínculo com o Tribunal.","D":"afastado para exercer emprego em empresa privada.","E":"afastado para cursos de qualquer natureza por mais de 90 dias."},"gabarito":"A","explicacao":"O art. 17 lista as exceções em que o interstício não se interrompe: designação para função com gratificação pro labore no TJSP (I); nomeação para cargo em comissão (II); designação como substituto ou para responder por cargo vago de comando (III); afastamento para cursos de aperfeiçoamento do cargo ou exigidos para o Acesso (IV); afastamento sem prejuízo de vencimentos para cursos e congressos da área, por até 90 dias (V).","explicacoes":{"A":"Correta: art. 17, II.","B":"Não é exceção prevista no art. 17.","C":"Não é exceção prevista no art. 17.","D":"Não é exceção prevista no art. 17.","E":"O limite para cursos e congressos é de até 90 dias (inciso V)."},"fonte":"LC 1.111/2010, art. 17","mastigado":"A resposta é a letra A. Em regra, quem vai fazer outra coisa fora do cargo para de contar tempo para a progressão. Mas há exceções, e uma delas é ser nomeado para cargo em comissão no Tribunal: o tempo continua contando.","teSitua":{"termos":[{"termo":"interstício","significado":"tempo mínimo que o servidor precisa cumprir antes de subir de grau."},{"termo":"natureza diversa","significado":"tipo de atividade diferente da do cargo ocupado."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"A escrevente Olga foi nomeada assessora em comissão durante oito meses. Esse período não interrompeu seu interstício para progressão, porque a nomeação para cargo em comissão é uma das exceções da lei."}},{"id":"aut.legislacao_tj.lc1111.0012","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a LC nº 1.111/2010, o servidor poderá interpor recurso ao Comitê de Recursos Humanos no prazo máximo de 30 dias corridos, a contar da publicação do resultado do processo da Progressão ou da Promoção.","gabarito":"C","explicacao":"É o que preveem os arts. 18 (Progressão) e 26 (Promoção). Compete ao Comitê de Recursos Humanos decidir esses recursos (art. 34, III).","fonte":"LC 1.111/2010, arts. 18, 26 e 34, III","mastigado":"Certo. Quem discorda do resultado da progressão ou da promoção tem trinta dias corridos, contados da publicação, para recorrer ao Comitê de Recursos Humanos, que decide o recurso.","teSitua":{"termos":[{"termo":"recurso","significado":"pedido de revisão de uma decisão."},{"termo":"dias corridos","significado":"contagem que inclui todos os dias, úteis ou não."}],"exemplo":"O resultado da promoção saiu em 2 de março, e Igor não foi contemplado, embora achasse que tinha cumprido os requisitos. Ele recorreu ao Comitê de Recursos Humanos em 20 de março, dentro dos trinta dias corridos."}},{"id":"aut.legislacao_tj.lc1111.0013","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da redação vigente da LC nº 1.111/2010, a Promoção","alternativas":{"A":"é a passagem para o nível e grau imediatamente superior, dentro da mesma referência, exigindo interstício mínimo de 1 ano no último grau do nível, cursos de aperfeiçoamento específicos e Avaliação de Desempenho.","B":"é a passagem de um grau para o imediatamente superior, sem exigência de cursos.","C":"exige interstício mínimo de 3 anos em qualquer grau.","D":"depende apenas de antiguidade no cargo.","E":"é a forma de provimento de cargo em comissão de direção."},"gabarito":"A","explicacao":"A Promoção é a passagem ao nível e grau imediatamente superior, na mesma referência (art. 21); exige interstício mínimo de 1 ano no último grau do nível (art. 22, redação da LC 1.217/2013); e se dá pelo reconhecimento da experiência, com cursos de aperfeiçoamento específicos selecionados pelo Tribunal, combinados com a Avaliação de Desempenho (arts. 23 e 24).","explicacoes":{"A":"Correta: arts. 21 a 24.","B":"Isso descreve a Progressão (art. 13), e a Promoção exige cursos.","C":"O interstício é de 1 ano, no último grau do nível.","D":"Exige experiência, cursos e avaliação, não só antiguidade.","E":"Isso é o Acesso (art. 29)."},"fonte":"LC 1.111/2010, arts. 21 a 24 (art. 22 com redação da LC 1.217/2013)","mastigado":"A resposta é a letra A. Promoção é mudar de nível. Para isso, o servidor precisa estar no último grau do nível atual há pelo menos um ano, fazer os cursos que o Tribunal escolher e ter boa avaliação de desempenho.","teSitua":{"termos":[{"termo":"nível","significado":"faixa da carreira que agrupa vários graus de vencimento."},{"termo":"interstício","significado":"tempo mínimo exigido antes de subir na carreira."},{"termo":"cursos de aperfeiçoamento","significado":"cursos que aprimoram o conhecimento para o cargo, escolhidos pelo Tribunal."}],"exemplo":"Selma chegou ao último grau do seu nível em 2025. Em 2026, com um ano nesse grau, cursos de aperfeiçoamento concluídos e avaliação positiva, ela foi promovida ao nível seguinte."}},{"id":"aut.legislacao_tj.lc1111.0014","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":4,"enunciado":"De acordo com a LC nº 1.111/2010, os cargos em comissão de direção, coordenação, supervisão ou chefia ficam reservados para provimento exclusivo de servidores titulares de cargos efetivos de mesma natureza e profissão do Quadro do Tribunal, na proporção de","alternativas":{"A":"totalidade dos de Chefe de Seção Judiciário e Chefe de Seção Técnica Judiciário, no mínimo 90% dos de Supervisor de Serviço, 90% dos de Coordenador e 70% dos de Diretor.","B":"50% de todos os cargos de chefia, indistintamente.","C":"totalidade dos de Diretor e 70% dos de Chefe de Seção.","D":"90% dos de Chefe de Seção e 50% dos de Diretor.","E":"70% dos de Coordenador e totalidade dos de Supervisor de Serviço."},"gabarito":"A","explicacao":"O art. 30 reserva: a totalidade dos cargos de Chefe de Seção Judiciário e Chefe de Seção Técnica Judiciário (I); no mínimo 90% dos de Supervisor de Serviço (II); 90% dos de Coordenador (III); e 70% dos de Diretor (IV). O Acesso é a forma de provimento vertical desses cargos pelo servidor efetivo (art. 29).","explicacoes":{"A":"Correta: art. 30, I a IV.","B":"A lei fixa proporções diferentes por cargo.","C":"Para Diretor a reserva é de 70%, e para Chefe de Seção é total.","D":"Chefe de Seção é 100% e Diretor é 70%.","E":"Coordenador é 90% e Supervisor, no mínimo 90%."},"fonte":"LC 1.111/2010, arts. 29 e 30","mastigado":"A resposta é a letra A. Quanto mais próximo da base, maior a reserva para servidores de carreira: chefias de seção são todas deles; supervisor e coordenador, noventa por cento; diretor, setenta por cento.","teSitua":{"termos":[{"termo":"provimento exclusivo","significado":"preenchimento reservado apenas a determinado grupo de pessoas."},{"termo":"Chefe de Seção Judiciário","significado":"cargo em comissão que chefia uma seção da unidade judicial."},{"termo":"Supervisor de Serviço","significado":"cargo em comissão que supervisiona um serviço do Tribunal."}],"exemplo":"Numa unidade com 10 cargos de Diretor, pelo menos 7 devem ser ocupados por servidores efetivos do Tribunal. Já as vagas de Chefe de Seção Judiciário, como a ocupada por Rui, são todas reservadas a servidores efetivos."}},{"id":"aut.legislacao_tj.lc1111.0015","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":3,"enunciado":"Para a qualificação ao provimento dos cargos em comissão de direção, coordenação, supervisão ou chefia, a LC nº 1.111/2010 exige do servidor, entre outros requisitos, resultados finais positivos nos últimos 3 processos anuais de Avaliação de Desempenho.","gabarito":"C","explicacao":"O art. 32 exige: declaração de interesse (I); habilitação legal correspondente (II); resultados positivos nos últimos 3 processos anuais de Avaliação de Desempenho (III); participação em cursos selecionados pelo Tribunal (IV). O art. 31 exige ainda experiência anterior nesses cargos, ainda que em substituição, ou experiência adequada.","fonte":"LC 1.111/2010, arts. 31 e 32, III","mastigado":"Certo. Para chegar a cargo de chefia pelo acesso, o servidor precisa, entre outras coisas, ter tido avaliação positiva nos três últimos anos, além de manifestar interesse e fazer os cursos indicados pelo Tribunal.","teSitua":{"termos":[{"termo":"qualificação","significado":"preenchimento dos requisitos para concorrer a um cargo."},{"termo":"Avaliação de Desempenho","significado":"avaliação anual do trabalho do servidor."}],"exemplo":"Lauro quer ser Supervisor de Serviço. Ele declarou interesse, fez os cursos indicados e teve avaliação positiva em 2024, 2025 e 2026. Com isso, está qualificado para o acesso."}},{"id":"aut.legislacao_tj.lc1111.0016","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a LC nº 1.111/2010, cabe ao Comitê de Recursos Humanos, entre outras atribuições,","alternativas":{"A":"normatizar o processamento do Sistema de Avaliação de Desempenho e do Estágio Probatório e decidir sobre recursos referentes à Progressão e à Promoção.","B":"executar os procedimentos anuais da Progressão e da Promoção.","C":"nomear os servidores para os cargos em comissão.","D":"processar o Acesso aos cargos de chefia.","E":"fixar por resolução o valor da Gratificação Judiciária."},"gabarito":"A","explicacao":"O art. 34 atribui ao Comitê: normatizar a Avaliação de Desempenho e o Estágio Probatório (I); acompanhar os resultados (II); decidir recursos de Progressão e Promoção (III). A execução da Progressão e da Promoção e o processamento do Acesso cabem à Secretaria de Recursos Humanos (arts. 20, 28 e 33). A Gratificação Judiciária é regulamentada pelo Tribunal por Resolução (art. 35).","explicacoes":{"A":"Correta: art. 34, I e III.","B":"Cabe à Secretaria de Recursos Humanos (arts. 20 e 28).","C":"Não é atribuição prevista para o Comitê.","D":"Cabe à Secretaria de Recursos Humanos (art. 33).","E":"A Gratificação Judiciária é regulamentada pelo Tribunal por Resolução (art. 35)."},"fonte":"LC 1.111/2010, arts. 20, 28, 33, 34 e 35","mastigado":"A resposta é a letra A. O Comitê cria as regras da avaliação e do estágio probatório e julga os recursos de quem discorda da progressão ou da promoção. Quem executa os procedimentos no dia a dia é a Secretaria de Recursos Humanos.","teSitua":{"termos":[{"termo":"Comitê de Recursos Humanos","significado":"órgão do Tribunal que normatiza a avaliação e julga recursos da carreira."},{"termo":"Estágio Probatório","significado":"período inicial de avaliação do servidor novo."},{"termo":"Gratificação Judiciária","significado":"gratificação paga aos servidores do Tribunal, regulamentada por resolução."}],"exemplo":"Insatisfeito com o resultado da progressão, o servidor Ênio recorreu. Quem julgou o recurso foi o Comitê de Recursos Humanos. Já a lista de progressões havia sido processada pela Secretaria de Recursos Humanos."}},{"id":"aut.legislacao_tj.lc1111.0017","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":3,"enunciado":"Sobre o Adicional de Qualificação (AQ) previsto na LC nº 1.111/2010, é correto afirmar que","alternativas":{"A":"não será concedido quando o curso constituir requisito ou estiver no mesmo nível de escolaridade para ingresso no cargo.","B":"incorpora-se aos vencimentos para todos os efeitos.","C":"admite pós-graduação lato sensu de qualquer duração.","D":"considera cursos de instituições não reconhecidas pelo MEC.","E":"é devido desde a data de conclusão do curso, independentemente de protocolo."},"gabarito":"A","explicacao":"O art. 37-A, § 1º, afasta o AQ quando o curso é requisito ou está no mesmo nível de escolaridade exigido para o ingresso. Só valem cursos e instituições reconhecidos pelo MEC (§ 2º); lato sensu com mínimo de 360 horas (§ 3º); o AQ não se incorpora e sobre ele não incide vantagem (§ 4º); é devido a partir do protocolo do diploma registrado (art. 37-B, § 2º).","explicacoes":{"A":"Correta: art. 37-A, § 1º.","B":"O AQ não se incorpora para nenhum efeito (§ 4º).","C":"Exige-se duração mínima de 360 horas (§ 3º).","D":"Só valem cursos e instituições reconhecidos pelo MEC (§ 2º).","E":"É devido a partir do protocolo do diploma no Tribunal (art. 37-B, § 2º)."},"fonte":"LC 1.111/2010, art. 37-A, §§ 1º a 4º; art. 37-B, § 2º","mastigado":"A resposta é a letra A. O adicional premia o estudo além do exigido para o cargo. Se o curso é justamente o que se pede para entrar no cargo, ou é do mesmo nível, ele não gera adicional.","teSitua":{"termos":[{"termo":"Adicional de Qualificação","significado":"valor pago ao servidor que tem formação acadêmica além da exigida para o cargo."},{"termo":"lato sensu","significado":"pós-graduação de especialização, como MBA, diferente de mestrado e doutorado."},{"termo":"requisito","significado":"condição obrigatória exigida para o ingresso."}],"exemplo":"O cargo de Analista exige graduação. Por isso, o diploma de Direito do analista Bento não lhe dá Adicional de Qualificação. Já a especialização de 400 horas que ele concluiu depois, protocolada no Tribunal, dá direito ao adicional."}},{"id":"aut.legislacao_tj.lc1111.0018","subtopico":"legislacao_tj.carreira.lc1111","tipo":"multipla","dificuldade":4,"enunciado":"Pela redação dada à LC nº 1.111/2010 pela LC nº 1.441/2026, o Adicional de Qualificação incidirá sobre os vencimentos brutos equivalentes à base de contribuição previdenciária do cargo, à razão de","alternativas":{"A":"20% para título de Doutor, 15% para Mestre, 10% para Especialização e 7,5% para graduação em curso superior.","B":"12,5% para Doutor, 10% para Mestre, 7,5% para Especialização e 5% para graduação.","C":"25% para Doutor, 20% para Mestre e 15% para Especialização, sem previsão para graduação.","D":"20% para Doutor e Mestre, indistintamente.","E":"15% para qualquer título, cumulativamente."},"gabarito":"A","explicacao":"O art. 37-B, com redação da LC 1.441/2026, fixa: 20% para Doutor (I); 15% para Mestre (II); 10% para Especialização (III); 7,5% para graduação (IV). Os percentuais não se acumulam (§ 1º). Os percentuais de 12,5%, 10%, 7,5% e 5% eram os da redação de 2013, substituídos.","explicacoes":{"A":"Correta: art. 37-B, I a IV, redação da LC 1.441/2026.","B":"Eram os percentuais da redação de 2013, alterados.","C":"Não são os percentuais legais.","D":"Mestre tem 15%, distinto do Doutor.","E":"Os percentuais variam e não se acumulam (§ 1º)."},"fonte":"LC 1.111/2010, art. 37-B, I a IV e § 1º (redação da LC 1.441/2026)","mastigado":"A resposta é a letra A. Desde 2026, o adicional é de vinte por cento para doutor, quinze para mestre, dez para especialista e sete e meio para quem tem graduação além da exigida. O servidor recebe só o maior que tiver, sem somar.","teSitua":{"termos":[{"termo":"Adicional de Qualificação","significado":"valor pago ao servidor com formação além da exigida para o cargo."},{"termo":"base de contribuição previdenciária","significado":"valor da remuneração sobre o qual se calcula a contribuição para a aposentadoria."},{"termo":"Especialização","significado":"curso de pós-graduação lato sensu, com no mínimo 360 horas."}],"exemplo":"A escrevente Raquel tem graduação, especialização e mestrado. Ela recebe apenas o percentual do mestrado, de 15%, porque os adicionais não se acumulam. Se concluir o doutorado, passará a receber 20%."}},{"id":"aut.legislacao_tj.lc1111.0019","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a LC nº 1.111/2010, fica dispensado do estágio probatório o servidor que, em decorrência de concurso público, passar a ocupar outro cargo de provimento efetivo previsto no Anexo I da lei, desde que já o tenha cumprido no cargo efetivo anteriormente ocupado.","gabarito":"C","explicacao":"É a regra do art. 40. Para a Progressão e a Promoção, porém, quem passa a outro cargo efetivo por concurso deve cumprir novo interstício (arts. 19 e 27), e o novo cargo é enquadrado em grau de vencimento igual ou imediatamente superior ao do anterior (art. 39).","fonte":"LC 1.111/2010, arts. 19, 27, 39 e 40","mastigado":"Certo. Se o servidor já foi aprovado no estágio probatório num cargo do Tribunal e passa em outro concurso para cargo do mesmo quadro, não precisa fazer estágio de novo. Mas o tempo para progredir no novo cargo começa do zero.","teSitua":{"termos":[{"termo":"estágio probatório","significado":"período inicial de avaliação do servidor antes da efetivação."},{"termo":"provimento efetivo","significado":"forma de ocupar cargo permanente, destinado a concursados."},{"termo":"Anexo I","significado":"lista dos cargos efetivos do Quadro do Tribunal, anexa à lei."}],"exemplo":"Paulo foi escrevente por seis anos e cumpriu o estágio probatório. Aprovado em concurso para outro cargo efetivo do Tribunal previsto no Anexo I, ele não precisa repetir o estágio, mas terá de cumprir novo interstício para progredir."}},{"id":"aut.legislacao_tj.lc1111.0020","subtopico":"legislacao_tj.carreira.lc1111","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a LC nº 1.111/2010, o instituto de Remoção, destinado a propiciar a alteração de posto de trabalho dos servidores dentro do Quadro do Tribunal, aplica-se apenas ex officio, por necessidade de serviço, segundo critérios fixados em lei estadual.","gabarito":"E","explicacao":"O art. 51 cria a Remoção para alteração de posto de trabalho a pedido dos servidores, dentro do Quadro do Tribunal, e seu parágrafo único remete os critérios à Presidência do Tribunal de Justiça.","fonte":"LC 1.111/2010, art. 51 e parágrafo único","mastigado":"Errado. A remoção prevista no Plano é a pedido do servidor, para mudar de posto de trabalho dentro do Tribunal. E quem estabelece os critérios é a Presidência do Tribunal, não uma lei estadual.","teSitua":{"termos":[{"termo":"Remoção","significado":"mudança do posto de trabalho do servidor, sem mudança de cargo."},{"termo":"ex officio","significado":"por iniciativa da Administração, sem pedido do servidor."},{"termo":"posto de trabalho","significado":"unidade ou local onde o servidor exerce suas funções."}],"exemplo":"A escrevente Cíntia trabalha em Itapetininga e quer ficar mais perto da família, em Sorocaba. Ela se inscreve no concurso de remoção, a pedido, seguindo os critérios fixados pela Presidência do Tribunal."}},{"id":"aut.legislacao_tj.livros_registros.0001","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (Tomo I), ao receber a petição inicial ou a denúncia, o ofício de justiça providenciará a autuação no prazo de","alternativas":{"A":"24 horas, afixando a etiqueta gerada pelo sistema e oriunda do distribuidor, que atribui número ao processo.","B":"48 horas, mediante certidão lavrada no interior dos autos.","C":"5 dias, após despacho do juiz.","D":"10 dias, contados da distribuição.","E":"1 hora, sob pena de responsabilidade do escrivão."},"gabarito":"A","explicacao":"O art. 87 fixa 24 horas para a autuação, com a etiqueta gerada pelo sistema e oriunda do distribuidor, que traz o número do processo, o juízo, a natureza do feito, as partes e a data. É dispensada certidão de autuação e registro no interior dos autos (parágrafo único).","explicacoes":{"A":"Correta: art. 87, caput.","B":"O prazo é de 24 horas, e a certidão de autuação é dispensada.","C":"O prazo é de 24 horas, sem depender de despacho.","D":"O prazo é de 24 horas.","E":"O prazo é de 24 horas."},"fonte":"NSCGJ, Tomo I, art. 87 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quando chega uma ação nova ou uma denúncia, o cartório tem vinte e quatro horas para montar a capa do processo, colando a etiqueta com o número e os dados principais.","teSitua":{"termos":[{"termo":"autuação","significado":"montagem da capa do processo, com seus dados de identificação."},{"termo":"denúncia","significado":"petição do Ministério Público que dá início à ação penal."},{"termo":"distribuidor","significado":"setor que reparte os processos novos entre as varas."}],"exemplo":"A petição inicial de uma ação de cobrança chegou ao cartório da 4ª Vara Cível numa terça às 10h. Até quarta às 10h, a escrevente Rosa fez a autuação, colando na capa a etiqueta com número, partes e natureza do feito."}},{"id":"aut.legislacao_tj.livros_registros.0002","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, é dispensada a lavratura de certidão, no interior dos autos, da autuação e do registro do processo.","gabarito":"C","explicacao":"É o que diz o parágrafo único do art. 87. A etiqueta afixada na autuação já contém os dados do processo.","fonte":"NSCGJ, Tomo I, art. 87, parágrafo único (consolidação de 2017)","mastigado":"Certo. O cartório não precisa escrever dentro do processo uma certidão dizendo que o autuou e registrou. A etiqueta da capa já mostra isso.","teSitua":{"termos":[{"termo":"lavratura de certidão","significado":"elaboração de documento oficial que atesta um fato."},{"termo":"autuação","significado":"montagem da capa do processo, com seus dados."}],"exemplo":"Ao autuar um novo processo, o escrevente Igor colou a etiqueta na capa e já o encaminhou para conclusão, sem redigir certidão de autuação no interior dos autos, como permitem as Normas."}},{"id":"aut.legislacao_tj.livros_registros.0003","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":3,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, o ofício de justiça afixará nas autuações tarjas coloridas, na posição vertical, apenas por determinação expressa do juiz em cada processo.","gabarito":"E","explicacao":"O art. 88 manda afixar tarjas coloridas na posição horizontal, para assinalar situações especiais descritas nas próprias Normas, sem exigir determinação do juiz caso a caso.","fonte":"NSCGJ, Tomo I, art. 88 (consolidação de 2017)","mastigado":"Errado. As tarjas coloridas vão na horizontal, e o cartório as coloca sempre que o processo estiver numa das situações especiais previstas nas Normas, como réu preso ou prioridade, sem precisar de ordem do juiz.","teSitua":{"termos":[{"termo":"tarjas coloridas","significado":"faixas de cor coladas na capa do processo para indicar situações especiais."},{"termo":"autuações","significado":"capas dos processos, com seus dados de identificação."}],"exemplo":"Num processo com réu preso, o escrevente Lauro colou na capa a tarja colorida horizontal prevista nas Normas, para que todos identificassem a urgência ao pegar os autos."}},{"id":"aut.legislacao_tj.livros_registros.0004","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os autos de processos físicos não excederão, em cada volume,","alternativas":{"A":"200 folhas, salvo determinação judicial expressa em contrário ou para manter peça processual com seus documentos anexos.","B":"100 folhas, sem exceção.","C":"300 folhas, salvo pedido da parte.","D":"500 folhas, em qualquer caso.","E":"150 folhas, salvo nos processos criminais."},"gabarito":"A","explicacao":"O art. 89 limita cada volume a 200 folhas, salvo determinação judicial ou para manter peça com seus anexos, podendo então ser encerrado com mais ou menos folhas. O encerramento e a abertura de volumes são certificados, e a numeração prossegue sem interrupção (§ 1º). Não confundir com o Livro de Visitas e Correições, limitado a 100 folhas (art. 67, § 2º).","explicacoes":{"A":"Correta: art. 89, caput.","B":"Cem folhas é o limite do Livro de Visitas e Correições (art. 67, § 2º).","C":"O limite é de 200 folhas.","D":"O limite é de 200 folhas.","E":"O limite é de 200 folhas para todos os processos."},"fonte":"NSCGJ, Tomo I, art. 89 (consolidação de 2017)","mastigado":"A resposta é a letra A. Cada volume de um processo em papel tem no máximo duzentas folhas. Pode passar um pouco disso se o juiz mandar ou para não separar uma petição dos seus documentos.","teSitua":{"termos":[{"termo":"volume","significado":"cada parte encadernada de um processo físico."},{"termo":"peça processual","significado":"documento apresentado no processo, como petição ou contestação."}],"exemplo":"O processo de inventário chegou à folha 196 quando foi juntada uma petição com dez folhas de documentos. Para não separar a petição dos anexos, o volume foi encerrado na folha 206, e o seguinte começou na 207."}},{"id":"aut.legislacao_tj.livros_registros.0005","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o encerramento e a abertura dos novos volumes serão certificados em folhas regularmente numeradas, prosseguindo-se a numeração sem solução de continuidade no volume subsequente.","gabarito":"C","explicacao":"É a regra do art. 89, § 1º. A numeração ordinal dos novos volumes é destacada nas respectivas autuações e anotada na autuação do primeiro volume (§ 2º).","fonte":"NSCGJ, Tomo I, art. 89, §§ 1º e 2º (consolidação de 2017)","mastigado":"Certo. Quando um volume termina, o novo continua a numeração do anterior, sem recomeçar do um. Se o primeiro acabou na folha duzentos, o segundo começa na duzentos e um.","teSitua":{"termos":[{"termo":"sem solução de continuidade","significado":"sem interrupção, seguindo a sequência anterior."},{"termo":"volume subsequente","significado":"volume seguinte do mesmo processo."}],"exemplo":"O primeiro volume de uma execução terminou na folha 200, com certidão de encerramento. O segundo volume foi aberto com certidão na folha 201, e a capa recebeu a indicação de 2º volume."}},{"id":"aut.legislacao_tj.livros_registros.0006","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Nos feitos antecedidos por procedimentos preparatórios, como inquérito policial, a peça inaugural (por exemplo, a denúncia), segundo as Normas de Serviço da Corregedoria Geral da Justiça,","alternativas":{"A":"terá numeração própria, com o número da folha seguido da letra “i” (1-i, 2-i...), aproveitando-se integralmente a numeração do procedimento preparatório.","B":"receberá a numeração seguinte à última folha do inquérito.","C":"será juntada ao final dos autos, sem numeração.","D":"obrigará a renumeração de todo o inquérito.","E":"terá numeração com a letra “d” (1-d, 2-d...)."},"gabarito":"A","explicacao":"O art. 90 manda dar à peça inaugural numeração própria, com a letra “i” após o número da folha (1-i; 2-i...), aproveitando-se integralmente a numeração dos procedimentos preparatórios (inquéritos civis, comunicações de atos infracionais, inquéritos policiais).","explicacoes":{"A":"Correta: art. 90.","B":"A peça inaugural tem numeração própria com a letra “i”.","C":"A peça é numerada.","D":"A numeração do procedimento preparatório é aproveitada integralmente.","E":"A letra prevista é “i”."},"fonte":"NSCGJ, Tomo I, art. 90 (consolidação de 2017)","mastigado":"A resposta é a letra A. O inquérito já vem numerado. Para não bagunçar essa numeração, a denúncia recebe números próprios com a letra i: folha 1-i, 2-i e assim por diante.","teSitua":{"termos":[{"termo":"procedimentos preparatórios","significado":"investigações feitas antes do processo, como o inquérito policial."},{"termo":"peça inaugural","significado":"documento que dá início ao processo, como a denúncia ou a petição inicial."},{"termo":"inquérito policial","significado":"investigação feita pela polícia para apurar um crime."}],"exemplo":"O inquérito policial chegou ao fórum com 85 folhas. A denúncia do promotor, de três folhas, recebeu os números 1-i, 2-i e 3-i, e a numeração do inquérito foi mantida intacta."}},{"id":"aut.legislacao_tj.livros_registros.0007","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Constatado erro na numeração das folhas dos autos, de acordo com as Normas de Serviço da Corregedoria Geral da Justiça,","alternativas":{"A":"certificar-se-á a ocorrência, sendo vedada a renumeração; havendo numeração repetida, acrescenta-se uma letra do alfabeto em sequência (188-a, 188-b...), certificando-se.","B":"renumeram-se todas as folhas a partir do erro.","C":"corrige-se com corretivo e nova anotação.","D":"desentranham-se as folhas com numeração errada.","E":"o processo é encaminhado à Corregedoria Geral para correção."},"gabarito":"A","explicacao":"O art. 91 atribui aos escrivães, ou aos escreventes sob sua supervisão, zelar pela numeração. Em caso de erro, certifica-se a ocorrência, vedada a renumeração (§ 1º); na numeração repetida, acrescenta-se uma letra em sequência, certificando-se (§ 2º). O uso de corretivo é vedado (art. 82, I).","explicacoes":{"A":"Correta: art. 91, §§ 1º e 2º.","B":"A renumeração é vedada.","C":"O corretivo é vedado (art. 82, I).","D":"Não há desentranhamento por erro de numeração.","E":"A correção é feita no próprio cartório, por certidão."},"fonte":"NSCGJ, Tomo I, art. 91 (consolidação de 2017)","mastigado":"A resposta é a letra A. Errou a numeração? Não se renumera o processo. Faz-se uma certidão explicando o erro. Se duas folhas ficaram com o mesmo número, a segunda vira 188-a, a terceira 188-b, sempre com certidão.","teSitua":{"termos":[{"termo":"renumeração","significado":"nova numeração das folhas, apagando a anterior."},{"termo":"certificar-se-á","significado":"será registrada em certidão, isto é, em documento oficial."}],"exemplo":"Ao conferir um processo, o escrevente Nilo viu que duas folhas tinham o número 188. Ele numerou a segunda como 188-a e lavrou certidão explicando a ocorrência, sem renumerar as folhas seguintes."}},{"id":"aut.legislacao_tj.livros_registros.0008","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, é vedado aos ofícios de justiça receber e juntar petições que não tenham sido encaminhadas pelo setor de protocolo, SALVO","alternativas":{"A":"as de juntada de procuração ou de substabelecimento apresentadas diretamente ao ofício, mencionando-se a circunstância no termo de juntada, ou quando houver decisão fundamentada do juiz dispensando o protocolo.","B":"as petições urgentes de qualquer natureza, a critério do escrevente.","C":"as petições apresentadas por advogados com mais de dez anos de inscrição.","D":"as petições do Ministério Público, que nunca passam pelo protocolo.","E":"as contestações, em qualquer caso."},"gabarito":"A","explicacao":"O art. 92 só admite juntada sem passagem pelo protocolo em dois casos: procuração ou substabelecimento apresentados diretamente pelo interessado, registrando-se o fato no termo de juntada (I), e decisão fundamentada do juiz no caso concreto (II).","explicacoes":{"A":"Correta: art. 92, I e II.","B":"A urgência não é exceção prevista, nem cabe ao escrevente decidir.","C":"Não há esse critério.","D":"Não há essa exceção.","E":"Contestações passam pelo protocolo."},"fonte":"NSCGJ, Tomo I, art. 92 (consolidação de 2017)","mastigado":"A resposta é a letra A. Toda petição entra pelo protocolo. O balcão do cartório só pode receber diretamente a procuração ou o substabelecimento do advogado, ou outra petição se o juiz, num caso concreto, autorizar de forma fundamentada.","teSitua":{"termos":[{"termo":"setor de protocolo","significado":"setor que registra a entrada de petições, com número e data."},{"termo":"substabelecimento","significado":"documento pelo qual o advogado transfere a outro os poderes recebidos do cliente."},{"termo":"termo de juntada","significado":"anotação que registra a inclusão de uma peça nos autos."}],"exemplo":"Um advogado foi ao balcão do cartório entregar a procuração do novo cliente. A escrevente a recebeu e juntou aos autos, anotando no termo de juntada que a peça foi entregue diretamente no ofício."}},{"id":"aut.legislacao_tj.livros_registros.0009","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, por ocasião da juntada de petições e documentos,","alternativas":{"A":"lavrar-se-á termo de juntada, sendo confeccionado um único termo, com a relação das peças, quando juntadas na mesma oportunidade duas ou mais, vedado o lançamento do termo na própria petição ou documento.","B":"dispensa-se o termo de juntada quando se tratar de laudo pericial.","C":"lavra-se um termo para cada petição, ainda que juntadas no mesmo momento.","D":"o termo de juntada será lançado no verso da própria petição.","E":"a juntada independe de qualquer registro."},"gabarito":"A","explicacao":"O art. 93 exige termo de juntada; para duas ou mais peças juntadas na mesma oportunidade, um único termo com a relação delas (§ 1º); é vedado lançar o termo na própria petição ou documento (§ 2º). Também é vedado lançar termos no verso de petições e documentos (art. 95).","explicacoes":{"A":"Correta: art. 93, caput e §§ 1º e 2º.","B":"Laudos também exigem termo de juntada (caput).","C":"Basta um termo para as peças juntadas ao mesmo tempo.","D":"É vedado lançar termos na própria petição ou no verso (arts. 93, § 2º, e 95).","E":"A juntada exige termo."},"fonte":"NSCGJ, Tomo I, arts. 93 e 95 (consolidação de 2017)","mastigado":"A resposta é a letra A. Juntou papéis no processo, faz um termo de juntada. Se foram vários ao mesmo tempo, basta um termo listando todos. E o termo vai em folha própria, nunca escrito em cima da petição.","teSitua":{"termos":[{"termo":"juntada","significado":"inclusão de petição ou documento nos autos do processo."},{"termo":"termo de juntada","significado":"anotação que registra a inclusão de peças nos autos."}],"exemplo":"Chegaram juntos ao cartório um laudo pericial e duas petições do mesmo processo. A escrevente Vera juntou os três e lavrou um único termo de juntada, listando cada peça, numa folha separada."}},{"id":"aut.legislacao_tj.livros_registros.0010","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":3,"enunciado":"Recebida petição acompanhada de objetos de inviável entranhamento aos autos, o escrivão, segundo as Normas de Serviço da Corregedoria Geral da Justiça, deverá conferi-los, arrolá-los e quantificá-los, lavrando certidão, sempre que possível na presença do interessado, e mantê-los sob sua guarda e responsabilidade até o encerramento da demanda.","gabarito":"C","explicacao":"É o que dispõe o art. 93, § 4º: o escrivão confere, arrola e quantifica os objetos que não podem ser entranhados, lavra certidão, de preferência na presença do interessado, e os guarda sob sua responsabilidade até o encerramento da demanda.","fonte":"NSCGJ, Tomo I, art. 93, § 4º (consolidação de 2017)","mastigado":"Certo. Se a parte entrega com a petição algo que não cabe no processo, como um pen drive ou um objeto, o escrivão confere, lista, conta e certifica, de preferência na frente de quem entregou, e guarda até o fim do processo.","teSitua":{"termos":[{"termo":"inviável entranhamento","significado":"impossibilidade de colocar o objeto dentro dos autos."},{"termo":"arrolar","significado":"relacionar em lista, um por um."},{"termo":"demanda","significado":"o processo judicial em andamento; a ação."}],"exemplo":"Com a petição inicial, o advogado entregou três amostras de piso defeituoso. O escrivão Caio conferiu e listou as peças na frente do advogado, lavrou certidão e guardou as amostras no cofre do cartório até o fim do processo."}},{"id":"aut.legislacao_tj.livros_registros.0011","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, todos os atos e termos do processo serão certificados nos autos e anotados no sistema informatizado, sem qualquer exceção, inclusive quanto à emissão de ofícios e mandados que passem imediatamente a integrar os autos.","gabarito":"E","explicacao":"O art. 94 exige certificação e anotação dos atos e termos, mas o parágrafo único dispensa essa providência quanto à emissão de documento que passe imediatamente a integrar os autos (ofícios expedidos, mandados etc.), por original ou cópia rubricada pelo emitente, desde que a data corresponda à efetiva emissão.","fonte":"NSCGJ, Tomo I, art. 94 e parágrafo único (consolidação de 2017)","mastigado":"Errado. Há exceção: se o ofício ou mandado expedido já vai direto para dentro do processo, original ou cópia rubricada, não é preciso fazer certidão dizendo que foi expedido. A data do documento deve ser a do dia em que saiu.","teSitua":{"termos":[{"termo":"certificados","significado":"registrados em certidão nos autos."},{"termo":"mandados","significado":"ordens escritas do juiz para que o oficial de justiça pratique um ato."}],"exemplo":"A escrevente Lia expediu um ofício ao banco e juntou a cópia rubricada aos autos, com a data daquele dia. Ela não precisou lavrar certidão de expedição do ofício, porque a própria cópia já integra o processo."}},{"id":"aut.legislacao_tj.livros_registros.0012","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":2,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, ressalvadas as hipóteses expressamente previstas, é vedado o lançamento de termos no verso de petições, documentos e guias, devendo ser usada, quando necessária, outra folha, com inutilização dos espaços em branco.","gabarito":"C","explicacao":"É a regra do art. 95, que ressalva o disposto no art. 140 das Normas.","fonte":"NSCGJ, Tomo I, art. 95 (consolidação de 2017)","mastigado":"Certo. O cartório não escreve termos atrás de petições ou guias. Usa outra folha e risca os espaços que sobrarem em branco, para que ninguém escreva ali depois.","teSitua":{"termos":[{"termo":"verso","significado":"lado de trás da folha."},{"termo":"inutilização dos espaços em branco","significado":"traço ou marca nas áreas vazias para impedir anotações posteriores."}],"exemplo":"O escrevente Davi ia escrever o termo de vista no verso de uma guia de custas. Lembrou da proibição, usou uma folha nova, lavrou o termo e passou um traço no espaço que sobrou."}},{"id":"aut.legislacao_tj.livros_registros.0013","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Ao examinar autos, o escrevente percebeu que um advogado fez anotações à margem de documentos e sublinhou palavras a caneta. Segundo as Normas de Serviço da Corregedoria Geral da Justiça, ele deverá","alternativas":{"A":"comunicar imediatamente a irregularidade ao juiz, pois são vedadas cotas marginais ou interlineares e a prática de sublinhar palavras nos autos.","B":"apagar as anotações com corretivo.","C":"desentranhar as folhas anotadas e devolvê-las ao advogado.","D":"ignorar as anotações, por se tratar de prática permitida.","E":"aplicar multa ao advogado."},"gabarito":"A","explicacao":"O art. 96 veda cotas marginais ou interlineares, sublinhar palavras à tinta ou a lápis e expressões injuriosas nos escritos, incumbindo ao serventuário comunicar imediatamente a irregularidade ao juiz. O corretivo é vedado (art. 82, I).","explicacoes":{"A":"Correta: art. 96.","B":"O corretivo é vedado (art. 82, I).","C":"A providência prevista é comunicar o juiz.","D":"A prática é vedada.","E":"O servidor não aplica sanção; comunica o juiz."},"fonte":"NSCGJ, Tomo I, art. 96 (consolidação de 2017)","mastigado":"A resposta é a letra A. Ninguém pode rabiscar os autos, escrever na margem ou sublinhar palavras. Quando o servidor vê isso, não corrige por conta própria: avisa o juiz na hora.","teSitua":{"termos":[{"termo":"cotas marginais ou interlineares","significado":"anotações feitas nas margens ou entre as linhas dos documentos."}],"exemplo":"Ao receber os autos de volta de uma carga, a escrevente Inês notou que trechos da sentença estavam sublinhados a caneta e havia comentários na margem. Ela comunicou o fato ao juiz no mesmo dia."}},{"id":"aut.legislacao_tj.livros_registros.0014","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, deverá ser feita a conclusão dos autos e executados os atos processuais, respectivamente, nos prazos de","alternativas":{"A":"1 dia e 5 dias.","B":"2 dias e 10 dias.","C":"5 dias e 1 dia.","D":"24 horas e 48 horas.","E":"3 dias e 15 dias."},"gabarito":"A","explicacao":"O art. 97 fixa 1 dia para a conclusão dos autos e 5 dias para a execução dos atos processuais. Os juízes atendem preferencialmente à ordem cronológica de conclusão para sentenciar (§ 1º), e o escrivão à ordem cronológica de recebimento para publicar e efetivar os pronunciamentos (§ 2º).","explicacoes":{"A":"Correta: art. 97, caput.","B":"Os prazos são de 1 e 5 dias.","C":"Os prazos estão invertidos.","D":"Os prazos são de 1 e 5 dias.","E":"Os prazos são de 1 e 5 dias."},"fonte":"NSCGJ, Tomo I, art. 97 (consolidação de 2017)","mastigado":"A resposta é a letra A. O cartório tem um dia para levar o processo ao juiz e cinco dias para cumprir o que o juiz mandou. São prazos curtos, para que o processo não fique parado na prateleira.","teSitua":{"termos":[{"termo":"conclusão dos autos","significado":"envio do processo ao juiz para que ele decida ou despache."},{"termo":"atos processuais","significado":"providências praticadas no processo, como intimações e expedições."}],"exemplo":"Uma petição pedindo liminar foi juntada numa segunda-feira. Na terça, o processo foi concluso ao juiz, que despachou. O cartório cumpriu o despacho, expedindo o mandado, até a segunda-feira seguinte."}},{"id":"aut.legislacao_tj.livros_registros.0015","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o escrivão atenderá, preferencialmente, à ordem cronológica de recebimento para publicação e efetivação dos pronunciamentos judiciais.","gabarito":"C","explicacao":"É a regra do art. 97, § 2º, paralela à preferência dos juízes pela ordem cronológica de conclusão para proferir sentença ou acórdão (§ 1º).","fonte":"NSCGJ, Tomo I, art. 97, § 2º (consolidação de 2017)","mastigado":"Certo. O cartório deve, de preferência, cumprir as decisões na ordem em que chegaram: o que veio primeiro é publicado e cumprido primeiro. Isso evita que um processo fure a fila sem motivo.","teSitua":{"termos":[{"termo":"ordem cronológica","significado":"ordem de acordo com a data de chegada."},{"termo":"pronunciamentos judiciais","significado":"atos do juiz no processo, como despachos, decisões e sentenças."}],"exemplo":"Na segunda-feira, o juiz devolveu ao cartório vinte processos despachados. A escrevente Tânia publicou e cumpriu os despachos na ordem em que os processos foram recebidos, começando pelos que chegaram primeiro."}},{"id":"aut.legislacao_tj.livros_registros.0016","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Quanto aos termos de movimentação dos processos, as Normas de Serviço da Corregedoria Geral da Justiça estabelecem que","alternativas":{"A":"são vedados termos de conclusão ou de vista sem data, bem como a permanência dos autos em cartório depois de assinados os respectivos termos.","B":"os termos de vista podem ser lançados sem data, se urgente.","C":"os autos podem permanecer em cartório após o termo de conclusão, até o fim da semana.","D":"dispensa-se o nome de quem recebe os autos.","E":"os termos de movimentação são facultativos."},"gabarito":"A","explicacao":"O art. 98 exige nos termos de movimentação a data do efetivo encaminhamento e, sempre que possível, os nomes por extenso de juízes, promotores, advogados ou outros destinatários. O § 1º veda termos de conclusão ou de vista sem data e a permanência dos autos no cartório depois de assinados os termos.","explicacoes":{"A":"Correta: art. 98, § 1º.","B":"É vedado, sob qualquer pretexto, termo sem data.","C":"Os autos não podem permanecer em cartório depois de assinado o termo.","D":"Os nomes devem constar sempre que possível.","E":"Os termos são obrigatórios."},"fonte":"NSCGJ, Tomo I, art. 98, caput e § 1º (consolidação de 2017)","mastigado":"A resposta é a letra A. Todo termo de conclusão ou de vista precisa ter data. E, se o termo diz que o processo foi para o juiz ou para o advogado, ele não pode ficar parado no cartório: tem de ir mesmo.","teSitua":{"termos":[{"termo":"termos de conclusão","significado":"anotações que registram o envio do processo ao juiz."},{"termo":"termo de vista","significado":"anotação que registra a entrega do processo para manifestação de alguém."}],"exemplo":"Na correição, o juiz encontrou processos com termo de conclusão assinado havia uma semana, mas ainda na prateleira do cartório. Ele determinou a correção, porque é vedado manter os autos em cartório depois de assinado o termo."}},{"id":"aut.legislacao_tj.livros_registros.0017","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":2,"enunciado":"Um advogado pede vista de autos físicos no balcão do cartório. Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o processo","alternativas":{"A":"não será entregue com termo de vista sem prévia assinatura no livro de carga ou no relatório de carga eletrônica e correspondente andamento no sistema informatizado.","B":"pode ser entregue mediante simples identificação verbal do advogado.","C":"só pode ser entregue com autorização escrita do juiz em cada caso.","D":"deve ser consultado apenas por meio de cópias.","E":"pode ser entregue sem registro, se devolvido no mesmo dia."},"gabarito":"A","explicacao":"O art. 98, § 2º, proíbe entregar processo com termo de vista a promotor ou advogado sem prévia assinatura no livro de carga ou no relatório de carga eletrônica e o correspondente andamento no sistema. O Regimento Interno também exige registro de carga para saída de autos (art. 174).","explicacoes":{"A":"Correta: art. 98, § 2º.","B":"É necessária a assinatura no livro ou relatório de carga.","C":"O termo de vista, com carga regular, não depende de autorização do juiz em cada caso.","D":"Não há essa restrição.","E":"A carga deve sempre ser registrada."},"fonte":"NSCGJ, Tomo I, art. 98, § 2º (consolidação de 2017)","mastigado":"A resposta é a letra A. O processo físico só sai do cartório com o advogado depois que ele assina a carga, no livro ou no relatório eletrônico, e o cartório lança o andamento no sistema. Assim se sabe sempre onde o processo está.","teSitua":{"termos":[{"termo":"vista","significado":"entrega do processo para que alguém se manifeste nele."},{"termo":"livro de carga","significado":"livro que registra a retirada e a devolução de autos."},{"termo":"carga eletrônica","significado":"registro da retirada dos autos feito diretamente no sistema."}],"exemplo":"O advogado Marcelo pediu vista dos autos físicos para preparar a apelação. O escrevente lançou o termo de vista, colheu a assinatura dele no relatório de carga e registrou o andamento no sistema antes de entregar o processo."}},{"id":"aut.legislacao_tj.livros_registros.0018","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, a conclusão dos autos ao juiz será efetuada semanalmente, limitada a cinquenta processos por vez.","gabarito":"E","explicacao":"O art. 98, § 5º, determina que a conclusão dos autos ao juiz seja efetuada diariamente, sem limitação de número. Todas as conclusões são anotadas no sistema, acrescendo-se a carga apenas quanto aos autos não despachados ou sentenciados até o fim do expediente (§ 3º).","fonte":"NSCGJ, Tomo I, art. 98, §§ 3º e 5º (consolidação de 2017)","mastigado":"Errado. O cartório faz conclusão ao juiz todos os dias, sem limite de quantidade. Não pode segurar processos para mandar em lotes semanais.","teSitua":{"termos":[{"termo":"conclusão dos autos","significado":"envio do processo ao juiz para decisão ou despacho."},{"termo":"semanalmente","significado":"uma vez por semana, em dia certo."}],"exemplo":"A chefe do cartório queria enviar os processos ao juiz só às sextas, em lotes de cinquenta. O juiz corregedor determinou a mudança: as conclusões devem ser feitas diariamente, sem limitação de número."}},{"id":"aut.legislacao_tj.livros_registros.0019","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, nenhum processo permanecerá paralisado em cartório além dos prazos legais ou fixados, nem ficará sem andamento por mais de","alternativas":{"A":"30 dias no aguardo de diligências; decorrido esse prazo, o ofício reiterará a diligência uma única vez e, não atendida, abrirá conclusão ao juiz.","B":"60 dias, reiterando-se a diligência quantas vezes forem necessárias.","C":"90 dias, sem necessidade de reiteração.","D":"15 dias, com arquivamento automático.","E":"120 dias, quando houver ofício pendente."},"gabarito":"A","explicacao":"O art. 99 proíbe deixar o processo sem andamento por mais de 30 dias aguardando diligências (informações, respostas a ofícios, providências das partes etc.). Decorrido o prazo, o ofício reitera a diligência uma única vez e, não atendida, abre conclusão ao juiz (parágrafo único).","explicacoes":{"A":"Correta: art. 99 e parágrafo único.","B":"O prazo é de 30 dias, e a reiteração é única.","C":"O prazo é de 30 dias, com reiteração.","D":"O prazo é de 30 dias, e não há arquivamento automático.","E":"O prazo é de 30 dias."},"fonte":"NSCGJ, Tomo I, art. 99 (consolidação de 2017)","mastigado":"A resposta é a letra A. O processo não pode ficar mais de trinta dias parado esperando uma resposta. Passado esse tempo, o cartório cobra uma vez. Se ainda assim não vier, leva o processo ao juiz para decidir o que fazer.","teSitua":{"termos":[{"termo":"paralisado","significado":"parado, sem nenhum andamento no cartório."},{"termo":"diligências","significado":"providências necessárias ao processo, como pedidos de informação."},{"termo":"reiterará","significado":"repetirá o pedido feito anteriormente."}],"exemplo":"O cartório oficiou a um banco pedindo extratos em 2 de maio. Sem resposta, em 2 de junho reiterou o ofício. Como o banco continuou sem responder, os autos foram conclusos ao juiz em julho."}},{"id":"aut.legislacao_tj.livros_registros.0020","subtopico":"legislacao_tj.nscgj.livros_registros","tipo":"multipla","dificuldade":3,"enunciado":"Se o juiz se recusar a assinar a carga de autos conclusos que não receberam despacho até o final do expediente, segundo as Normas de Serviço da Corregedoria Geral da Justiça,","alternativas":{"A":"consignar-se-á essa ocorrência no assentamento da carga.","B":"os autos serão devolvidos ao cartório sem registro.","C":"o escrivão comunicará o fato ao Presidente do Tribunal.","D":"a conclusão será considerada inexistente.","E":"o processo será redistribuído a outro juiz."},"gabarito":"A","explicacao":"O art. 98, § 3º, manda anotar todas as conclusões no sistema e acrescer a carga quanto aos autos conclusos não despachados ou sentenciados até o fim do expediente; o § 4º diz que, se o juiz se recusar a assinar, a ocorrência será consignada no assentamento da carga.","explicacoes":{"A":"Correta: art. 98, § 4º.","B":"A recusa é registrada, e não se deixa de registrar a carga.","C":"A providência prevista é registrar no assentamento da carga.","D":"A conclusão permanece registrada.","E":"Não há redistribuição por esse motivo."},"fonte":"NSCGJ, Tomo I, art. 98, §§ 3º e 4º (consolidação de 2017)","mastigado":"A resposta é a letra A. Se o processo ficou com o juiz sem despacho até o fim do dia, registra-se a carga para ele. Se o juiz não quiser assinar, o cartório anota essa recusa no próprio registro da carga.","teSitua":{"termos":[{"termo":"carga","significado":"registro de que os autos estão sob a responsabilidade de alguém."},{"termo":"autos conclusos","significado":"processos que foram enviados ao juiz para decisão."},{"termo":"assentamento","significado":"registro escrito de um fato."}],"exemplo":"Ao fim do expediente, vinte processos físicos conclusos continuavam no gabinete sem despacho. O escrivão preparou a carga para o juiz, que se recusou a assinar. O escrivão anotou a recusa no registro da carga."}},{"id":"aut.legislacao_tj.oficios_organizacao.0001","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (Tomo I), as disposições do capítulo dos ofícios de justiça em geral têm caráter geral e aplicam-se a todos os ofícios de justiça, no que não contrariarem as disposições específicas contidas em capítulo próprio.","gabarito":"C","explicacao":"É o que diz o art. 26. As regras específicas de cada tipo de ofício (cível, criminal, família etc.) estão no Capítulo IV e prevalecem naquilo que dispuserem de modo diverso.","fonte":"NSCGJ, Tomo I, art. 26 (consolidação de 2017)","mastigado":"Certo. As regras do capítulo dos ofícios em geral valem para todos os cartórios judiciais. Mas, se o capítulo próprio de um tipo de cartório disser algo diferente, vale a regra específica.","teSitua":{"termos":[{"termo":"ofícios de justiça","significado":"cartórios judiciais que dão andamento aos processos de uma vara."},{"termo":"caráter geral","significado":"aplicação a todos os casos, salvo regra especial em contrário."}],"exemplo":"Uma regra geral sobre escrituração vale para o cartório cível e para o criminal de Ourinhos. Mas, se o capítulo próprio dos ofícios criminais tiver regra diferente sobre determinado livro, o cartório criminal segue a regra específica."}},{"id":"aut.legislacao_tj.oficios_organizacao.0002","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os servidores da justiça darão atendimento prioritário","alternativas":{"A":"às pessoas com deficiência, aos idosos, às gestantes, às lactantes e às pessoas acompanhadas por crianças de colo.","B":"apenas aos advogados e membros do Ministério Público.","C":"somente às pessoas maiores de 80 anos.","D":"às partes que chegarem primeiro, sem preferências.","E":"apenas às gestantes e aos idosos."},"gabarito":"A","explicacao":"O art. 27 garante atendimento prioritário às pessoas com deficiência, aos idosos, às gestantes, às lactantes e às pessoas acompanhadas por crianças de colo, mediante lugar privilegiado em filas, senhas próprias, espaço exclusivo no balcão ou outro sistema que assegure a prioridade.","explicacoes":{"A":"Correta: art. 27.","B":"A prioridade do art. 27 é para pessoas em situação de vulnerabilidade, não para profissionais.","C":"O art. 27 abrange os idosos em geral, não só os maiores de 80 anos.","D":"Há preferências obrigatórias.","E":"A lista é mais ampla."},"fonte":"NSCGJ, Tomo I, art. 27 (consolidação de 2017)","mastigado":"A resposta é a letra A. No balcão do cartório, têm prioridade pessoas com deficiência, idosos, grávidas, mulheres que amamentam e quem está com criança de colo. O cartório deve organizar fila, senha ou espaço próprio para isso.","teSitua":{"termos":[{"termo":"atendimento prioritário","significado":"atendimento antes dos demais, garantido por lei a certos grupos."},{"termo":"lactantes","significado":"mulheres que estão amamentando seus bebês."},{"termo":"crianças de colo","significado":"crianças pequenas que ainda são carregadas no colo."}],"exemplo":"No balcão do fórum de Guarulhos, Dona Iracema, de 72 anos, e uma mãe com o bebê no colo chegaram depois de outras pessoas. O escrevente as atendeu primeiro, usando a fila preferencial prevista nas Normas."}},{"id":"aut.legislacao_tj.oficios_organizacao.0003","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, nas comarcas e foros distritais com mais de uma vara, haverá um ofício ou seção de distribuição judicial, ao qual incumbem","alternativas":{"A":"os serviços de distribuição, de contadoria e partidoria e, nos termos da lei, do arquivo geral; nas comarcas de vara e ofício únicos, essas atribuições competem ao próprio ofício de justiça.","B":"apenas os serviços de protocolo de petições.","C":"os serviços de expedição de mandados e de intimação pessoal.","D":"os serviços de execução criminal.","E":"os serviços de corregedoria permanente."},"gabarito":"A","explicacao":"O art. 29, § 1º, atribui ao ofício ou seção de distribuição judicial a distribuição, a contadoria e partidoria e, nos termos da lei, o arquivo geral. Em comarcas com uma única vara e um único ofício, este assume a distribuição, a contadoria e a partidoria (§ 2º). Aos ofícios competem os serviços do foro judicial, com numeração ordinal e denominação da vara (caput).","explicacoes":{"A":"Correta: art. 29, §§ 1º e 2º.","B":"As atribuições são mais amplas.","C":"Não são atribuições da distribuição.","D":"Não é atribuição da distribuição.","E":"A corregedoria permanente é função do juiz (art. 7º)."},"fonte":"NSCGJ, Tomo I, art. 29 (consolidação de 2017)","mastigado":"A resposta é a letra A. Onde há várias varas, um setor de distribuição reparte os processos, faz as contas de custas e partilhas e cuida do arquivo geral. Onde só há uma vara, o próprio cartório faz tudo isso.","teSitua":{"termos":[{"termo":"distribuição judicial","significado":"serviço que reparte os processos novos entre as varas."},{"termo":"contadoria e partidoria","significado":"serviços que fazem cálculos de custas e dívidas e a divisão de bens em partilhas."},{"termo":"foros distritais","significado":"unidades do fórum instaladas em distritos de uma comarca."}],"exemplo":"Na comarca de Piracicaba, com várias varas, a seção de distribuição recebe as ações novas, faz os cálculos da contadoria e cuida do arquivo geral. Em Pedregulho, de vara única, o próprio cartório da vara faz esses serviços."}},{"id":"aut.legislacao_tj.oficios_organizacao.0004","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, é vedado ao funcionário credenciado ceder a respectiva senha ou permitir que outrem, funcionário ou não, use-a para acessar indevidamente o sistema informatizado.","gabarito":"C","explicacao":"É o que dispõe o art. 49, § 1º. Os escrivães devem comunicar prontamente as alterações no quadro funcional da unidade, para revogação ou novo credenciamento (§ 2º).","fonte":"NSCGJ, Tomo I, art. 49, §§ 1º e 2º (consolidação de 2017)","mastigado":"Certo. A senha do sistema é pessoal. O servidor não pode emprestá-la a ninguém, nem a colega, porque tudo o que é feito no sistema fica registrado em nome de quem é dono da senha.","teSitua":{"termos":[{"termo":"credenciado","significado":"autorizado oficialmente a acessar o sistema, com senha própria."},{"termo":"sistema informatizado","significado":"programa eletrônico usado pelo cartório para registrar e movimentar processos."}],"exemplo":"O escrevente Jair estava de férias e deixou a senha com o colega Mauro para adiantar o serviço. A conduta é proibida, porque a senha é pessoal e não pode ser usada por outra pessoa."}},{"id":"aut.legislacao_tj.oficios_organizacao.0005","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os dados retificados, alterados ou excluídos no sistema informatizado não são conservados, e as operações realizadas não ficam vinculadas ao usuário que as realiza.","gabarito":"E","explicacao":"O art. 50 determina o contrário: os dados retificados, alterados ou excluídos serão conservados pelo sistema, e todas as operações ficam vinculadas ao usuário que as realiza. As alterações seguem níveis de criticidade definidos pela Corregedoria Geral.","fonte":"NSCGJ, Tomo I, art. 50 (consolidação de 2017)","mastigado":"Errado. Tudo o que se muda ou apaga no sistema fica guardado, e cada operação aparece ligada ao servidor que a fez. Isso permite saber quem alterou o quê.","teSitua":{"termos":[{"termo":"retificados","significado":"corrigidos após terem sido lançados com erro."},{"termo":"sistema informatizado","significado":"programa eletrônico usado pelo cartório para registrar e movimentar processos."}],"exemplo":"Uma data de audiência foi alterada no sistema sem explicação. Na consulta ao histórico, o escrivão viu o dado anterior, que ficou guardado, e o nome da servidora que fez a alteração."}},{"id":"aut.legislacao_tj.oficios_organizacao.0006","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os escrivães judiciais do serviço de distribuição e dos ofícios de justiça realizarão auditoria no sistema informatizado","alternativas":{"A":"semanalmente, de acordo com os níveis de criticidade definidos, comunicando à Corregedoria Geral qualquer irregularidade.","B":"anualmente, por ocasião da correição ordinária.","C":"mensalmente, apenas se houver reclamação.","D":"diariamente, enviando relatório ao Presidente do Tribunal.","E":"semestralmente, mediante autorização do juiz."},"gabarito":"A","explicacao":"O art. 51 prevê auditoria semanal no sistema, segundo os níveis de criticidade, com comunicação de irregularidades à Corregedoria Geral da Justiça.","explicacoes":{"A":"Correta: art. 51.","B":"A auditoria é semanal.","C":"A auditoria é semanal e obrigatória.","D":"A auditoria é semanal, e a comunicação é à Corregedoria Geral.","E":"A auditoria é semanal."},"fonte":"NSCGJ, Tomo I, art. 51 (consolidação de 2017)","mastigado":"A resposta é a letra A. Toda semana, o escrivão confere no sistema as alterações mais sensíveis feitas na unidade. Se achar algo errado, avisa a Corregedoria Geral.","teSitua":{"termos":[{"termo":"auditoria","significado":"verificação sistemática dos registros para detectar erros ou irregularidades."},{"termo":"níveis de criticidade","significado":"graus de importância das alterações feitas no sistema."}],"exemplo":"Toda sexta-feira, o escrivão Ademar confere o relatório de alterações sensíveis feitas no sistema pelo cartório. Numa delas, achou uma exclusão de parte sem justificativa e comunicou à Corregedoria Geral."}},{"id":"aut.legislacao_tj.oficios_organizacao.0007","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, não será admitida exclusão de parte no processo cadastrado no sistema informatizado, procedendo-se à sua baixa, quando necessário.","gabarito":"C","explicacao":"É o que diz o art. 54, § 2º. O § 1º manda cadastrar todos os litisconsortes, intervenientes e terceiros interessados, bem como seus representantes.","fonte":"NSCGJ, Tomo I, art. 54, §§ 1º e 2º (consolidação de 2017)","mastigado":"Certo. Se uma parte deixa o processo, o cartório não apaga o nome dela do sistema: faz a baixa. Assim fica o histórico de quem participou do processo.","teSitua":{"termos":[{"termo":"exclusão de parte","significado":"retirada total do nome de uma parte dos registros do processo."},{"termo":"baixa","significado":"anotação de que a parte deixou de figurar no processo, mantendo o registro histórico."}],"exemplo":"Na ação contra duas empresas, o autor desistiu do pedido contra a empresa Beta. O escrevente não apagou a Beta do cadastro, mas lançou a baixa, mantendo o registro de que ela participou do processo."}},{"id":"aut.legislacao_tj.oficios_organizacao.0008","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, as vítimas identificadas na denúncia ou queixa e as testemunhas de processo criminal terão suas qualificações lançadas no sistema informatizado,","alternativas":{"A":"exceto quando, ao darem conta de coação ou grave ameaça, após deferimento do juiz, pedirem para não haver identificação de seus dados de qualificação e endereço.","B":"em nenhuma hipótese, por se tratar de dados sigilosos.","C":"apenas se forem testemunhas de acusação.","D":"somente após o trânsito em julgado da sentença.","E":"exceto quando o escrivão entender conveniente omiti-las."},"gabarito":"A","explicacao":"O art. 55, § 3º, manda lançar a qualificação das vítimas e das testemunhas de acusação, defesa ou comuns, exceto quando, relatando coação ou grave ameaça, após deferimento do juiz, pedirem a não identificação de seus dados e endereço.","explicacoes":{"A":"Correta: art. 55, § 3º.","B":"A regra é o lançamento dos dados.","C":"Abrange testemunhas de acusação, defesa ou comuns.","D":"Não há essa condição.","E":"A exceção depende de pedido da pessoa e deferimento do juiz, não de critério do escrivão."},"fonte":"NSCGJ, Tomo I, art. 55, § 3º (consolidação de 2017)","mastigado":"A resposta é a letra A. Em regra, os dados de vítimas e testemunhas entram no sistema. Mas, se a pessoa diz que está sendo ameaçada e o juiz concorda, seu nome e endereço ficam fora do cadastro, para protegê-la.","teSitua":{"termos":[{"termo":"denúncia ou queixa","significado":"petição que dá início à ação penal, pelo Ministério Público ou pela vítima."},{"termo":"qualificações","significado":"dados de identificação da pessoa, como nome, documentos e endereço."},{"termo":"coação","significado":"pressão ou ameaça para obrigar alguém a fazer ou deixar de fazer algo."}],"exemplo":"A testemunha Laura contou ao juiz que vinha recebendo ameaças do réu e pediu sigilo de seus dados. O juiz deferiu, e o escrevente deixou de lançar seu endereço e qualificação no sistema."}},{"id":"aut.legislacao_tj.oficios_organizacao.0009","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os dados obrigatórios de qualificação das partes serão apresentados","alternativas":{"A":"pelos requerentes, na petição inicial, e pelos requeridos, na primeira oportunidade de postulação em juízo, dispensando-se a exigência quando comprometer o acesso à Justiça, a critério do juiz, ou quando a parte não for inscrita no CPF ou CNPJ, mediante declaração.","B":"apenas pelos requerentes, sendo vedado exigi-los dos requeridos.","C":"exclusivamente pelo cartório, que deverá pesquisá-los em cadastros públicos.","D":"somente na fase de cumprimento de sentença.","E":"pelas partes, sem qualquer exceção, sob pena de extinção do processo."},"gabarito":"A","explicacao":"O art. 56 exige os dados do requerente na inicial e do requerido na primeira oportunidade de postulação (contestação, procuração, pedido de vista etc.). O § 1º dispensa a obrigação quando comprometer o acesso à Justiça, conforme prudente arbítrio do juiz, ou quando a parte não estiver inscrita no CPF ou CNPJ, firmando declaração; nesses casos, cabem outros dados de individualização (§ 2º).","explicacoes":{"A":"Correta: art. 56, caput e §§ 1º e 2º.","B":"Os requeridos também devem apresentá-los.","C":"Os dados são apresentados pelas partes; o cadastramento cabe ao cartório (art. 55, § 2º).","D":"Os dados são apresentados desde o início.","E":"Há exceções expressas no § 1º."},"fonte":"NSCGJ, Tomo I, art. 56 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quem entra com a ação informa seus dados na petição inicial, e quem é processado, na primeira vez que se manifesta. Se isso dificultar o acesso à Justiça ou se a pessoa não tiver CPF, há dispensa, mas ela deve dar outros dados para ser identificada.","teSitua":{"termos":[{"termo":"requerentes","significado":"pessoas que pedem algo ao juiz, como o autor da ação."},{"termo":"postulação em juízo","significado":"manifestação da parte no processo, pedindo ou defendendo algo."},{"termo":"CNPJ","significado":"número de cadastro das pessoas jurídicas na Receita Federal."}],"exemplo":"O morador de rua Joaquim pediu medicamentos ao Estado, mas não tinha CPF. Ele assinou declaração dizendo que não era inscrito e informou nome dos pais e data de nascimento, permitindo seu cadastro no processo."}},{"id":"aut.legislacao_tj.oficios_organizacao.0010","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, compete aos ofícios de justiça cadastrar no sistema informatizado a decretação do segredo de justiça, a concessão da justiça gratuita e o deferimento da tramitação prioritária do processo, entre outros benefícios processuais.","gabarito":"C","explicacao":"É o que dispõe o art. 61, III. O segredo de justiça pode também ser gerado automaticamente pelo sistema, conforme a natureza da ação (§ 2º).","fonte":"NSCGJ, Tomo I, art. 61, III e § 2º (consolidação de 2017)","mastigado":"Certo. Quando o juiz decreta segredo de justiça, concede justiça gratuita ou dá prioridade ao processo, o cartório tem de lançar isso no sistema. Assim todos sabem como tratar aquele processo.","teSitua":{"termos":[{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, que só as partes e advogados podem consultar."},{"termo":"justiça gratuita","significado":"benefício que dispensa a parte de pagar custas e despesas do processo."},{"termo":"tramitação prioritária","significado":"andamento mais rápido garantido por lei a idosos e outras pessoas."}],"exemplo":"O juiz concedeu prioridade ao processo de Dona Zélia, de 81 anos, e justiça gratuita. A escrevente lançou as duas informações no cadastro do processo, que passou a aparecer destacado no sistema."}},{"id":"aut.legislacao_tj.oficios_organizacao.0011","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os ofícios de justiça em geral possuirão, entre outros, os seguintes livros:","alternativas":{"A":"Visitas e Correições; Protocolo de Autos e Papéis em Geral; Cargas de Autos; Registro de Feitos Administrativos.","B":"Registro de Imóveis; Notas; Protestos.","C":"Registro Civil de Pessoas Naturais; Casamentos.","D":"Ponto Eletrônico; Férias; Licenças.","E":"Tombo de Bens Particulares; Inventário de Advogados."},"gabarito":"A","explicacao":"O art. 63 lista: Visitas e Correições (I); Protocolo de Autos e Papéis em Geral (II); Cargas de Autos (III); Registro de Feitos Administrativos (IV); Registro das decisões terminativas em feitos administrativos (V); e os da Corregedoria Permanente do art. 23, quando for o caso (VI). O art. 64 acrescenta, entre outros, o Livro de Cargas de Mandados.","explicacoes":{"A":"Correta: art. 63, I a IV.","B":"São livros de serventias extrajudiciais, não dos ofícios de justiça.","C":"São livros do registro civil, serviço extrajudicial.","D":"Não constam do art. 63.","E":"Não constam do art. 63."},"fonte":"NSCGJ, Tomo I, arts. 63 e 64 (consolidação de 2017)","mastigado":"A resposta é a letra A. Todo cartório judicial tem livros básicos: o de visitas e correições, o de protocolo, o de cargas de autos e o de registro de feitos administrativos. Livros de imóveis, notas e casamentos são de cartórios extrajudiciais.","teSitua":{"termos":[{"termo":"Visitas e Correições","significado":"livro em que se registram as fiscalizações feitas na unidade."},{"termo":"Cargas de Autos","significado":"livro que registra a retirada e a devolução de processos."},{"termo":"Feitos Administrativos","significado":"procedimentos não judiciais, como sindicâncias e representações."}],"exemplo":"Na correição, o juiz pediu ao escrivão Otávio os livros de visitas e correições, de protocolo, de cargas de autos e de registro de feitos administrativos do cartório. Todos estavam em ordem."}},{"id":"aut.legislacao_tj.oficios_organizacao.0012","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os livros em geral, inclusive de folhas soltas,","alternativas":{"A":"serão abertos, numerados, autenticados e encerrados pelo escrivão judicial, sempre na mesma oportunidade, vedada a substituição de folhas.","B":"serão abertos pelo juiz e encerrados pelo escrevente mais antigo.","C":"dispensam abertura e encerramento, se mantidos em folhas soltas.","D":"podem ter folhas substituídas, se houver erro, mediante autorização verbal do escrivão.","E":"serão autenticados exclusivamente pela Corregedoria Geral."},"gabarito":"A","explicacao":"O art. 66 atribui ao escrivão judicial abrir, numerar, autenticar e encerrar os livros, sempre na mesma oportunidade, admitido processo mecânico de autenticação aprovado pelo juiz corregedor, vedada a substituição de folhas. As folhas soltas, completado o uso, vão para encadernação (parágrafo único).","explicacoes":{"A":"Correta: art. 66.","B":"Todos esses atos cabem ao escrivão.","C":"Os livros de folhas soltas também são abertos e encerrados.","D":"É vedada a substituição de folhas.","E":"A autenticação é feita pelo escrivão."},"fonte":"NSCGJ, Tomo I, art. 66 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quem abre, numera, autentica e fecha os livros do cartório é o escrivão, tudo de uma vez. E não se pode trocar folhas, para garantir que nada seja apagado ou inserido depois.","teSitua":{"termos":[{"termo":"folhas soltas","significado":"livro formado por folhas avulsas, depois encadernadas."},{"termo":"autenticados","significado":"conferidos e marcados oficialmente como verdadeiros."},{"termo":"encerrados","significado":"fechados com termo que indica o número de folhas utilizadas."}],"exemplo":"Ao iniciar o novo livro de protocolo, o escrivão Rui numerou todas as folhas, lançou o termo de abertura e o de encerramento e autenticou o livro, tudo no mesmo dia, como exigem as Normas."}},{"id":"aut.legislacao_tj.oficios_organizacao.0013","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, o Livro de Visitas e Correições será organizado em folhas soltas, formado gradativamente pelos originais das atas, e não excederá 200 folhas, vedado o encerramento com número diferente.","gabarito":"E","explicacao":"O art. 67, § 2º, limita o Livro de Visitas e Correições a 100 folhas, salvo determinação judicial em contrário ou para manter a continuidade da peça correcional, casos em que pode ser encerrado com mais ou menos folhas. O livro é formado pelos originais das atas assinadas pelo juiz, pelo escrivão e pelos funcionários (caput).","fonte":"NSCGJ, Tomo I, art. 67 (consolidação de 2017)","mastigado":"Errado. O livro de visitas e correições tem limite de cem folhas, e não duzentas. E pode terminar com um pouco mais ou menos, se o juiz determinar ou para não partir uma ata ao meio.","teSitua":{"termos":[{"termo":"Livro de Visitas e Correições","significado":"livro que reúne as atas das fiscalizações feitas na unidade."},{"termo":"atas","significado":"registros escritos do que foi verificado e determinado nas fiscalizações."}],"exemplo":"O livro de visitas e correições do cartório de Avaré chegou a 98 folhas, e a ata da nova correição tinha seis folhas. Para não dividir a ata, o livro foi encerrado com 104 folhas, mediante termo contemporâneo à última ata."}},{"id":"aut.legislacao_tj.oficios_organizacao.0014","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Quanto ao Livro Registro de Sentenças, as Normas de Serviço da Corregedoria Geral da Justiça estabelecem que","alternativas":{"A":"o registro far-se-á em até 5 dias após a baixa dos autos em cartório pelo juiz, ficando dispensadas do registro as sentenças cadastradas no sistema com assinatura digital.","B":"o registro far-se-á em até 30 dias após o trânsito em julgado.","C":"o registro é facultativo em todos os casos.","D":"apenas as sentenças criminais são registradas.","E":"o registro é feito pelo juiz, de próprio punho."},"gabarito":"A","explicacao":"O art. 72, § 1º, fixa o prazo de 5 dias após a baixa dos autos pelo juiz. O § 6º dispensa do registro, do livro e da certidão as sentenças cadastradas no sistema com assinatura digital. O registro é autenticado pelo escrivão (caput) e certificado nos autos (§ 5º).","explicacoes":{"A":"Correta: art. 72, §§ 1º e 6º.","B":"O prazo é de 5 dias após a baixa dos autos.","C":"O registro é a regra, salvo assinatura digital.","D":"Todas as sentenças são registradas, salvo a dispensa do § 6º.","E":"O registro é feito pelo cartório e autenticado pelo escrivão."},"fonte":"NSCGJ, Tomo I, art. 72, §§ 1º, 5º e 6º (consolidação de 2017)","mastigado":"A resposta é a letra A. Quando o juiz devolve o processo com a sentença, o cartório tem cinco dias para registrá-la. Se a sentença já foi lançada no sistema com assinatura digital, esse registro em livro é dispensado.","teSitua":{"termos":[{"termo":"Registro de Sentenças","significado":"livro ou registro oficial que guarda o texto das sentenças proferidas."},{"termo":"baixa dos autos","significado":"devolução do processo pelo juiz ao cartório, após decidir."},{"termo":"assinatura digital","significado":"assinatura eletrônica feita com certificado digital, que garante autoria e integridade."}],"exemplo":"Num processo físico antigo, o juiz devolveu os autos com a sentença na segunda-feira, e a escrevente fez o registro na quarta. Já nos processos digitais da vara, as sentenças assinadas digitalmente não precisam desse registro."}},{"id":"aut.legislacao_tj.oficios_organizacao.0015","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os livros de cargas de autos e de mandados, após revisados e decorridos 2 anos do último registro, se reputados sem utilidade pelo escrivão judicial,","alternativas":{"A":"poderão ser inutilizados, mediante prévia autorização do Juiz Corregedor Permanente, arquivando-se a autorização em classificador próprio.","B":"deverão ser encaminhados ao Arquivo Geral do Tribunal para guarda permanente.","C":"poderão ser inutilizados pelo próprio escrivão, sem autorização.","D":"deverão ser conservados por 20 anos.","E":"serão remetidos à Corregedoria Geral para destruição."},"gabarito":"A","explicacao":"O art. 74, § 2º, permite inutilizar esses livros após revisão e decurso de 2 anos do último registro, se o escrivão os considerar sem utilidade, mediante prévia autorização do Juiz Corregedor Permanente, que é arquivada em classificador próprio com certidão da data e da forma de inutilização. O desaparecimento de livro é comunicado imediatamente ao juiz (§ 1º).","explicacoes":{"A":"Correta: art. 74, § 2º.","B":"A regra permite a inutilização.","C":"É necessária a prévia autorização do juiz.","D":"O prazo é de 2 anos do último registro.","E":"A autorização é do Juiz Corregedor Permanente."},"fonte":"NSCGJ, Tomo I, art. 74 (consolidação de 2017)","mastigado":"A resposta é a letra A. Livros de carga velhos, com mais de dois anos desde o último registro e sem utilidade, podem ser destruídos. Mas só com autorização do juiz corregedor, que fica arquivada no cartório.","teSitua":{"termos":[{"termo":"inutilizados","significado":"destruídos de forma controlada, por não terem mais utilidade."},{"termo":"classificador próprio","significado":"pasta específica para guardar determinado tipo de documento."},{"termo":"Juiz Corregedor Permanente","significado":"juiz encarregado de fiscalizar continuamente o cartório."}],"exemplo":"O último registro do livro de cargas de mandados do cartório de Lins foi feito em 2021. Em 2024, o escrivão o revisou, considerou-o sem utilidade e pediu autorização ao juiz para inutilizá-lo, arquivando depois a autorização e a certidão."}},{"id":"aut.legislacao_tj.oficios_organizacao.0016","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Pelas Normas de Serviço da Corregedoria Geral da Justiça, os ofícios e mensagens eletrônicas expedidos e recebidos pelo ofício de justiça serão conservados pelo prazo de 1 ano, e as guias de recolhimento de diligências do oficial de justiça, pelo prazo mínimo de 2 anos contados do arquivamento.","gabarito":"C","explicacao":"O art. 78 fixa 1 ano para ofícios e mensagens expedidos e recebidos, após o que podem ser inutilizados com autorização do juiz corregedor (parágrafo único). O art. 79 fixa o mínimo de 2 anos do arquivamento para as guias de recolhimento de diligências do oficial de justiça.","fonte":"NSCGJ, Tomo I, arts. 78 e 79 (consolidação de 2017)","mastigado":"Certo. As cópias de ofícios e e-mails do cartório ficam guardadas por um ano. As guias de pagamento das diligências do oficial de justiça ficam pelo menos dois anos. Depois, podem ser inutilizadas com autorização do juiz.","teSitua":{"termos":[{"termo":"ofícios","significado":"comunicações escritas oficiais enviadas ou recebidas pelo cartório."},{"termo":"guias de recolhimento de diligências","significado":"comprovantes de pagamento das despesas de deslocamento do oficial de justiça."}],"exemplo":"Em 2026, o escrivão Paulo separou os ofícios recebidos em 2024 e as guias de diligência arquivadas em 2023. Como já haviam passado os prazos de um e de dois anos, pediu autorização ao juiz para inutilizá-los."}},{"id":"aut.legislacao_tj.oficios_organizacao.0017","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Na lavratura de atos, termos, certidões e demais documentos do ofício de justiça, as Normas de Serviço da Corregedoria Geral da Justiça exigem, entre outros requisitos, que","alternativas":{"A":"a escrituração seja feita em vernáculo, com tinta preta ou azul, indelével, e os numerais sejam expressos em algarismos e por extenso.","B":"os numerais sejam expressos apenas em algarismos.","C":"a escrituração seja feita preferencialmente a lápis, para permitir correções.","D":"os espaços em branco sejam mantidos para futuras anotações.","E":"as assinaturas sejam colhidas ao final do expediente, em conjunto."},"gabarito":"A","explicacao":"O art. 80 exige: papel de fundo branco ou reciclado (I); escrituração em vernáculo, preferencialmente eletrônica, com tinta preta ou azul indelével (II); numerais em algarismos e por extenso (III); inutilização dos espaços em branco (IV); assinaturas colhidas imediatamente após a lavratura, com nome por extenso (V). Anotações a lápis devem ser evitadas (art. 81, III).","explicacoes":{"A":"Correta: art. 80, II e III.","B":"Os numerais devem constar em algarismos e por extenso.","C":"Anotações a lápis devem ser evitadas (art. 81, III).","D":"Os espaços em branco devem ser inutilizados (art. 80, IV).","E":"As assinaturas devem ser colhidas imediatamente após a lavratura (art. 80, V)."},"fonte":"NSCGJ, Tomo I, arts. 80 e 81 (consolidação de 2017)","mastigado":"A resposta é a letra A. Os documentos do cartório são escritos em português, com caneta preta ou azul que não apaga, e os números aparecem em algarismo e por extenso, como em um cheque. Isso dificulta fraudes.","teSitua":{"termos":[{"termo":"escrituração","significado":"ato de escrever e registrar formalmente atos e termos."},{"termo":"vernáculo","significado":"língua portuguesa, idioma oficial do país."},{"termo":"indelével","significado":"que não pode ser apagado."}],"exemplo":"Ao lavrar a certidão, a escrevente Neide escreveu o valor da causa como R$ 5.000,00 (cinco mil reais), usando caneta azul, e inutilizou o espaço em branco que sobrou no fim da página."}},{"id":"aut.legislacao_tj.oficios_organizacao.0018","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, é vedada na escrituração","alternativas":{"A":"a utilização de corretivo ou raspagem, a assinatura de atos ou termos em branco e a utilização de chancela ou recurso que reproduza mecanicamente a assinatura do juiz.","B":"a utilização de qualquer sigla, inclusive as adotadas por órgãos oficiais.","C":"a escrituração por meio eletrônico.","D":"a ressalva de erros antes da subscrição do ato.","E":"a utilização de papel reciclado."},"gabarito":"A","explicacao":"O art. 82 veda: borracha, raspagem ou corretivo (I); assinatura em branco (II); abreviaturas e siglas, exceto as consagradas pelo Vocabulário Ortográfico, as de órgãos oficiais e as convencionadas por área do conhecimento (III); chancela ou reprodução mecânica da assinatura do juiz (IV). Erros devem ser ressalvados antes da subscrição (art. 81, § 1º). A escrituração eletrônica é preferencial e o papel reciclado é admitido (art. 80).","explicacoes":{"A":"Correta: art. 82, I, II e IV.","B":"Siglas de órgãos oficiais são admitidas (art. 82, III).","C":"A escrituração eletrônica é preferencial (art. 80, II).","D":"A ressalva é exigida (art. 81, § 1º).","E":"O papel reciclado é admitido (art. 80, I)."},"fonte":"NSCGJ, Tomo I, arts. 80, 81 e 82 (consolidação de 2017)","mastigado":"A resposta é a letra A. No cartório não se usa corretivo nem se raspa o papel, não se assina documento em branco e não se usa carimbo com a assinatura do juiz. Erros são corrigidos com ressalva escrita antes de assinar.","teSitua":{"termos":[{"termo":"raspagem","significado":"remoção do que estava escrito, raspando o papel."},{"termo":"chancela","significado":"carimbo ou recurso que reproduz uma assinatura."},{"termo":"em branco","significado":"sem o conteúdo preenchido, para ser completado depois."}],"exemplo":"Com pressa, o juiz quis deixar mandados assinados em branco com o escrivão. O escrivão Hélio recusou, lembrando que as Normas proíbem assinatura em branco e o uso de chancela com a assinatura do juiz."}},{"id":"aut.legislacao_tj.oficios_organizacao.0019","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os mandados, cartas postais e ofícios gerais de comunicação expedidos em cumprimento de ato judicial serão assinados pelos escrivães, por ordem do juiz. A subscrição do próprio juiz é, porém, obrigatória quando","alternativas":{"A":"se tratar de alvará de soltura ou mandado de prisão, houver determinação de desconto de pensão alimentícia ou o documento for dirigido a autoridades, como Delegados de Polícia.","B":"se tratar de qualquer carta de citação pelo correio.","C":"o ofício for dirigido a uma empresa privada para simples informação.","D":"o mandado for de intimação de testemunha.","E":"a carta for expedida por meio eletrônico."},"gabarito":"A","explicacao":"O art. 85, § 1º, exige assinatura do juiz quando a lei ou as Normas assim determinarem (busca e apreensão cautelar, prisão, contramandado, alvará de soltura, alvarás em geral, levantamento de depósito, ordem de arrombamento) (I), quando houver desconto de pensão alimentícia (II) e quando os documentos forem dirigidos a autoridades (III). Cartas postais, inclusive eletrônicas, podem dispensar até a assinatura do escrivão, nas condições do § 2º.","explicacoes":{"A":"Correta: art. 85, § 1º.","B":"Cartas postais são assinadas pelo escrivão ou até dispensam assinatura (§ 2º).","C":"Ofícios gerais de comunicação são assinados pelo escrivão.","D":"Mandados comuns são assinados pelo escrivão por ordem do juiz.","E":"A expedição eletrônica de cartas pode dispensar assinatura (§ 2º)."},"fonte":"NSCGJ, Tomo I, art. 85 (consolidação de 2017)","mastigado":"A resposta é a letra A. Na maioria dos mandados e ofícios, o escrivão assina dizendo que o faz por ordem do juiz. Mas atos graves, como prender ou soltar alguém, descontar pensão do salário ou escrever a uma autoridade, exigem a assinatura do próprio juiz.","teSitua":{"termos":[{"termo":"alvará de soltura","significado":"ordem judicial para libertar uma pessoa presa."},{"termo":"desconto de pensão alimentícia","significado":"ordem para o empregador descontar a pensão diretamente do salário."},{"termo":"subscrição","significado":"assinatura de quem é responsável pelo documento."}],"exemplo":"No mesmo dia, a escrevente preparou um mandado de intimação, assinado pelo escrivão por ordem do juiz, e um ofício à empresa determinando o desconto da pensão de um pai devedor, que precisou ser assinado pela juíza."}},{"id":"aut.legislacao_tj.oficios_organizacao.0020","subtopico":"legislacao_tj.nscgj.oficios_organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos ofícios de justiça contemplados com sistema informatizado que permita a assinatura por certificação digital, as Normas de Serviço da Corregedoria Geral da Justiça dispensam a certificação, pelo escrivão, da autenticidade da assinatura do juiz.","gabarito":"C","explicacao":"É o que dispõe o art. 84, § 2º. Fora dessa hipótese, o escrivão certifica a autenticidade da firma do juiz na expedição de alvarás de soltura, mandados e contramandados de prisão, requisições de preso e outros atos em que a lei o exige, ou quando houver dúvida (§ 1º).","fonte":"NSCGJ, Tomo I, art. 84, §§ 1º e 2º (consolidação de 2017)","mastigado":"Certo. Antes, o escrivão precisava confirmar por escrito que a assinatura do juiz era verdadeira em alguns documentos, como alvará de soltura. Com a assinatura digital, isso não é mais necessário, porque o próprio certificado garante a autoria.","teSitua":{"termos":[{"termo":"certificação digital","significado":"tecnologia que identifica com segurança quem assinou um documento eletrônico."},{"termo":"autenticidade","significado":"qualidade de ser verdadeiro, de ter sido realmente feito por quem diz."}],"exemplo":"O alvará de soltura de um réu foi assinado digitalmente pelo juiz no sistema. O escrivão Marcos não precisou lançar certidão confirmando a assinatura, porque o certificado digital já garante a autenticidade."}},{"id":"aut.legislacao_tj.organizacao.0001","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Regimento Interno do Tribunal de Justiça de São Paulo, o Tribunal Pleno é composto por todos os desembargadores, competindo-lhe, entre outras atribuições,","alternativas":{"A":"eleger o Presidente, o Vice-Presidente e o Corregedor Geral da Justiça, bem como eleger doze desembargadores que integrarão o Órgão Especial.","B":"julgar os incidentes de inconstitucionalidade.","C":"julgar os recursos de candidatos aos concursos de servidores.","D":"processar e julgar as ações rescisórias de acórdãos das Câmaras.","E":"aprovar o quadro geral de antiguidade dos juízes."},"gabarito":"A","explicacao":"O art. 4º atribui ao Pleno: eleger Presidente, Vice-Presidente e Corregedor Geral (I); eleger doze desembargadores do Órgão Especial e seus suplentes (II); eleger Diretor, Vice-Diretor e conselhos da Escola Paulista da Magistratura (III); e eleger os desembargadores substitutos do TRE (IV). Incidentes de inconstitucionalidade são do Órgão Especial (art. 13, I, d); recursos de candidatos a concursos de servidores e quadro de antiguidade dos juízes, do Conselho Superior da Magistratura (art. 16, IX e XIII).","explicacoes":{"A":"Correta: art. 4º, I e II.","B":"Compete ao Órgão Especial (art. 13, I, d).","C":"Compete ao Conselho Superior da Magistratura (art. 16, XIII).","D":"Rescisórias de acórdãos de Câmaras são julgadas pelos Grupos (art. 37, § 1º).","E":"Compete ao Conselho Superior da Magistratura (art. 16, IX)."},"fonte":"Regimento Interno do TJSP, art. 4º","mastigado":"A resposta é a letra A. O Pleno, que reúne todos os desembargadores, é sobretudo um colégio eleitoral: escolhe a cúpula do Tribunal e parte do Órgão Especial. Os julgamentos e a administração do dia a dia ficam com outros órgãos.","teSitua":{"termos":[{"termo":"Tribunal Pleno","significado":"reunião de todos os desembargadores do Tribunal."},{"termo":"Corregedor Geral da Justiça","significado":"desembargador que dirige a fiscalização dos serviços judiciais de primeira instância."},{"termo":"Órgão Especial","significado":"órgão de 25 desembargadores que exerce as atribuições do Pleno em julgamentos e administração."}],"exemplo":"Em novembro, os mais de trezentos desembargadores do TJSP se reúnem em Pleno para votar no novo Presidente, no Vice-Presidente e no Corregedor Geral. Na mesma composição, elegem os doze membros eleitos do Órgão Especial."}},{"id":"aut.legislacao_tj.organizacao.0002","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, o Órgão Especial é constituído por","alternativas":{"A":"vinte e cinco desembargadores, sendo membros natos o Presidente, o Vice-Presidente e o Corregedor Geral da Justiça, além dos desembargadores das classes de antiguidade e de eleitos.","B":"vinte e cinco desembargadores, todos eleitos pelo Pleno.","C":"treze desembargadores, os mais antigos do Tribunal.","D":"todos os desembargadores, sob a presidência do Presidente do Tribunal.","E":"doze desembargadores eleitos e doze escolhidos pelo Presidente."},"gabarito":"A","explicacao":"O art. 8º fixa o Órgão Especial em vinte e cinco desembargadores: o Presidente, o Vice-Presidente e o Corregedor Geral como membros natos, segundo as classes a que pertençam, e desembargadores das classes de antiguidade e de eleitos. O Pleno elege doze (art. 4º, II). O quórum mínimo de instalação é de treze (art. 11).","explicacoes":{"A":"Correta: art. 8º.","B":"Apenas doze são eleitos pelo Pleno (art. 4º, II); os demais vêm da antiguidade.","C":"Treze é o quórum mínimo de instalação (art. 11), não a composição.","D":"Essa é a composição do Pleno (art. 4º).","E":"Não há escolha de membros pelo Presidente."},"fonte":"Regimento Interno do TJSP, arts. 4º, II, 8º e 11","mastigado":"A resposta é a letra A. O Órgão Especial tem vinte e cinco desembargadores: metade vem pela antiguidade, metade por eleição, e o Presidente, o Vice e o Corregedor fazem parte dele automaticamente.","teSitua":{"termos":[{"termo":"Órgão Especial","significado":"órgão reduzido de desembargadores que exerce funções do Pleno."},{"termo":"membros natos","significado":"integrantes que fazem parte do órgão automaticamente, pelo cargo que ocupam."},{"termo":"classes de antiguidade e de eleitos","significado":"grupos de vagas preenchidas pelos mais antigos e por desembargadores escolhidos em eleição."}],"exemplo":"A desembargadora Helena entrou no Órgão Especial por ser uma das mais antigas do Tribunal. Seu colega Ricardo chegou lá por eleição do Pleno. O Presidente do Tribunal, por sua vez, integra o órgão como membro nato."}},{"id":"aut.legislacao_tj.organizacao.0003","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Regimento Interno do TJSP, o Órgão Especial instalar-se-á com a presença de, no mínimo, treze desembargadores.","gabarito":"C","explicacao":"É a regra do art. 11. As demais sessões de órgãos colegiados (Turmas Especiais, Grupos e Câmaras) exigem a maioria absoluta de seus integrantes (art. 43).","fonte":"Regimento Interno do TJSP, art. 11","mastigado":"Certo. Para o Órgão Especial começar a sessão, precisam estar presentes pelo menos treze dos vinte e cinco desembargadores, isto é, mais da metade.","teSitua":{"termos":[{"termo":"Órgão Especial","significado":"órgão de vinte e cinco desembargadores que exerce funções do Pleno."},{"termo":"instalar-se-á","significado":"terá início a sessão, de forma válida."}],"exemplo":"Numa quarta-feira, só onze desembargadores do Órgão Especial compareceram por causa de um congresso. A sessão não pôde ser instalada e foi adiada, porque o mínimo exigido é de treze presentes."}},{"id":"aut.legislacao_tj.organizacao.0004","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Conforme o Regimento Interno do TJSP, compete ao Órgão Especial processar e julgar, originariamente,","alternativas":{"A":"os incidentes de inconstitucionalidade e, em matéria administrativa, instaurar e decidir os processos disciplinares contra magistrado.","B":"os recursos em matéria de Infância e Juventude.","C":"os conflitos de competência entre Câmaras da mesma Seção.","D":"as apelações contra sentenças de primeiro grau.","E":"os incidentes de suspeição de juiz de primeiro grau."},"gabarito":"A","explicacao":"O art. 13, I, d, atribui ao Órgão Especial os incidentes de inconstitucionalidade; o inciso II, g, a instauração e decisão de processos disciplinares contra magistrado. Infância e Juventude e suspeição de juiz de primeiro grau são da Câmara Especial (art. 33, parágrafo único, I e IV); conflitos entre Câmaras da mesma Seção, das Turmas Especiais (art. 32, III); apelações, das Câmaras (art. 35).","explicacoes":{"A":"Correta: art. 13, I, d, e II, g.","B":"Compete à Câmara Especial (art. 33, parágrafo único, IV).","C":"Compete às Turmas Especiais (art. 32, III); o Órgão Especial julga conflitos entre órgãos de Seções diversas (art. 13, I, e).","D":"Compete às Câmaras (art. 35).","E":"Compete à Câmara Especial (art. 33, parágrafo único, I)."},"fonte":"Regimento Interno do TJSP, art. 13, I, d e e, e II, g","mastigado":"A resposta é a letra A. O Órgão Especial decide se uma lei é inconstitucional quando a questão surge num processo do Tribunal e também julga os processos disciplinares contra juízes. Recursos comuns e questões de primeiro grau ficam com outros órgãos.","teSitua":{"termos":[{"termo":"originariamente","significado":"como primeiro órgão a julgar, e não em grau de recurso."},{"termo":"incidentes de inconstitucionalidade","significado":"questões sobre a validade de uma lei diante da Constituição surgidas num processo."},{"termo":"Infância e Juventude","significado":"área da Justiça que trata de crianças e adolescentes."},{"termo":"suspeição","significado":"dúvida sobre a imparcialidade do juiz, por amizade, inimizade ou interesse."}],"exemplo":"Uma Câmara de Direito Público concluiu que uma lei municipal aplicada no caso poderia ser inconstitucional. O julgamento parou e a questão foi enviada ao Órgão Especial, que decidiu o incidente antes de a Câmara terminar o recurso."}},{"id":"aut.legislacao_tj.organizacao.0005","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Regimento Interno do TJSP, o Conselho Superior da Magistratura é composto","alternativas":{"A":"pelo Presidente do Tribunal, que o preside, pelo Vice-Presidente, pelo Corregedor Geral da Justiça, pelo Decano e pelos Presidentes das Seções, prevalecendo, no empate, o voto do presidente do Conselho.","B":"por todos os membros do Órgão Especial.","C":"pelo Presidente, pelo Vice-Presidente e por três desembargadores eleitos.","D":"pelo Corregedor Geral, que o preside, e pelos juízes assessores da Corregedoria.","E":"pelos Presidentes das Seções, sob a presidência do Decano."},"gabarito":"A","explicacao":"O art. 15 compõe o Conselho com Presidente (que o preside), Vice-Presidente, Corregedor Geral, Decano e Presidentes das Seções; no empate, prevalece o voto do presidente do Conselho (§ 2º). O Vice-Presidente secretaria seus trabalhos (art. 27, II, c), e ele só se reúne com ao menos dois ocupantes de cargos de direção e mais dois membros (art. 43, parágrafo único).","explicacoes":{"A":"Correta: art. 15, caput e § 2º.","B":"O Órgão Especial tem composição própria (art. 8º).","C":"Não há membros eleitos no Conselho.","D":"Quem preside é o Presidente do Tribunal.","E":"Quem preside é o Presidente do Tribunal, e há outros membros."},"fonte":"Regimento Interno do TJSP, art. 15; art. 43, parágrafo único","mastigado":"A resposta é a letra A. O Conselho Superior da Magistratura reúne a cúpula do Tribunal: Presidente, Vice, Corregedor, o desembargador mais antigo e os Presidentes das três Seções. Se der empate, vale o voto do Presidente.","teSitua":{"termos":[{"termo":"Conselho Superior da Magistratura","significado":"órgão de cúpula do TJSP com funções administrativas sobre a magistratura e os serviços judiciais."},{"termo":"Decano","significado":"desembargador mais antigo do Tribunal."},{"termo":"Presidentes das Seções","significado":"desembargadores eleitos para dirigir as Seções de Direito Criminal, Privado e Público."}],"exemplo":"Numa votação do Conselho Superior da Magistratura sobre a suspensão do expediente num feriado municipal, houve empate. Prevaleceu o voto do Presidente do Tribunal, que preside o Conselho."}},{"id":"aut.legislacao_tj.organizacao.0006","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, compete ao Conselho Superior da Magistratura julgar os recursos de candidatos aos concursos para provimento de cargos no quadro de servidores da Justiça e aprovar a suspensão do expediente forense nos feriados municipais das comarcas do interior.","gabarito":"C","explicacao":"Essas atribuições estão no art. 16, XIII e XV. O Conselho também oferece ao Órgão Especial as listas de promoção dos juízes (I), aprecia suspeições por foro íntimo de juiz de primeiro grau (III) e aprova o quadro geral de antiguidade dos juízes (IX).","fonte":"Regimento Interno do TJSP, art. 16, XIII e XV","mastigado":"Certo. Quem julga o recurso de candidato em concurso para servidor do Tribunal, como o de escrevente, é o Conselho Superior da Magistratura. Ele também autoriza fechar o fórum em feriado municipal no interior.","teSitua":{"termos":[{"termo":"provimento de cargos","significado":"preenchimento de cargos públicos vagos."},{"termo":"expediente forense","significado":"horário de funcionamento dos fóruns e serviços judiciais."},{"termo":"feriados municipais","significado":"feriados próprios de cada cidade, como o aniversário do município."}],"exemplo":"Lívia foi eliminada do concurso de escrevente por um erro na inscrição e recorreu. O recurso foi julgado pelo Conselho Superior da Magistratura. No mesmo mês, o Conselho aprovou a suspensão do expediente do fórum de Franca no aniversário da cidade."}},{"id":"aut.legislacao_tj.organizacao.0007","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Regimento Interno do TJSP, para a eleição do Presidente, do Vice-Presidente e do Corregedor Geral da Justiça, o Tribunal Pleno reunir-se-á na segunda quarta-feira de dezembro do ano em que findarem os mandatos.","gabarito":"E","explicacao":"O art. 17, com redação do Assento Regimental 578/2020, fixa a reunião na segunda quarta-feira de novembro do ano em que findarem os mandatos. No mesmo dia, as Seções elegem seus Presidentes (art. 20), e a votação é secreta, preferencialmente eletrônica (art. 22).","fonte":"Regimento Interno do TJSP, arts. 17, 20 e 22","mastigado":"Errado. A eleição da cúpula do Tribunal acontece na segunda quarta-feira de novembro, e não de dezembro. No mesmo dia, cada Seção elege seu Presidente, em votação secreta.","teSitua":{"termos":[{"termo":"Tribunal Pleno","significado":"reunião de todos os desembargadores."},{"termo":"mandatos","significado":"períodos de exercício dos cargos de direção."}],"exemplo":"Em 2025, os mandatos da cúpula terminavam. Os desembargadores foram convocados e votaram na segunda quarta-feira de novembro, de forma secreta e eletrônica, escolhendo Presidente, Vice e Corregedor, enquanto as Seções escolhiam seus Presidentes."}},{"id":"aut.legislacao_tj.organizacao.0008","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Na eleição para os cargos de direção do TJSP, nenhum candidato alcançou a maioria absoluta dos votos dos integrantes efetivos do Tribunal no primeiro escrutínio. Segundo o Regimento Interno,","alternativas":{"A":"haverá segundo escrutínio entre os dois candidatos mais votados, elegendo-se o que obtiver a maioria dos votantes, computados os votos brancos e nulos; havendo empate, vence o mais antigo.","B":"será considerado eleito o candidato mais votado, independentemente de maioria.","C":"será eleito o candidato mais idoso.","D":"a escolha caberá ao Órgão Especial.","E":"haverá novo escrutínio com todos os candidatos, no prazo de trinta dias."},"gabarito":"A","explicacao":"O art. 19 prevê segundo escrutínio entre os dois mais votados, elegendo-se quem obtiver a maioria dos votantes, computados brancos e nulos. Se nenhum for eleito, faz-se outra eleição em no máximo cinco dias, sem eles (§ 1º); havendo empate, vence o mais antigo (§ 3º).","explicacoes":{"A":"Correta: art. 19, caput e § 3º.","B":"Exige-se maioria; não basta ser o mais votado no primeiro escrutínio.","C":"O desempate é pela antiguidade.","D":"A eleição é do Pleno.","E":"O segundo escrutínio é entre os dois mais votados; nova eleição, se necessária, ocorre em até cinco dias."},"fonte":"Regimento Interno do TJSP, art. 19, caput, §§ 1º e 3º","mastigado":"A resposta é a letra A. Se ninguém tiver mais da metade dos votos do Tribunal no primeiro turno, há segundo turno entre os dois primeiros colocados. Se empatarem, ganha o desembargador mais antigo.","teSitua":{"termos":[{"termo":"escrutínio","significado":"rodada de votação com apuração dos votos."},{"termo":"maioria absoluta","significado":"mais da metade do total de integrantes."},{"termo":"votos brancos e nulos","significado":"votos sem escolha de candidato ou invalidados."}],"exemplo":"Na disputa pela Presidência, os desembargadores Álvaro e Beatriz foram os mais votados, mas nenhum teve maioria absoluta. No segundo escrutínio, só os dois concorreram. Se empatassem, venceria quem tem mais tempo no cargo de desembargador."}},{"id":"aut.legislacao_tj.organizacao.0009","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme o Regimento Interno do TJSP, vagando, no curso do mandato, cargo de direção ou de cúpula, será convocada eleição para o período restante, mas não haverá eleição se restar menos de seis meses de mandato, ocorrendo, então, substituição conforme a ordem regimental.","gabarito":"C","explicacao":"É o que dispõe o art. 21 e seu parágrafo único. A eleição segue a forma do § 1º do art. 10 (convocação em quinze dias, edital com vinte dias de antecedência).","fonte":"Regimento Interno do TJSP, art. 21 e parágrafo único","mastigado":"Certo. Se o Presidente, o Vice ou outro dirigente deixar o cargo no meio do mandato, faz-se eleição para completar o tempo. Mas, se faltar menos de seis meses, não vale a pena votar: assume o substituto previsto no Regimento.","teSitua":{"termos":[{"termo":"cargo de direção ou de cúpula","significado":"cargos de Presidente, Vice-Presidente, Corregedor Geral e Presidentes das Seções."},{"termo":"ordem regimental","significado":"sequência de substituição prevista no próprio Regimento."}],"exemplo":"O Vice-Presidente do Tribunal se aposentou faltando quatro meses para o fim do mandato. Não houve eleição: o Decano assumiu a Vice-Presidência até o término do período, conforme a ordem do Regimento."}},{"id":"aut.legislacao_tj.organizacao.0010","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos afastamentos, ausências e impedimentos, segundo o Regimento Interno do TJSP, o Presidente do Tribunal é substituído","alternativas":{"A":"pelo Vice-Presidente e, na falta, pelo Decano.","B":"pelo Corregedor Geral da Justiça e, na falta, pelo Vice-Presidente.","C":"pelo Presidente da Seção de Direito Público.","D":"pelo desembargador mais votado do Órgão Especial.","E":"pelo Decano e, na falta, pelo Vice-Presidente."},"gabarito":"A","explicacao":"O art. 24 prevê que o Presidente seja substituído pelo Vice-Presidente e, na falta, pelo Decano; o Vice e o Corregedor são substituídos pelo Decano, e este pelo seguinte na antiguidade (§ 1º); o Presidente de Seção, pelo mais antigo da Seção (§ 3º).","explicacoes":{"A":"Correta: art. 24, caput.","B":"O Corregedor não é o substituto do Presidente.","C":"Não é a regra regimental.","D":"O eleito do Órgão Especial só é convocado se houver mais de uma substituição simultânea (§ 2º).","E":"A ordem é Vice-Presidente e, depois, Decano."},"fonte":"Regimento Interno do TJSP, art. 24, caput e §§ 1º a 3º","mastigado":"A resposta é a letra A. Quando o Presidente se ausenta, assume o Vice-Presidente. Se o Vice também não puder, assume o Decano, que é o desembargador mais antigo do Tribunal.","teSitua":{"termos":[{"termo":"impedimentos","significado":"situações que impedem a pessoa de exercer o cargo naquele momento."},{"termo":"Decano","significado":"desembargador mais antigo do Tribunal."}],"exemplo":"O Presidente do TJSP viajou para um encontro em Brasília. Durante a viagem, o Vice-Presidente assinou os atos da Presidência. Como o Vice também estava de licença médica, quem assumiu foi o Decano."}},{"id":"aut.legislacao_tj.organizacao.0011","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com o Regimento Interno do TJSP, compete ao Presidente do Tribunal, em matéria administrativa,","alternativas":{"A":"administrar os prédios do Poder Judiciário, designando os juízes diretores dos foros da Capital e do interior, e exercer os atos de provimento, designação, exoneração, férias e licença de servidores não atribuídos a outros órgãos.","B":"superintender, em primeira instância, a distribuição dos feitos.","C":"realizar correições ordinárias nas unidades judiciais do interior.","D":"estabelecer as normas de serviço das serventias judiciais.","E":"secretariar os trabalhos do Conselho Superior da Magistratura."},"gabarito":"A","explicacao":"O art. 26, II, d e u, atribui ao Presidente a administração dos prédios, com designação dos juízes diretores dos foros, e os atos de provimento, designação, alteração de posto, exoneração, férias, afastamento e licença de servidores não atribuídos a outros órgãos. Superintender a distribuição em primeira instância, fazer correições e baixar normas de serviço das serventias cabem ao Corregedor (art. 28, I, VIII e XVI); secretariar o Conselho, ao Vice-Presidente (art. 27, II, c).","explicacoes":{"A":"Correta: art. 26, II, d e u.","B":"Compete ao Corregedor Geral (art. 28, I).","C":"Compete ao Corregedor Geral (art. 28, VIII).","D":"Compete ao Corregedor Geral (art. 28, XVI).","E":"Compete ao Vice-Presidente (art. 27, II, c)."},"fonte":"Regimento Interno do TJSP, art. 26, II, d e u","mastigado":"A resposta é a letra A. O Presidente é o administrador geral: cuida dos prédios, nomeia os juízes diretores dos fóruns e pratica os atos de vida funcional dos servidores. A fiscalização dos cartórios de primeira instância é tarefa do Corregedor.","teSitua":{"termos":[{"termo":"juízes diretores dos foros","significado":"juízes encarregados da administração do prédio e dos serviços gerais de cada fórum."},{"termo":"provimento","significado":"preenchimento de cargo vago com a nomeação de alguém."},{"termo":"serventias judiciais","significado":"cartórios judiciais, onde tramitam os processos."}],"exemplo":"A juíza Cláudia foi designada diretora do fórum de Presidente Prudente por ato do Presidente do Tribunal. No mesmo mês, também por ato da Presidência, foram nomeados os novos escreventes aprovados no concurso."}},{"id":"aut.legislacao_tj.organizacao.0012","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, compete ao Vice-Presidente do Tribunal, em matéria administrativa,","alternativas":{"A":"presidir a distribuição de processos do Órgão Especial e secretariar os trabalhos do Conselho Superior da Magistratura.","B":"fiscalizar a atividade das delegações notariais e de registro.","C":"presidir as sessões do Órgão Especial.","D":"designar os corregedores permanentes dos presídios.","E":"elaborar o regimento da secretaria do Tribunal."},"gabarito":"A","explicacao":"O art. 27, II, atribui ao Vice-Presidente presidir a distribuição do Órgão Especial e resolver previamente incidentes urgentes (a), substituir o Presidente (b), secretariar o Conselho Superior da Magistratura (c) e integrar e presidir comissão permanente (d). A fiscalização das delegações e a designação de corregedores permanentes são do Corregedor (art. 28); presidir o Órgão Especial e elaborar o regimento da secretaria, do Presidente (art. 26, II, m e w).","explicacoes":{"A":"Correta: art. 27, II, a e c.","B":"Compete ao Corregedor Geral (art. 28, XIX).","C":"Compete ao Presidente (art. 26, II, m).","D":"Compete ao Corregedor Geral, com aprovação do Conselho (art. 28, XI).","E":"Compete ao Presidente (art. 26, II, w)."},"fonte":"Regimento Interno do TJSP, art. 27, II","mastigado":"A resposta é a letra A. O Vice-Presidente cuida da distribuição dos processos do Órgão Especial e funciona como secretário do Conselho Superior da Magistratura, além de substituir o Presidente quando preciso.","teSitua":{"termos":[{"termo":"distribuição","significado":"repartição dos processos entre os julgadores."},{"termo":"Órgão Especial","significado":"órgão de vinte e cinco desembargadores com funções do Pleno."},{"termo":"delegações notariais e de registro","significado":"cartórios extrajudiciais, como tabelionatos e registros de imóveis."}],"exemplo":"Chegou ao Tribunal um mandado de segurança contra ato do Governador, de competência do Órgão Especial. Quem presidiu a distribuição desse processo foi o Vice-Presidente, que também secretaria as reuniões do Conselho Superior da Magistratura."}},{"id":"aut.legislacao_tj.organizacao.0013","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Regimento Interno do TJSP, compete ao Corregedor Geral da Justiça","alternativas":{"A":"superintender, em primeira instância, a distribuição dos feitos de qualquer natureza, fiscalizar em caráter geral e permanente os serviços judiciários de primeira instância e estabelecer as normas de serviço das serventias judiciais.","B":"eleger os membros do Órgão Especial.","C":"julgar os recursos em matéria de Infância e Juventude.","D":"decidir a admissibilidade dos recursos extraordinários em processos do Órgão Especial.","E":"apreciar o pedido de suspensão de liminar concedida contra o Poder Público."},"gabarito":"A","explicacao":"O art. 28 atribui ao Corregedor, entre outras funções: superintender a distribuição em primeira instância (I); fiscalizar, em caráter geral e permanente, os órgãos e serviços judiciários de primeira instância e estabelecimentos prisionais (VI); estabelecer as normas de serviço das serventias judiciais (XVI). A eleição do Órgão Especial é do Pleno; Infância e Juventude, da Câmara Especial; admissibilidade de recursos e suspensão de liminar, do Presidente (art. 26, I, b e c).","explicacoes":{"A":"Correta: art. 28, I, VI e XVI.","B":"Compete ao Pleno (art. 4º, II).","C":"Compete à Câmara Especial (art. 33, parágrafo único, IV).","D":"Compete ao Presidente (art. 26, I, c).","E":"Compete ao Presidente (art. 26, I, b)."},"fonte":"Regimento Interno do TJSP, art. 28, I, VI e XVI","mastigado":"A resposta é a letra A. O Corregedor é o grande fiscal da primeira instância: comanda a distribuição dos processos nos fóruns, fiscaliza cartórios e presídios e edita as normas de serviço que os cartórios seguem, como as Normas da Corregedoria.","teSitua":{"termos":[{"termo":"superintender","significado":"dirigir e supervisionar de forma geral."},{"termo":"serventias judiciais","significado":"cartórios judiciais, onde tramitam os processos."},{"termo":"estabelecimentos prisionais","significado":"presídios e cadeias onde ficam pessoas presas."}],"exemplo":"Uma nova regra sobre a forma de expedir mandados nos cartórios de primeira instância foi editada nas Normas de Serviço pelo Corregedor Geral da Justiça. Todos os escreventes do Estado passaram a segui-la."}},{"id":"aut.legislacao_tj.organizacao.0014","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, compete ao Corregedor Geral da Justiça propor à autoridade competente, quando for o caso, a pena de demissão de servidor e aplicar, originariamente, sem prejuízo da competência dos corregedores permanentes, as demais penas.","gabarito":"C","explicacao":"É o inciso XIV do art. 28, com redação do Assento Regimental 582/2020, que permite ainda reexaminar, enquanto não prescrita a infração, decisões da corregedoria permanente. O Corregedor também julga os recursos contra decisões dos juízes corregedores permanentes em matéria disciplinar do pessoal das serventias judiciais (XIII).","fonte":"Regimento Interno do TJSP, art. 28, XIII e XIV","mastigado":"Certo. Em matéria disciplinar de servidores dos cartórios, o Corregedor Geral pode aplicar diretamente as penas mais leves e, quando for caso de demissão, propõe a pena à autoridade que tem o poder de aplicá-la.","teSitua":{"termos":[{"termo":"originariamente","significado":"como primeira autoridade a decidir, e não em recurso."},{"termo":"corregedores permanentes","significado":"juízes encarregados de fiscalizar, de forma contínua, os cartórios e serviços da comarca."}],"exemplo":"Apurou-se que a escrevente Tânia cometeu falta grave que justificaria demissão. O Corregedor Geral propôs a demissão à autoridade competente. Já a falta leve do colega Rui foi punida diretamente com repreensão pelo juiz corregedor permanente."}},{"id":"aut.legislacao_tj.organizacao.0015","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Regimento Interno do TJSP, o Tribunal é composto por","alternativas":{"A":"uma Seção de Direito Criminal, uma de Direito Privado e uma de Direito Público, havendo também uma Câmara Especial e uma Câmara Especial de Presidentes, desvinculadas das Seções.","B":"duas Seções, uma Cível e uma Criminal.","C":"quatro Seções: Criminal, Privado, Público e Infância e Juventude.","D":"uma Seção única, dividida em Grupos de Câmaras.","E":"três Seções, às quais estão vinculadas a Câmara Especial e a Câmara Especial de Presidentes."},"gabarito":"A","explicacao":"O art. 30 prevê três Seções (Criminal, Privado e Público), constituídas por Turmas Especiais, Grupos, Câmaras e desembargadores, além de uma Câmara Especial e uma Câmara Especial de Presidentes, desvinculadas das Seções. O Órgão Especial fixa, por resolução, a competência de cada Seção (parágrafo único).","explicacoes":{"A":"Correta: art. 30.","B":"São três Seções.","C":"Não há Seção de Infância e Juventude; essa matéria é da Câmara Especial.","D":"São três Seções.","E":"A Câmara Especial e a Câmara Especial de Presidentes são desvinculadas das Seções."},"fonte":"Regimento Interno do TJSP, art. 30","mastigado":"A resposta é a letra A. O TJSP se divide em três grandes áreas: Direito Criminal, Direito Privado e Direito Público. Fora delas, existem a Câmara Especial e a Câmara Especial de Presidentes, que não pertencem a nenhuma Seção.","teSitua":{"termos":[{"termo":"Seção","significado":"grande divisão do Tribunal por área do Direito, que reúne câmaras e grupos."},{"termo":"Câmara Especial","significado":"órgão do Tribunal com competências próprias, como infância e juventude."},{"termo":"desvinculadas","significado":"que não pertencem nem estão subordinadas a outro órgão."}],"exemplo":"Uma apelação sobre contrato de aluguel vai para a Seção de Direito Privado; um recurso contra multa de trânsito, para a de Direito Público; e uma apelação criminal, para a de Direito Criminal. Já um recurso sobre adoção vai para a Câmara Especial."}},{"id":"aut.legislacao_tj.organizacao.0016","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":3,"enunciado":"Conforme o Regimento Interno do TJSP, a Câmara Especial é presidida pelo Vice-Presidente do Tribunal e integrada pelos Presidentes das Seções e pelo Decano, competindo-lhe processar e julgar, entre outros,","alternativas":{"A":"os processos originários e os recursos em matéria de Infância e Juventude e os incidentes de suspeição e impedimento de juiz de primeiro grau.","B":"os incidentes de inconstitucionalidade de lei.","C":"as apelações cíveis de competência da Seção de Direito Privado.","D":"os agravos internos contra decisões que negam seguimento a recurso especial.","E":"as eleições para os cargos de direção."},"gabarito":"A","explicacao":"O art. 33 dá à Câmara Especial: incidentes de suspeição e impedimento de juiz de primeiro grau (I); conflitos de competência entre juízes e de atribuição, ressalvado o Órgão Especial (II); agravos em exceções de incompetência de sua matéria (III); processos e recursos de Infância e Juventude (IV); recursos de decisões originárias do Corregedor em processos disciplinares de servidores, delegados e oficiais de justiça (V). Os agravos contra negativa de seguimento a recurso especial são da Câmara Especial de Presidentes (art. 33-A, § 1º).","explicacoes":{"A":"Correta: art. 33, parágrafo único, I e IV.","B":"Compete ao Órgão Especial (art. 13, I, d).","C":"Compete às Câmaras de Direito Privado (art. 35).","D":"Compete à Câmara Especial de Presidentes (art. 33-A, § 1º, I).","E":"As eleições são do Pleno (arts. 4º e 17)."},"fonte":"Regimento Interno do TJSP, art. 33; art. 33-A, § 1º","mastigado":"A resposta é a letra A. A Câmara Especial julga tudo de Infância e Juventude e também decide quando alguém alega que um juiz de primeiro grau é suspeito ou impedido. Ela também julga recursos contra punições aplicadas pelo Corregedor a servidores.","teSitua":{"termos":[{"termo":"Câmara Especial","significado":"órgão presidido pelo Vice-Presidente, com competências próprias fixadas no Regimento."},{"termo":"Decano","significado":"desembargador mais antigo do Tribunal."},{"termo":"impedimento","significado":"situação objetiva que proíbe o juiz de atuar no processo, como parentesco com a parte."}],"exemplo":"A mãe de um adolescente recorreu da decisão que aplicou medida socioeducativa ao filho. O recurso foi para a Câmara Especial, e não para uma Câmara Criminal, porque se trata de matéria de Infância e Juventude."}},{"id":"aut.legislacao_tj.organizacao.0017","subtopico":"legislacao_tj.regimento.organizacao","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Regimento Interno do TJSP, as Câmaras terão designação ordinal e cada uma será composta por","alternativas":{"A":"cinco desembargadores, sendo os feitos de sua competência julgados, em regra, por turma de três desembargadores.","B":"três desembargadores, que julgam todos os feitos em conjunto.","C":"sete desembargadores, julgando em turma de cinco.","D":"cinco desembargadores, que julgam sempre em composição integral.","E":"nove desembargadores, divididos em três turmas."},"gabarito":"A","explicacao":"O art. 34 fixa cada Câmara em cinco desembargadores, e o art. 41 diz que os feitos das Câmaras são julgados por turma de três, salvo embargos infringentes criminais e julgamento ampliado do art. 942 do CPC, quando atuam os cinco integrantes.","explicacoes":{"A":"Correta: arts. 34 e 41.","B":"A Câmara tem cinco membros; a turma é que tem três.","C":"A Câmara tem cinco membros.","D":"A composição integral é exceção (art. 41).","E":"Não há essa composição."},"fonte":"Regimento Interno do TJSP, arts. 34 e 41","mastigado":"A resposta é a letra A. Cada Câmara tem cinco desembargadores, mas, em regra, cada recurso é julgado por três deles. Os cinco votam juntos só em casos especiais, como quando o julgamento precisa ser ampliado por divergência.","teSitua":{"termos":[{"termo":"designação ordinal","significado":"nome dado por número de ordem, como 1ª, 2ª ou 3ª Câmara."},{"termo":"turma","significado":"grupo de desembargadores que julga um caso concreto."}],"exemplo":"A 5ª Câmara de Direito Privado tem cinco desembargadores. A apelação de Jorge foi julgada pelo relator, pelo revisor e por um terceiro juiz. Como houve divergência, o julgamento foi ampliado, e os outros dois integrantes também votaram."}},{"id":"aut.legislacao_tj.organizacao.0018","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Regimento Interno do TJSP, os Grupos de Câmaras são compostos pela reunião de duas Câmaras, segundo a ordem crescente, ou, sendo ímpar o número, o primeiro ou o último grupo será composto das três primeiras ou das três últimas Câmaras.","gabarito":"C","explicacao":"É a regra do art. 36. Os Grupos julgam o que exceder a competência das Câmaras, como mandados de segurança contra atos das Câmaras, ações rescisórias e revisões criminais (art. 37, § 1º).","fonte":"Regimento Interno do TJSP, arts. 36 e 37","mastigado":"Certo. Um Grupo é a união de duas Câmaras vizinhas, como a 1ª com a 2ª. Se o número de Câmaras for ímpar, um dos Grupos fica com três. Os Grupos julgam causas que vão além do que as Câmaras podem decidir, como rescisórias de seus acórdãos.","teSitua":{"termos":[{"termo":"Grupos de Câmaras","significado":"órgãos formados pela reunião de Câmaras, com competência mais ampla que a delas."},{"termo":"ordem crescente","significado":"sequência do menor para o maior número."}],"exemplo":"Na Seção de Direito Público, a 1ª e a 2ª Câmaras formam o 1º Grupo. Uma ação rescisória contra acórdão da 2ª Câmara foi julgada pelo 1º Grupo, por exceder a competência da própria Câmara."}},{"id":"aut.legislacao_tj.organizacao.0019","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Pelo Regimento Interno do TJSP, as sessões do Órgão Especial, das Turmas Especiais, dos Grupos e das Câmaras podem ser instaladas com a presença de qualquer número de integrantes, e o Conselho Superior da Magistratura pode reunir-se com apenas um ocupante de cargo de direção.","gabarito":"E","explicacao":"O art. 43 exige maioria absoluta dos integrantes para instalar essas sessões, e seu parágrafo único exige, para o Conselho Superior da Magistratura, a presença de ao menos dois ocupantes de cargos de direção e mais dois de seus membros. Para o Órgão Especial, o art. 11 fixa o mínimo de treze.","fonte":"Regimento Interno do TJSP, art. 43 e parágrafo único; art. 11","mastigado":"Errado. Os órgãos colegiados só podem começar a sessão com a maioria absoluta dos integrantes. O Conselho Superior da Magistratura precisa de pelo menos dois dirigentes e mais dois membros presentes.","teSitua":{"termos":[{"termo":"instaladas","significado":"iniciadas de forma válida, com o quórum exigido."},{"termo":"Conselho Superior da Magistratura","significado":"órgão de cúpula do TJSP com funções administrativas."},{"termo":"cargo de direção","significado":"cargos de Presidente, Vice-Presidente e Corregedor Geral."}],"exemplo":"Numa Câmara de cinco desembargadores, apenas dois compareceram por causa de licenças. A sessão não pôde ser instalada, porque seria necessária a presença de pelo menos três, a maioria absoluta."}},{"id":"aut.legislacao_tj.organizacao.0020","subtopico":"legislacao_tj.regimento.organizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos do Regimento Interno do TJSP, o Ouvidor do Tribunal e seu Substituto serão eleitos pelo Órgão Especial para o período de 2 anos, com mandatos coincidentes com o do Presidente do Tribunal, permitida uma reeleição.","gabarito":"C","explicacao":"É o que dispõe o art. 29-A, incluído pelo Assento Regimental 589/2024. A Ouvidoria passou a integrar o Tribunal (art. 2º, VI-A); é vedado ao Ouvidor acumular cargos diretivos e de juiz assessor (§ 2º) e exercer a função por mais de 4 anos consecutivos (§ 5º).","fonte":"Regimento Interno do TJSP, art. 29-A, caput, §§ 2º e 5º (Assento Regimental 589/2024)","mastigado":"Certo. O Ouvidor e o substituto dele são escolhidos pelo Órgão Especial para mandatos de dois anos, que andam junto com o do Presidente. Pode haver uma reeleição, mas não mais de quatro anos seguidos.","teSitua":{"termos":[{"termo":"Ouvidor","significado":"desembargador que dirige a Ouvidoria, canal de reclamações, sugestões e denúncias do público."},{"termo":"Órgão Especial","significado":"órgão de vinte e cinco desembargadores com funções do Pleno."},{"termo":"reeleição","significado":"nova eleição da mesma pessoa para o período seguinte."}],"exemplo":"A desembargadora Marisa foi eleita Ouvidora pelo Órgão Especial para o biênio 2026-2027 e reeleita para 2028-2029. Em 2030, ela não poderá concorrer de novo, porque já terá completado quatro anos seguidos na função."}},{"id":"aut.legislacao_tj.processo.0001","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, a Câmara ou o Grupo que primeiro conhecer de uma causa, ainda que não apreciado o mérito, ou de qualquer incidente,","alternativas":{"A":"terá a competência preventa para os feitos originários conexos e para todos os recursos na causa principal, cautelar, acessória ou incidente, derivados do mesmo ato, fato, contrato ou relação jurídica.","B":"não terá prevenção, se não houver julgado o mérito.","C":"terá prevenção apenas para os embargos de declaração.","D":"perderá a prevenção se o relator se afastar do órgão.","E":"terá prevenção somente se o julgamento tiver sido unânime."},"gabarito":"A","explicacao":"O art. 105 fixa a prevenção da Câmara ou Grupo que primeiro conhecer da causa, ainda que sem apreciar o mérito, para feitos conexos e todos os recursos derivados do mesmo ato, fato, contrato ou relação jurídica, e nas execuções dos julgados. O afastamento dos juízes não rompe a prevenção (§ 1º), e o relator do primeiro recurso fica prevento para os seguintes, enquanto compuser o órgão (§ 3º).","explicacoes":{"A":"Correta: art. 105, caput.","B":"A prevenção existe ainda que não apreciado o mérito.","C":"A prevenção é ampla, não restrita aos embargos.","D":"O afastamento dos juízes não rompe a prevenção (§ 1º).","E":"A unanimidade não é requisito."},"fonte":"Regimento Interno do TJSP, art. 105, caput, §§ 1º e 3º","mastigado":"A resposta é a letra A. A Câmara que recebe primeiro um recurso de determinada causa fica responsável pelos próximos recursos ligados a ela, mesmo que no primeiro não tenha julgado o mérito. Isso evita decisões contraditórias sobre o mesmo caso.","teSitua":{"termos":[{"termo":"competência preventa","significado":"competência fixada para o órgão que primeiro recebeu a causa, atraindo os processos ligados a ela."},{"termo":"mérito","significado":"questão principal discutida no processo."},{"termo":"conexos","significado":"processos ligados entre si por terem o mesmo pedido ou a mesma causa."}],"exemplo":"A 10ª Câmara de Direito Privado julgou um agravo de instrumento num processo de despejo. Mais tarde, a apelação contra a sentença do mesmo processo foi distribuída por prevenção à 10ª Câmara, que já conhecia o caso."}},{"id":"aut.legislacao_tj.processo.0002","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos do Regimento Interno do TJSP, o afastamento dos juízes que participaram do julgamento anterior rompe a prevenção, devendo o novo processo ser livremente distribuído a qualquer órgão da Seção.","gabarito":"E","explicacao":"O art. 105, § 1º, diz o contrário: o afastamento dos juízes que participaram do julgamento anterior não rompe a prevenção, sendo o novo processo distribuído a quem os substituir ou assumir a cadeira vaga.","fonte":"Regimento Interno do TJSP, art. 105, § 1º","mastigado":"Errado. A prevenção pertence ao órgão e à cadeira, não à pessoa. Se o desembargador que julgou antes saiu, o novo recurso vai para quem ocupa a cadeira dele na mesma Câmara.","teSitua":{"termos":[{"termo":"prevenção","significado":"regra que liga processos relacionados ao órgão que primeiro conheceu da causa."},{"termo":"distribuído","significado":"encaminhado a um órgão julgador e a um relator."}],"exemplo":"O desembargador Rui relatou um agravo e depois se aposentou. Quando chegou a apelação do mesmo processo, ela foi distribuída à cadeira que era de Rui, agora ocupada pela desembargadora Lúcia, na mesma Câmara."}},{"id":"aut.legislacao_tj.processo.0003","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Regimento Interno do TJSP, as sessões realizar-se-ão","alternativas":{"A":"entre nove e dezessete horas dos dias úteis, podendo haver prorrogação; no período de 20 de dezembro a 20 de janeiro, não serão realizadas audiências nem sessões de julgamento.","B":"entre oito e dezoito horas, inclusive aos sábados.","C":"entre treze e dezenove horas dos dias úteis, sem prorrogação.","D":"em qualquer horário, a critério do presidente, inclusive de 20 de dezembro a 20 de janeiro.","E":"entre nove e dezessete horas, suspendendo-se apenas de 24 de dezembro a 6 de janeiro."},"gabarito":"A","explicacao":"O art. 116 fixa as sessões entre 9h e 17h dos dias úteis, com prorrogação possível. O § 2º veda audiências e sessões de 20 de dezembro a 20 de janeiro, com suspensão dos prazos; até 6 de janeiro o expediente é por plantões, e de 6 a 20 de janeiro há expediente regular nas unidades (§ 4º). O Órgão Especial e as Câmaras Ordinárias fazem sessões presenciais semanais, facultada periodicidade maior não superior a um mês (§ 1º).","explicacoes":{"A":"Correta: art. 116, caput e § 2º.","B":"As sessões são em dias úteis, entre 9h e 17h.","C":"O horário é de 9h às 17h, e pode haver prorrogação.","D":"Há horário regimental e vedação de sessões no período de 20/12 a 20/1.","E":"O período sem sessões vai de 20 de dezembro a 20 de janeiro."},"fonte":"Regimento Interno do TJSP, art. 116, caput, §§ 1º, 2º e 4º","mastigado":"A resposta é a letra A. As sessões do Tribunal acontecem em dias úteis, das nove às dezessete horas, podendo se estender. Entre 20 de dezembro e 20 de janeiro não há sessões de julgamento nem audiências, e os prazos ficam suspensos.","teSitua":{"termos":[{"termo":"sessões","significado":"reuniões dos órgãos colegiados para julgar processos."},{"termo":"prorrogação","significado":"extensão do horário além do previsto."},{"termo":"audiências","significado":"atos com a presença das partes para ouvir depoimentos ou tentar acordo."}],"exemplo":"A sessão da 3ª Câmara Criminal começou às 13h e, com muitos processos na pauta, foi prorrogada até as 18h. Já em 5 de janeiro não houve sessão, porque o período de 20 de dezembro a 20 de janeiro é sem julgamentos."}},{"id":"aut.legislacao_tj.processo.0004","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Regimento Interno do TJSP, se, até trinta minutos após a hora marcada, o magistrado responsável pela audiência não houver comparecido, poderão os presentes retirar-se, registrado o fato em livro próprio.","gabarito":"C","explicacao":"É a regra do art. 118. As audiências no Tribunal realizam-se em lugar, dia e hora designados pelo desembargador que preside os trabalhos (art. 117).","fonte":"Regimento Interno do TJSP, arts. 117 e 118","mastigado":"Certo. Se o magistrado não aparecer até meia hora depois do horário marcado, as pessoas podem ir embora. O fato fica registrado em livro, para que ninguém seja prejudicado.","teSitua":{"termos":[{"termo":"audiência","significado":"ato com a presença das partes e outras pessoas para ouvir depoimentos ou tentar acordo."},{"termo":"livro próprio","significado":"livro oficial destinado a registrar esse tipo de ocorrência."}],"exemplo":"A audiência estava marcada para as 14h no Tribunal. Às 14h30, o desembargador ainda não havia chegado. O advogado Sérgio e as testemunhas puderam se retirar, e o servidor registrou a ocorrência no livro."}},{"id":"aut.legislacao_tj.processo.0005","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Constatado erro na ata de sessão de julgamento, o interessado, nos termos do Regimento Interno do TJSP, poderá reclamar mediante petição dirigida ao presidente da sessão","alternativas":{"A":"dentro de quarenta e oito horas, contadas da publicação ou, não havendo, da aprovação da ata, e a reclamação não suspenderá o prazo para recurso.","B":"dentro de cinco dias, com suspensão automática do prazo recursal.","C":"a qualquer tempo, antes do trânsito em julgado.","D":"dentro de dez dias, perante o Presidente do Tribunal.","E":"dentro de vinte e quatro horas, com efeito suspensivo."},"gabarito":"A","explicacao":"O art. 122 dá 48 horas, contadas da publicação ou, não havendo, da aprovação da ata. A reclamação não suspende o prazo para recurso; se acolhida, restituem-se os dias que faltarem (parágrafo único). As atas são aprovadas na sessão subsequente (art. 120).","explicacoes":{"A":"Correta: art. 122 e parágrafo único.","B":"O prazo é de 48 horas e não há suspensão.","C":"Há prazo de 48 horas.","D":"O prazo é de 48 horas e a petição vai ao presidente da sessão.","E":"O prazo é de 48 horas e não suspende o prazo recursal."},"fonte":"Regimento Interno do TJSP, arts. 120 e 122","mastigado":"A resposta é a letra A. Achou erro na ata? São quarenta e oito horas para reclamar ao presidente da sessão. Enquanto isso, o prazo de recurso continua correndo; se a reclamação for aceita, os dias perdidos são devolvidos.","teSitua":{"termos":[{"termo":"ata","significado":"registro escrito do que aconteceu na sessão."},{"termo":"prazo para recurso","significado":"tempo que a parte tem para recorrer da decisão."}],"exemplo":"Na ata publicada, constou que o advogado Paulo fez sustentação oral, mas quem falou foi a advogada Inês. Paulo protocolou reclamação ao presidente da sessão no dia seguinte, sem deixar de contar o prazo do recurso."}},{"id":"aut.legislacao_tj.processo.0006","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Conforme o Regimento Interno do TJSP, independe de pauta o julgamento de","alternativas":{"A":"habeas corpus, desaforamento, conflito de jurisdição, de competência ou de atribuição e embargos de declaração em matéria criminal.","B":"apelações cíveis com pedido de efeito suspensivo.","C":"ações rescisórias.","D":"agravos de instrumento contra tutela de urgência.","E":"mandados de segurança em geral."},"gabarito":"A","explicacao":"O art. 123, § 3º, com redação do Assento Regimental 573/2019, dispensa a pauta para habeas corpus, desaforamento, conflito de jurisdição, de competência ou de atribuição e embargos de declaração em matéria criminal. Nas demais matérias, os embargos de declaração julgados na sessão subsequente também dispensam pauta (§ 4º).","explicacoes":{"A":"Correta: art. 123, § 3º.","B":"Apelações dependem de pauta.","C":"Ações rescisórias dependem de pauta.","D":"Agravos de instrumento dependem de pauta.","E":"Mandados de segurança dependem de pauta."},"fonte":"Regimento Interno do TJSP, art. 123, §§ 3º e 4º","mastigado":"A resposta é a letra A. Alguns casos são tão urgentes ou simples que podem ser julgados sem aviso prévio na pauta, como o habeas corpus, que trata da liberdade de alguém, e os conflitos de competência.","teSitua":{"termos":[{"termo":"pauta","significado":"lista publicada dos processos que serão julgados em determinada sessão."},{"termo":"habeas corpus","significado":"ação para proteger quem sofre ou está ameaçado de prisão ilegal."},{"termo":"desaforamento","significado":"transferência do julgamento pelo júri para outra comarca."},{"termo":"embargos de declaração","significado":"recurso para esclarecer obscuridade, contradição ou omissão da decisão."}],"exemplo":"Um habeas corpus em favor de Mateus, preso há semanas sem denúncia, chegou à 5ª Câmara Criminal na segunda-feira e foi julgado na sessão de quarta, sem precisar constar da pauta publicada."}},{"id":"aut.legislacao_tj.processo.0007","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Regimento Interno do TJSP, a pauta de julgamento será publicada","alternativas":{"A":"pelo menos cinco dias antes da data da sessão, e sua cópia será afixada à porta da sala da sessão com antecedência mínima de quinze minutos.","B":"pelo menos dez dias antes da sessão, dispensada a afixação.","C":"no próprio dia da sessão, com afixação de uma hora antes.","D":"pelo menos quarenta e oito horas antes da sessão.","E":"pelo menos quinze dias antes, com afixação de cinco minutos antes."},"gabarito":"A","explicacao":"O art. 127, com redação do Assento Regimental 552/2016, exige publicação da pauta pelo menos cinco dias antes da sessão, afixação de cópia à porta da sala com antecedência mínima de quinze minutos e entrega a cada desembargador.","explicacoes":{"A":"Correta: art. 127.","B":"O prazo é de pelo menos cinco dias, e há afixação.","C":"A pauta é publicada com cinco dias de antecedência.","D":"O prazo é de cinco dias.","E":"Os prazos são de cinco dias e quinze minutos."},"fonte":"Regimento Interno do TJSP, art. 127","mastigado":"A resposta é a letra A. Os advogados precisam saber com antecedência quando o processo será julgado. Por isso, a pauta sai pelo menos cinco dias antes, e uma cópia é colocada na porta da sala quinze minutos antes do início.","teSitua":{"termos":[{"termo":"pauta de julgamento","significado":"lista dos processos que serão julgados na sessão."},{"termo":"afixada","significado":"colocada em local visível ao público."}],"exemplo":"A sessão da 2ª Câmara de Direito Público foi marcada para uma terça-feira. A pauta foi publicada na quarta da semana anterior, seis dias antes, e no dia da sessão uma cópia foi fixada na porta da sala às 13h30, antes do início às 14h."}},{"id":"aut.legislacao_tj.processo.0008","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Regimento Interno do TJSP, nenhum feito será julgado na ausência do relator, ainda que já tenha proferido voto, salvo se, iniciado o julgamento, vier ele a se afastar, computando-se os votos proferidos.","gabarito":"C","explicacao":"É a regra do art. 134, caput. A ausência do revisor que ainda não votou acarreta adiamento, salvo afastamento superior a quarenta dias, quando é substituído (§ 1º); a ausência ocasional de vogal não acarreta adiamento se houver substituição (§ 2º).","fonte":"Regimento Interno do TJSP, art. 134","mastigado":"Certo. Sem o relator, o processo não é julgado, porque é ele quem conhece o caso e apresenta o relatório. A exceção é quando o julgamento já começou e ele se afasta depois: aí os votos já dados valem.","teSitua":{"termos":[{"termo":"relator","significado":"desembargador sorteado que estuda o processo, faz o relatório e vota primeiro."},{"termo":"feito","significado":"processo ou recurso em julgamento."}],"exemplo":"O relator da apelação de Joana estava doente no dia da sessão. Mesmo com os demais desembargadores presentes, o recurso não foi julgado e ficou para a sessão seguinte."}},{"id":"aut.legislacao_tj.processo.0009","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Ressalvada disposição legal em contrário, o Regimento Interno do TJSP NÃO admite sustentação oral no julgamento de","alternativas":{"A":"embargos de declaração.","B":"apelação cível.","C":"ação rescisória.","D":"mandado de segurança originário.","E":"agravo de instrumento referente a tutela provisória de urgência."},"gabarito":"A","explicacao":"O art. 146, § 4º, exclui a sustentação oral em embargos declaratórios, incidente de suspeição, conflito de competência, arquivamento de inquérito ou representação criminal e agravo, exceto o de instrumento referente às tutelas provisórias de urgência ou da evidência e o interno contra extinção de feito originário (art. 937, VI, do CPC).","explicacoes":{"A":"Correta: art. 146, § 4º.","B":"Há sustentação oral em apelação.","C":"Há sustentação oral em ação rescisória.","D":"Há sustentação oral em mandado de segurança.","E":"O agravo de instrumento sobre tutela de urgência é exceção expressa que admite a sustentação."},"fonte":"Regimento Interno do TJSP, art. 146, § 4º","mastigado":"A resposta é a letra A. Nos embargos de declaração, que só servem para esclarecer a decisão, o advogado não fala na tribuna. Mas no agravo contra decisão de urgência, a sustentação é permitida.","teSitua":{"termos":[{"termo":"sustentação oral","significado":"fala do advogado ou do promotor na sessão, defendendo sua tese antes do voto."},{"termo":"tutela provisória de urgência","significado":"decisão rápida e provisória para evitar dano grave enquanto o processo corre."},{"termo":"ação rescisória","significado":"ação para desfazer decisão definitiva em casos previstos em lei."}],"exemplo":"A advogada Clara pediu para fazer sustentação oral no julgamento dos embargos de declaração que opôs. O pedido foi indeferido. Semanas antes, porém, ela sustentou normalmente num agravo contra decisão que negou uma liminar."}},{"id":"aut.legislacao_tj.processo.0010","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":3,"enunciado":"Pelo Regimento Interno do TJSP, adotado o sistema de inscrição prévia para sustentação oral por e-mail dirigido ao cartório, o pedido deverá ser formulado com antecedência mínima de 24 horas em relação à hora prevista para o início da sessão, ficando sem efeito a inscrição se o advogado não comparecer para ratificá-la até o início da sessão.","gabarito":"C","explicacao":"É o que dispõe o art. 146, II e alínea b, com redação dos Assentos Regimentais 581/2019 e 588/2023. Mesmo após esse prazo, o pedido pode ser feito até o início da sessão, no local, ao oficial de Câmara, observada a ordem de formulação (inciso III).","fonte":"Regimento Interno do TJSP, art. 146, II e III","mastigado":"Certo. Quando a Câmara aceita inscrição por e-mail, o advogado deve se inscrever até vinte e quatro horas antes da sessão e confirmar presença até o início. Se não aparecer, a inscrição cai.","teSitua":{"termos":[{"termo":"inscrição prévia","significado":"pedido feito com antecedência para garantir a vez de falar na sessão."},{"termo":"sustentação oral","significado":"fala do advogado na sessão, defendendo sua tese antes dos votos."},{"termo":"ratificá-la","significado":"confirmá-la pessoalmente no dia da sessão."}],"exemplo":"O advogado Rogério mandou e-mail ao cartório da Câmara dois dias antes da sessão, pedindo para sustentar. No dia, não apareceu até o início dos trabalhos, e sua inscrição ficou sem efeito."}},{"id":"aut.legislacao_tj.processo.0011","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":2,"enunciado":"Havendo mais de uma sustentação oral no mesmo recurso, segundo o Regimento Interno do TJSP,","alternativas":{"A":"falará em primeiro lugar o recorrente e, por último, o Ministério Público, quando não for o recorrente.","B":"falará primeiro o recorrido e depois o recorrente.","C":"falará primeiro o Ministério Público, em qualquer caso.","D":"a ordem será definida por sorteio.","E":"falará primeiro o advogado mais antigo inscrito na OAB."},"gabarito":"A","explicacao":"O art. 147 fixa: nos feitos originários, fala primeiro o autor ou impetrante; nos recursos, o recorrente; por último, o Ministério Público, quando não for autor, impetrante ou recorrente. No recurso adesivo, fala primeiro o recorrente principal (§ 1º); o interveniente fala por último (§ 2º).","explicacoes":{"A":"Correta: art. 147, caput.","B":"Nos recursos, fala primeiro o recorrente.","C":"O Ministério Público fala por último, quando não é recorrente.","D":"Não há sorteio.","E":"Não há esse critério."},"fonte":"Regimento Interno do TJSP, art. 147","mastigado":"A resposta é a letra A. Quem recorreu fala primeiro, porque é quem está pedindo a mudança da decisão. Depois fala o outro lado e, por último, o Ministério Público, quando ele não é o autor do recurso.","teSitua":{"termos":[{"termo":"recorrente","significado":"parte que apresentou o recurso."},{"termo":"Ministério Público","significado":"instituição que fiscaliza a lei e atua em defesa do interesse público."},{"termo":"recorrido","significado":"parte contra quem o recurso foi apresentado."}],"exemplo":"Na apelação de uma ação de alimentos, falou primeiro a advogada do pai, que recorreu; depois, o advogado da criança; e, por último, o promotor de Justiça, que atua no processo como fiscal da lei."}},{"id":"aut.legislacao_tj.processo.0012","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Regimento Interno do TJSP, o Presidente do Tribunal não terá voto nas sessões a que presidir, salvo","alternativas":{"A":"em matéria constitucional, para desempate em qualquer matéria e quando for relator nato.","B":"em qualquer matéria, se assim desejar.","C":"apenas em matéria administrativa.","D":"somente em matéria criminal.","E":"em nenhuma hipótese."},"gabarito":"A","explicacao":"O art. 153 lista as exceções em que o Presidente vota: matéria constitucional (I), desempate em qualquer matéria (II) e quando for relator nato (III). Em geral, as deliberações são por maioria simples (art. 154). Em matéria administrativa e disciplinar do Órgão Especial, o art. 26, II, n, prevê que ele vote em todas as questões.","explicacoes":{"A":"Correta: art. 153.","B":"O voto do Presidente é restrito às hipóteses do art. 153.","C":"O art. 153 não limita à matéria administrativa.","D":"Não há essa restrição.","E":"Há hipóteses em que ele vota."},"fonte":"Regimento Interno do TJSP, arts. 153 e 154","mastigado":"A resposta é a letra A. O Presidente que dirige a sessão normalmente só organiza o julgamento. Ele vota quando se discute a Constituição, quando há empate ou quando ele é o relator natural do caso.","teSitua":{"termos":[{"termo":"matéria constitucional","significado":"questão que envolve a interpretação ou a aplicação da Constituição."},{"termo":"desempate","significado":"voto que decide uma votação empatada."},{"termo":"relator nato","significado":"julgador que é relator do caso por força do próprio cargo, sem sorteio."}],"exemplo":"No Órgão Especial, uma arguição de inconstitucionalidade de lei estadual foi julgada. Por se tratar de matéria constitucional, o Presidente do Tribunal, que presidia a sessão, também votou."}},{"id":"aut.legislacao_tj.processo.0013","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":4,"enunciado":"Em julgamento de agravo em matéria cível no TJSP, a votação resultou empatada. Segundo o Regimento Interno,","alternativas":{"A":"considerar-se-á mantida a decisão agravada.","B":"prevalecerá o voto do relator.","C":"será convocado o Presidente do Tribunal para desempatar.","D":"o agravo será considerado provido.","E":"o julgamento será anulado e repetido."},"gabarito":"A","explicacao":"O art. 139, § 3º, III, determina que, havendo empate no julgamento de agravos, considera-se mantida a decisão agravada. Nas ações rescisórias, convoca-se juiz de outro órgão (inciso I); na uniformização, desempata o Presidente da Seção (inciso II); em matéria criminal, persistindo empate sobre a pena, prevalece a decisão mais favorável ao réu, se o presidente já tiver votado (§ 2º).","explicacoes":{"A":"Correta: art. 139, § 3º, III.","B":"Não há prevalência do voto do relator.","C":"Não é a regra para agravos.","D":"O empate mantém a decisão agravada.","E":"Não há anulação."},"fonte":"Regimento Interno do TJSP, art. 139, §§ 2º e 3º","mastigado":"A resposta é a letra A. Se os desembargadores empatam ao julgar um agravo, a decisão que foi atacada continua valendo. Quem recorreu não conseguiu convencer a maioria, então nada muda.","teSitua":{"termos":[{"termo":"agravo","significado":"recurso contra decisão tomada no meio do processo."},{"termo":"decisão agravada","significado":"decisão contra a qual o agravo foi interposto."}],"exemplo":"Num agravo interno cível julgado por um Grupo de Câmaras, um dos juízes declarou-se impedido e a votação terminou empatada, três a três. Pela regra do Regimento, ficou mantida a decisão que havia sido agravada."}},{"id":"aut.legislacao_tj.processo.0014","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Vencido o relator no mérito, segundo o Regimento Interno do TJSP,","alternativas":{"A":"caberá ao desembargador designado redigir o acórdão, designando-se, preferencialmente, o que primeiro expôs a tese vencedora.","B":"o próprio relator vencido redigirá o acórdão, por ser o juiz preparador.","C":"o Presidente da Câmara redigirá o acórdão.","D":"o julgamento será repetido com novo relator.","E":"o revisor redigirá o acórdão, em qualquer caso."},"gabarito":"A","explicacao":"O art. 155 atribui a redação ao desembargador designado, preferencialmente o que primeiro expôs a tese vencedora (§ 1º). Publicado o acórdão, cessa sua vinculação, salvo quanto a embargos de declaração, infringentes criminais e reexame do art. 1.040, II, do CPC (§ 2º). O vencido declara voto (art. 156).","explicacoes":{"A":"Correta: art. 155, caput e § 1º.","B":"O relator vencido não redige o acórdão.","C":"Não é a regra regimental.","D":"Não há repetição do julgamento.","E":"A designação recai preferencialmente em quem primeiro expôs a tese vencedora."},"fonte":"Regimento Interno do TJSP, arts. 155 e 156","mastigado":"A resposta é a letra A. Se o relator perde a votação, não faz sentido ele escrever uma decisão contrária ao que pensa. Escreve o acórdão quem venceu, de preferência quem primeiro apresentou a tese vencedora.","teSitua":{"termos":[{"termo":"relator","significado":"desembargador sorteado que estuda o processo e vota primeiro."},{"termo":"acórdão","significado":"decisão escrita de um órgão colegiado do tribunal."},{"termo":"tese vencedora","significado":"entendimento que obteve a maioria dos votos."}],"exemplo":"Na apelação de Henrique, o relator votou por negar o recurso, mas o segundo juiz abriu divergência e foi acompanhado pelo terceiro. O segundo juiz, que primeiro expôs a tese vencedora, foi designado para redigir o acórdão."}},{"id":"aut.legislacao_tj.processo.0015","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Regimento Interno do TJSP, as conclusões do acórdão serão publicadas no órgão oficial, para efeito de intimação, nos cinco dias seguintes ao registro.","gabarito":"C","explicacao":"É o que diz o art. 163. Depois de assinado, o acórdão é registrado em livro próprio ou meio eletrônico (art. 162); é assinado pelo relator e, facultativamente, pelo presidente da sessão (art. 159).","fonte":"Regimento Interno do TJSP, arts. 159, 162 e 163","mastigado":"Certo. Depois que o acórdão é assinado e registrado, a parte final dele precisa sair no Diário Oficial em até cinco dias. É essa publicação que intima as partes e faz começar a contar o prazo de recurso.","teSitua":{"termos":[{"termo":"acórdão","significado":"decisão escrita de um órgão colegiado do tribunal."},{"termo":"órgão oficial","significado":"Diário da Justiça, onde são publicados os atos do Judiciário."},{"termo":"intimação","significado":"comunicação oficial de um ato do processo às partes."}],"exemplo":"O acórdão da apelação de Marina foi assinado e registrado numa segunda-feira. Na sexta-feira da mesma semana, suas conclusões saíram no Diário da Justiça, e a partir daí correu o prazo para eventual recurso."}},{"id":"aut.legislacao_tj.processo.0016","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, o desembargador que formular pedido de vista devolverá os autos em até","alternativas":{"A":"dez dias, prorrogáveis por no máximo mais dez, sendo o feito incluído automaticamente na pauta da sessão subsequente; o prazo do relator para exame e voto é de trinta dias, salvo outro estabelecido.","B":"trinta dias, prorrogáveis indefinidamente.","C":"cinco dias, improrrogáveis.","D":"sessenta dias, sem necessidade de inclusão em pauta.","E":"quinze dias, prorrogáveis por mais quinze."},"gabarito":"A","explicacao":"O art. 173 fixa a devolução em até dez dias, prorrogáveis por no máximo mais dez a pedido ao presidente do órgão (ou ao Presidente do Tribunal, no Órgão Especial), com inclusão automática na pauta seguinte; não devolvidos, o presidente requisita os autos (§ 1º). O art. 172 dá ao relator e ao revisor trinta dias para exame e voto.","explicacoes":{"A":"Correta: arts. 172 e 173.","B":"A vista é de dez dias, com uma prorrogação de até dez.","C":"O prazo é de dez dias e admite prorrogação.","D":"O prazo é de dez dias, e há inclusão automática em pauta.","E":"O prazo é de dez dias, prorrogáveis por mais dez."},"fonte":"Regimento Interno do TJSP, arts. 172 e 173","mastigado":"A resposta é a letra A. Quem pede vista para estudar melhor o caso tem dez dias para devolver, podendo pedir mais dez. Depois, o processo volta sozinho para a pauta da sessão seguinte. Já o relator tem trinta dias para preparar o voto.","teSitua":{"termos":[{"termo":"pedido de vista","significado":"pedido de um julgador para examinar melhor o processo antes de votar."},{"termo":"autos","significado":"conjunto de peças e documentos do processo."},{"termo":"pauta","significado":"lista dos processos que serão julgados em determinada sessão."}],"exemplo":"Na sessão de 3 de março, a desembargadora Vera pediu vista de uma apelação. Ela pediu prorrogação e devolveu os autos em 20 de março, dentro dos vinte dias possíveis. O processo entrou automaticamente na pauta da sessão seguinte."}},{"id":"aut.legislacao_tj.processo.0017","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos do Regimento Interno do TJSP, os autos somente sairão da Secretaria por força de disposição legal, regulamentar ou ordem judicial, com registro de carga, sob pena de responsabilidade do servidor encarregado.","gabarito":"C","explicacao":"É a regra do art. 174. A remessa de autos aos desembargadores é acompanhada de relação que vale como recibo (art. 187, § 1º).","fonte":"Regimento Interno do TJSP, arts. 174 e 187","mastigado":"Certo. O processo não pode sair da Secretaria sem motivo legal ou ordem do juiz, e toda saída precisa ser registrada como carga. Se o servidor deixar sair sem isso, ele responde.","teSitua":{"termos":[{"termo":"Secretaria","significado":"setor administrativo que guarda e movimenta os processos do Tribunal."},{"termo":"registro de carga","significado":"anotação de quem retirou os autos, quando e por qual motivo."}],"exemplo":"Um advogado pediu ao servidor Lauro que o deixasse levar os autos físicos para tirar cópias fora, sem registro. Lauro recusou, porque os autos só saem com carga registrada e base legal ou ordem judicial."}},{"id":"aut.legislacao_tj.processo.0018","subtopico":"legislacao_tj.regimento.processo","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Regimento Interno do TJSP, a remessa e a apresentação de feitos no Tribunal dar-se-ão no prazo de","alternativas":{"A":"quarenta e oito horas, se urgentes, e cinco dias, nos demais casos, contados da publicação da última decisão ou do despacho de remessa.","B":"vinte e quatro horas, se urgentes, e dez dias, nos demais.","C":"cinco dias, em qualquer caso.","D":"dez dias, se urgentes, e trinta dias, nos demais.","E":"setenta e duas horas, se urgentes, e quinze dias, nos demais."},"gabarito":"A","explicacao":"O art. 175 fixa 48 horas para feitos urgentes e 5 dias para os demais, contados da publicação da última decisão ou do despacho de remessa na instância anterior (§ 1º). Na remessa pelo correio, considera-se apresentado na data da postagem (§ 2º).","explicacoes":{"A":"Correta: art. 175, a e b, e § 1º.","B":"Os prazos são de 48 horas e 5 dias.","C":"Há prazo diferente para feitos urgentes.","D":"Os prazos são de 48 horas e 5 dias.","E":"Os prazos são de 48 horas e 5 dias."},"fonte":"Regimento Interno do TJSP, art. 175","mastigado":"A resposta é a letra A. Depois que o juiz manda o processo subir, o cartório tem quarenta e oito horas se for urgente e cinco dias nos demais casos para enviá-lo ao Tribunal.","teSitua":{"termos":[{"termo":"remessa","significado":"envio dos autos de um órgão para outro."},{"termo":"despacho de remessa","significado":"ordem do juiz que manda enviar o processo ao Tribunal."}],"exemplo":"O juiz da vara de família determinou a remessa de uma apelação ao Tribunal numa segunda-feira. Como o caso não era urgente, o cartório tinha cinco dias para enviá-lo, o que fez na quinta-feira."}},{"id":"aut.legislacao_tj.processo.0019","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":2,"enunciado":"Conforme o Regimento Interno do TJSP, os feitos serão distribuídos aos desembargadores em audiência pública designada em dias certos da semana, segundo as cadeiras que ocupam nos órgãos julgadores, mediante sorteio, de forma ininterrupta e paritária, respeitadas prevenções e impedimentos.","gabarito":"C","explicacao":"É a regra do art. 181. Na vacância ou afastamento, a distribuição à cadeira prossegue sob responsabilidade do substituto ou sucessor (§ 1º). No Órgão Especial, não há distribuição ao Presidente, ao Vice-Presidente e ao Corregedor (art. 181-A). Reclamações contra irregularidades são decididas pelo Vice-Presidente ou pelos Presidentes de Seção (art. 182).","fonte":"Regimento Interno do TJSP, arts. 181, 181-A e 182","mastigado":"Certo. Os processos são sorteados entre as cadeiras dos desembargadores, em sessão pública, sem parar e de forma igual para todos, respeitando os casos de prevenção e de impedimento.","teSitua":{"termos":[{"termo":"distribuídos","significado":"repartidos entre os julgadores para definir quem será o relator."},{"termo":"paritária","significado":"feita em igualdade, com número equilibrado para cada um."},{"termo":"impedimentos","significado":"situações que proíbem o julgador de atuar no processo."}],"exemplo":"Toda terça-feira, a Secretaria faz a audiência pública de distribuição. Os recursos que chegaram são sorteados entre as cadeiras da Seção, de modo que cada desembargador recebe quantidade semelhante de processos."}},{"id":"aut.legislacao_tj.processo.0020","subtopico":"legislacao_tj.regimento.processo","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Regimento Interno do TJSP, registrado e distribuído o feito, abrir-se-á vista à Procuradoria-Geral de Justiça somente após despacho do relator, devendo o Ministério Público manifestar-se em trinta dias.","gabarito":"E","explicacao":"O art. 186 manda abrir vista à Procuradoria-Geral de Justiça, se for o caso, independentemente de despacho, e o parágrafo único fixa o prazo de manifestação do Ministério Público em dez dias ou, havendo urgência, em cinco, salvo previsão legal.","fonte":"Regimento Interno do TJSP, art. 186 e parágrafo único","mastigado":"Errado. Quando o Ministério Público precisa se manifestar, a Secretaria já abre vista sem esperar despacho do relator. E o prazo dele é de dez dias, ou cinco se o caso for urgente, e não trinta.","teSitua":{"termos":[{"termo":"vista","significado":"envio dos autos para que alguém se manifeste no processo."},{"termo":"Procuradoria-Geral de Justiça","significado":"órgão do Ministério Público estadual que atua perante o Tribunal."},{"termo":"despacho","significado":"ordem simples do juiz para dar andamento ao processo."}],"exemplo":"Um recurso envolvendo interesse de criança foi distribuído. A Secretaria, sem esperar despacho, abriu vista à Procuradoria-Geral de Justiça, que se manifestou em dez dias."}},{"id":"aut.legislacao_tj.processo_eletronico.0001","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (Tomo I), processo eletrônico é o processo judicial cujas peças, documentos e atos processuais constituem um conjunto de arquivos digitais, que tramitam e são transmitidos, comunicados, armazenados e consultados por meio eletrônico, nos termos da Lei nº 11.419/2006.","gabarito":"C","explicacao":"É a definição do art. 1.189. Todos os atos do processo eletrônico são assinados eletronicamente, por certificação digital (art. 1.194).","fonte":"NSCGJ, Tomo I, arts. 1.189 e 1.194 (consolidação de 2017)","mastigado":"Certo. No processo eletrônico, tudo é arquivo digital: petições, documentos e decisões circulam, ficam guardados e são consultados pelo computador, conforme a lei federal do processo eletrônico.","teSitua":{"termos":[{"termo":"processo eletrônico","significado":"processo judicial que tramita inteiramente em meio digital."},{"termo":"arquivos digitais","significado":"documentos em formato de computador, como PDF."}],"exemplo":"A ação de Paulo contra a companhia aérea foi ajuizada pela internet. A petição, os documentos, a contestação e a sentença são arquivos digitais, consultados pelo sistema sem nenhuma folha de papel."}},{"id":"aut.legislacao_tj.processo_eletronico.0002","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, as reproduções digitalizadas de documentos juntadas aos autos eletrônicos por advogados públicos ou privados","alternativas":{"A":"fazem a mesma prova que os originais, ressalvada a alegação motivada e fundamentada de adulteração, devendo os originais ser preservados pelo detentor até o final do prazo para ação rescisória.","B":"não têm valor probatório, salvo se autenticadas em tabelionato.","C":"valem apenas até a sentença, quando os originais devem ser entregues em cartório.","D":"dispensam a guarda dos originais em qualquer caso.","E":"só valem se digitalizadas pelo próprio ofício de justiça."},"gabarito":"A","explicacao":"O art. 1.192, § 3º, dá às reproduções digitalizadas juntadas por órgãos da Justiça, Ministério Público, procuradorias, repartições públicas e advogados a mesma força probante dos originais, salvo alegação motivada de adulteração. O § 4º obriga o detentor a preservar os originais até o fim do prazo para ação rescisória.","explicacoes":{"A":"Correta: art. 1.192, §§ 3º e 4º.","B":"Não se exige autenticação em tabelionato.","C":"Não há essa restrição.","D":"Os originais devem ser preservados até o prazo da rescisória (§ 4º).","E":"Os advogados também podem digitalizar e juntar."},"fonte":"NSCGJ, Tomo I, art. 1.192, §§ 3º e 4º (consolidação de 2017)","mastigado":"A resposta é a letra A. A cópia digitalizada que o advogado junta ao processo vale como o original, a não ser que alguém prove suspeita de adulteração. Mas o papel original deve ser guardado até acabar o prazo da ação rescisória.","teSitua":{"termos":[{"termo":"reproduções digitalizadas","significado":"cópias de documentos de papel transformadas em arquivo digital."},{"termo":"adulteração","significado":"alteração fraudulenta de um documento."},{"termo":"ação rescisória","significado":"ação para desfazer decisão definitiva em casos previstos em lei."}],"exemplo":"A advogada Sônia digitalizou o contrato original do cliente e o juntou ao processo eletrônico. A cópia vale como prova. O cliente deve guardar o contrato em papel até terminar o prazo para eventual ação rescisória."}},{"id":"aut.legislacao_tj.processo_eletronico.0003","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, é de exclusiva responsabilidade do titular de certificação digital o uso e sigilo da chave privada da sua identidade digital, não sendo oponível, em nenhuma hipótese, alegação de seu uso indevido.","gabarito":"C","explicacao":"É o que diz o art. 1.193. A autenticidade e a integridade dos atos são garantidas por certificação digital ICP-Brasil, padrão A3 (art. 1.192).","fonte":"NSCGJ, Tomo I, arts. 1.192 e 1.193 (consolidação de 2017)","mastigado":"Certo. O certificado digital é como a assinatura da pessoa. Se ela empresta ou deixa alguém usar, responde por tudo o que for feito com ele e não pode depois alegar que foi outra pessoa.","teSitua":{"termos":[{"termo":"certificação digital","significado":"identidade eletrônica que permite assinar documentos com segurança."},{"termo":"chave privada","significado":"código secreto do certificado digital, que só o titular deve conhecer."},{"termo":"oponível","significado":"que pode ser alegado contra alguém para se defender."}],"exemplo":"O advogado Ronaldo deixou o certificado digital e a senha com o estagiário, que protocolou uma petição errada. Ronaldo não pode alegar uso indevido: a responsabilidade pelo sigilo do certificado é exclusivamente dele."}},{"id":"aut.legislacao_tj.processo_eletronico.0004","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, nos processos eletrônicos, será considerada original a versão impressa e arquivada pelo ofício de justiça.","gabarito":"E","explicacao":"O art. 1.195 considera original a versão armazenada no servidor do Tribunal de Justiça, enquanto o processo estiver em tramitação ou arquivado.","fonte":"NSCGJ, Tomo I, art. 1.195 (consolidação de 2017)","mastigado":"Errado. No processo eletrônico, o original é o arquivo guardado no servidor do Tribunal, e não uma cópia impressa no cartório. Isso vale enquanto o processo tramita e também depois de arquivado.","teSitua":{"termos":[{"termo":"versão armazenada no servidor","significado":"arquivo guardado nos computadores centrais do Tribunal."},{"termo":"ofício de justiça","significado":"cartório judicial que dá andamento aos processos."}],"exemplo":"Houve divergência entre uma cópia impressa de decisão guardada pelo advogado e o arquivo do sistema. Prevaleceu o arquivo armazenado no servidor do Tribunal, que é a versão original."}},{"id":"aut.legislacao_tj.processo_eletronico.0005","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, a correta formação do processo eletrônico constitui responsabilidade","alternativas":{"A":"do advogado ou procurador, que deverá carregar as peças essenciais e documentos na ordem em que devam aparecer: petição, procuração, documentos pessoais ou atos constitutivos, documentos da causa e comprovante de despesas.","B":"do ofício de justiça, que deverá reorganizar as peças enviadas.","C":"do distribuidor, exclusivamente.","D":"do juiz, que determinará a ordem das peças.","E":"da Secretaria de Tecnologia da Informação."},"gabarito":"A","explicacao":"O art. 1.197 atribui ao advogado ou procurador a correta formação do processo, carregando as peças na ordem: petição (I), procuração (II), documentos pessoais ou atos constitutivos (III), documentos de instrução (IV) e comprovante de despesas, se for o caso (V). Se a apresentação prejudicar o contraditório e a ampla defesa, o juiz pode determinar nova apresentação (§ 2º).","explicacoes":{"A":"Correta: art. 1.197.","B":"A responsabilidade é do advogado ou procurador.","C":"O distribuidor confere a formação (art. 1.210), mas a responsabilidade é do advogado.","D":"O juiz pode exigir nova apresentação, mas a responsabilidade é do advogado.","E":"Não é atribuição da STI."},"fonte":"NSCGJ, Tomo I, art. 1.197 (consolidação de 2017)","mastigado":"A resposta é a letra A. No processo eletrônico, é o advogado quem monta o processo: sobe a petição, a procuração, os documentos pessoais, as provas e o comprovante das custas, nessa ordem. Se ficar bagunçado a ponto de atrapalhar a defesa, o juiz manda refazer.","teSitua":{"termos":[{"termo":"procurador","significado":"pessoa que representa a parte em juízo, como advogado ou procurador público."},{"termo":"atos constitutivos","significado":"documentos que criam e regulam uma empresa, como o contrato social."},{"termo":"peças essenciais","significado":"documentos indispensáveis para o processo começar."}],"exemplo":"Ao ajuizar a ação eletrônica, o advogado Fábio anexou primeiro a petição, depois a procuração, o contrato social da empresa cliente, as notas fiscais e, por fim, a guia de custas paga, na ordem prevista."}},{"id":"aut.legislacao_tj.processo_eletronico.0006","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, quanto ao prazo para a prática de atos no processo eletrônico,","alternativas":{"A":"a petição será tempestiva quando recebida até as 24 horas do último dia do prazo, pela hora oficial de Brasília; se o vencimento ocorrer em dia sem expediente forense, prorroga-se até as 24 horas do primeiro dia útil subsequente.","B":"a petição é tempestiva se enviada até as 19 horas, encerramento do expediente.","C":"petições enviadas em dias sem expediente são consideradas protocoladas no próprio dia.","D":"vale o horário do computador do advogado.","E":"o prazo vence às 18 horas do último dia útil."},"gabarito":"A","explicacao":"O art. 1.198 considera os atos realizados no dia e hora do recebimento pelo sistema; é tempestiva a petição recebida até as 24h do último dia, pela hora de Brasília (§ 1º); vencido o prazo em dia sem expediente, prorroga-se até as 24h do primeiro dia útil seguinte (§ 2º); petições recebidas em dias sem expediente consideram-se protocoladas no primeiro dia útil seguinte (§ 3º). O sistema fornece recibo eletrônico com data e hora (art. 1.199).","explicacoes":{"A":"Correta: art. 1.198, §§ 1º e 2º.","B":"O limite é 24 horas, não o fim do expediente.","C":"Consideram-se protocoladas no primeiro dia útil seguinte (§ 3º).","D":"Vale a hora oficial de Brasília, registrada pelo sistema.","E":"O limite é 24 horas do último dia."},"fonte":"NSCGJ, Tomo I, arts. 1.198 e 1.199 (consolidação de 2017)","mastigado":"A resposta é a letra A. No processo eletrônico, dá para peticionar até meia-noite do último dia, pelo horário de Brasília. Se o prazo cair num feriado ou fim de semana, ele passa para a meia-noite do próximo dia útil.","teSitua":{"termos":[{"termo":"tempestiva","significado":"apresentada dentro do prazo fixado para o ato."},{"termo":"hora oficial de Brasília","significado":"horário de referência nacional usado pelo sistema."},{"termo":"expediente forense","significado":"período de funcionamento dos serviços judiciais."}],"exemplo":"O prazo da advogada Clara terminava num sábado. Como não houve expediente, o prazo foi prorrogado até as 24h da segunda-feira. Ela protocolou às 23h40 de segunda, e a petição foi tempestiva."}},{"id":"aut.legislacao_tj.processo_eletronico.0007","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, a suspensão dos prazos processuais impede o encaminhamento de petições e a movimentação de processos eletrônicos.","gabarito":"E","explicacao":"O art. 1.201 diz o contrário: a suspensão dos prazos não impede o encaminhamento de petições e a movimentação dos processos eletrônicos. Os pedidos feitos durante a suspensão são apreciados após seu término, salvo urgência (parágrafo único).","fonte":"NSCGJ, Tomo I, art. 1.201 (consolidação de 2017)","mastigado":"Errado. Mesmo com os prazos suspensos, por exemplo no recesso, o advogado pode mandar petições e o processo pode andar no sistema. Só que o juiz analisa os pedidos depois que a suspensão acabar, a menos que sejam urgentes.","teSitua":{"termos":[{"termo":"suspensão dos prazos processuais","significado":"período em que os prazos param de correr, como no recesso de fim de ano."},{"termo":"movimentação de processos","significado":"registro dos atos e do andamento do processo no sistema."}],"exemplo":"Em 5 de janeiro, com os prazos suspensos, o advogado Mauro enviou uma petição pedindo juntada de documentos. O sistema aceitou normalmente, e o pedido foi analisado pelo juiz depois de 20 de janeiro."}},{"id":"aut.legislacao_tj.processo_eletronico.0008","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, caracteriza indisponibilidade do sistema por parte do Tribunal a falta de oferta ao público externo dos serviços de","alternativas":{"A":"consulta aos autos digitais, transmissão eletrônica de peças processuais e acesso a citações, intimações ou notificações eletrônicas, não a caracterizando falhas nos equipamentos ou programas dos usuários.","B":"suporte técnico por telefone aos advogados.","C":"impressão de documentos no fórum.","D":"acesso à internet na residência do advogado.","E":"envio de e-mails entre advogados."},"gabarito":"A","explicacao":"O art. 1.202 define a indisponibilidade pela falta de oferta ao público externo de: consulta aos autos digitais (I); transmissão eletrônica de peças, inclusive petições (II); acesso a citações, intimações ou notificações eletrônicas (III). Falhas de transmissão entre o usuário e a rede pública e problemas nos equipamentos ou programas dos usuários não caracterizam indisponibilidade (parágrafo único).","explicacoes":{"A":"Correta: art. 1.202.","B":"Não está no rol do art. 1.202.","C":"Não está no rol do art. 1.202.","D":"Falhas do usuário não caracterizam indisponibilidade (parágrafo único).","E":"Não tem relação com o sistema do Tribunal."},"fonte":"NSCGJ, Tomo I, art. 1.202 (consolidação de 2017)","mastigado":"A resposta é a letra A. Só há indisponibilidade quando o sistema do Tribunal deixa de oferecer consulta aos autos, envio de petições ou acesso às intimações. Se o problema é a internet ou o computador do advogado, não conta.","teSitua":{"termos":[{"termo":"indisponibilidade do sistema","significado":"interrupção do serviço eletrônico por falha do próprio Tribunal."},{"termo":"público externo","significado":"usuários de fora do Tribunal, como advogados e partes."},{"termo":"notificações eletrônicas","significado":"comunicações oficiais feitas pelo sistema."}],"exemplo":"No último dia do prazo, a internet do escritório do advogado Júlio caiu e ele perdeu o prazo. Como o sistema do Tribunal funcionava normalmente, não houve indisponibilidade, e o prazo não foi prorrogado."}},{"id":"aut.legislacao_tj.processo_eletronico.0009","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":4,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (consolidação de 2017), nos casos de indisponibilidade do sistema por parte do Tribunal, prorroga-se automaticamente para o primeiro dia útil seguinte à solução do problema o prazo que vencer no dia da ocorrência, desde que a indisponibilidade","alternativas":{"A":"seja superior a 60 minutos, ininterruptos ou não, se ocorrida entre 6h e 23h, ou ocorra entre 23h e 24h.","B":"seja superior a 10 minutos, em qualquer horário.","C":"ocorra entre 0h e 6h dos dias de expediente forense.","D":"ocorra em feriados e finais de semana, por qualquer período.","E":"seja superior a 4 horas consecutivas."},"gabarito":"A","explicacao":"O art. 1.205, I, prorroga o prazo se a indisponibilidade for superior a 60 minutos, ininterruptos ou não, entre 6h e 23h (a), ou ocorrer entre 23h e 24h (b). O § 1º afasta esse efeito para indisponibilidades entre 0h e 6h e em feriados e fins de semana. Observação: para o sistema eproc, a Resolução TJSP 963/2025 (art. 21) adota janela diferente (superior a 60 minutos entre 12h e 23h, ou qualquer período entre 23h01 e 00h00).","explicacoes":{"A":"Correta: art. 1.205, I, a e b (consolidação de 2017).","B":"O mínimo é de 60 minutos.","C":"Essa faixa não produz prorrogação (§ 1º).","D":"Feriados e fins de semana não produzem prorrogação (§ 1º).","E":"O limite é de 60 minutos, ininterruptos ou não."},"fonte":"NSCGJ, Tomo I, art. 1.205, I e § 1º (consolidação de 2017)","mastigado":"A resposta é a letra A. Pelas Normas de 2017, se o sistema do Tribunal cair por mais de uma hora entre seis da manhã e onze da noite, ou cair na última hora antes da meia-noite, o prazo que vencia naquele dia passa para o próximo dia útil. De madrugada e em feriado, não muda nada.","teSitua":{"termos":[{"termo":"indisponibilidade do sistema","significado":"interrupção do serviço eletrônico por falha do Tribunal."},{"termo":"ininterruptos ou não","significado":"contados de uma vez só ou somando várias quedas no mesmo dia."},{"termo":"expediente forense","significado":"período de funcionamento dos serviços judiciais."}],"exemplo":"No último dia do prazo de recurso, o sistema do Tribunal ficou fora do ar por 40 minutos de manhã e mais 30 minutos à tarde, somando 70 minutos. O prazo do advogado Celso foi prorrogado para o dia útil seguinte."}},{"id":"aut.legislacao_tj.processo_eletronico.0010","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Em caso de indisponibilidade do sistema e risco de perecimento de direito, as Normas de Serviço da Corregedoria Geral da Justiça admitem petições urgentes em papel, que serão recebidas","alternativas":{"A":"durante o horário de funcionamento do fórum, no dia da indisponibilidade, desde que previamente admitidas pelo Juiz Corregedor Permanente do Distribuidor ou pelo juiz do feito, instruídas com cópias legíveis, vedado o recebimento de documentos originais.","B":"a qualquer hora, inclusive de madrugada, independentemente de autorização.","C":"somente no dia seguinte à indisponibilidade, com documentos originais.","D":"apenas se o advogado comprovar falha em seu próprio computador.","E":"pelo escrevente, sem necessidade de qualquer análise judicial."},"gabarito":"A","explicacao":"O art. 1.205, II, admite petições em papel em caso de risco de perecimento de direito, e o § 4º exige: recebimento no horário de funcionamento do fórum, no dia da indisponibilidade (I); prévia admissão pelo Juiz Corregedor Permanente do Distribuidor ou pelo juiz do feito, confirmadas a indisponibilidade e a urgência (II); cópias legíveis, vedados documentos originais (III).","explicacoes":{"A":"Correta: art. 1.205, II e § 4º.","B":"Exige-se horário do fórum e admissão judicial.","C":"O recebimento é no dia da indisponibilidade, e são vedados originais.","D":"Falhas do usuário não caracterizam indisponibilidade (art. 1.202, parágrafo único).","E":"É necessária a prévia admissão por juiz."},"fonte":"NSCGJ, Tomo I, art. 1.205, II e § 4º (consolidação de 2017)","mastigado":"A resposta é a letra A. Se o sistema cair e houver risco de perder um direito, o advogado pode levar a petição em papel ao fórum, no mesmo dia e no horário de funcionamento. Um juiz precisa aceitar antes, e só se entregam cópias, nunca os originais.","teSitua":{"termos":[{"termo":"perecimento de direito","significado":"perda definitiva de um direito por não ter sido exercido a tempo."},{"termo":"Juiz Corregedor Permanente do Distribuidor","significado":"juiz que fiscaliza o serviço de distribuição de processos."},{"termo":"documentos originais","significado":"documentos em sua primeira via, não cópias."}],"exemplo":"Com o sistema fora do ar desde a manhã, a advogada Rosa precisava pedir com urgência uma liminar para internação de um paciente. Às 14h, ela levou a petição em papel ao fórum, com cópias dos documentos, e o juiz corregedor do distribuidor admitiu o recebimento."}},{"id":"aut.legislacao_tj.processo_eletronico.0011","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Nas unidades com processos eletrônicos de Família e Sucessões, o pedido de alimentos formulado pelo credor sem assistência de advogado (alimentos de balcão), segundo as Normas de Serviço da Corregedoria Geral da Justiça,","alternativas":{"A":"será recepcionado ou reduzido a termo pelo ofício de justiça e encaminhado ao distribuidor para cadastro e digitalização; depois, os papéis aguardarão no ofício, por 45 dias, a retirada pelo autor, findo o qual serão inutilizados.","B":"deverá ser recusado, por exigir peticionamento eletrônico por advogado.","C":"será processado integralmente em papel até a sentença.","D":"deverá ser encaminhado à Defensoria Pública, que é a única que pode apresentá-lo.","E":"terá os documentos originais guardados até o fim do processo."},"gabarito":"A","explicacao":"O art. 1.207 prevê que os alimentos de balcão, recepcionados ou reduzidos a termo pelo ofício, sigam ao distribuidor para cadastro e digitalização; após, a petição física e os documentos voltam ao ofício e aguardam 45 dias a retirada pelo autor, sendo depois inutilizados (§ 1º). O autor é cientificado desse prazo ao comparecer (§ 2º). O art. 1.206 admite pedidos físicos nas hipóteses legais em que dispensada a assistência de advogado.","explicacoes":{"A":"Correta: art. 1.207 e § 1º.","B":"O pedido sem advogado é admitido (art. 1.206).","C":"O pedido é digitalizado e tramita eletronicamente.","D":"O próprio credor pode apresentá-lo.","E":"Os papéis aguardam retirada por 45 dias e depois são inutilizados."},"fonte":"NSCGJ, Tomo I, arts. 1.206 e 1.207 (consolidação de 2017)","mastigado":"A resposta é a letra A. A mãe que vai ao fórum pedir pensão sem advogado é atendida no balcão. O pedido é escrito ou recebido, digitalizado e segue no sistema. Os papéis ficam quarenta e cinco dias esperando ela buscar e depois são destruídos.","teSitua":{"termos":[{"termo":"alimentos de balcão","significado":"pedido de pensão alimentícia feito diretamente no cartório, sem advogado."},{"termo":"reduzido a termo","significado":"registrado por escrito pelo servidor a partir do relato oral da pessoa."},{"termo":"inutilizados","significado":"destruídos de forma controlada pelo cartório."}],"exemplo":"Joana foi ao fórum pedir pensão para o filho, sem advogado. A escrevente reduziu o pedido a termo e o enviou ao distribuidor para digitalização. Joana foi avisada de que teria 45 dias para retirar os papéis originais."}},{"id":"aut.legislacao_tj.processo_eletronico.0012","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, os pedidos apresentados em quaisquer modalidades de plantão judiciário serão formulados em petições em meio físico, mesmo quando dirigidos às unidades judiciais perante as quais tramitam processos eletrônicos.","gabarito":"C","explicacao":"É a regra do art. 1.208, na consolidação de 2017. A segunda via retida pelo magistrado é instruída com cópias legíveis, vedados originais (§ 1º); depois, a petição é distribuída no formato digital, cabendo a digitalização ao ofício de destino (§ 2º). Observação: a regra reflete a época da consolidação e deve ser conferida com as normas atuais do plantão eletrônico.","fonte":"NSCGJ, Tomo I, art. 1.208 (consolidação de 2017)","mastigado":"Certo. Pelas Normas de 2017, o pedido feito no plantão judiciário, à noite ou no fim de semana, é apresentado em papel, mesmo que o processo seja eletrônico. Depois, a petição é digitalizada e entra no sistema.","teSitua":{"termos":[{"termo":"plantão judiciário","significado":"atendimento judicial fora do expediente normal, para casos urgentes."},{"termo":"meio físico","significado":"papel, em oposição ao meio eletrônico."}],"exemplo":"No domingo, o advogado Hugo foi ao plantão judiciário pedir a soltura de um cliente. Ele apresentou a petição em papel, com cópias dos documentos. Na segunda-feira, a petição foi distribuída e digitalizada pelo cartório de destino."}},{"id":"aut.legislacao_tj.processo_eletronico.0013","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, é livre a consulta, no sítio do Tribunal, às movimentações processuais e ao inteiro teor das decisões, sentenças e acórdãos. Quanto ao conteúdo integral dos autos eletrônicos,","alternativas":{"A":"os advogados, defensores públicos, procuradores e membros do Ministério Público não vinculados ao processo, previamente identificados, poderão acessar todos os atos e documentos, salvo nos casos de sigilo ou segredo de justiça.","B":"somente o juiz e o escrivão podem acessá-lo.","C":"qualquer pessoa pode acessá-lo, inclusive em segredo de justiça.","D":"advogados não vinculados não podem acessá-lo em nenhuma hipótese.","E":"o acesso depende sempre de despacho judicial."},"gabarito":"A","explicacao":"O art. 1.224 garante consulta livre às movimentações e decisões; os habilitados nos autos têm acesso a todo o conteúdo (§ 1º); advogados, defensores, procuradores e membros do MP não vinculados, previamente identificados, acessam todos os atos e documentos, salvo sigilo ou segredo de justiça (§ 2º). Processos em segredo só são consultados pelas partes e procuradores habilitados (art. 1.225).","explicacoes":{"A":"Correta: art. 1.224, § 2º.","B":"O acesso é amplo para os profissionais identificados.","C":"Em segredo de justiça, o acesso é restrito (art. 1.225).","D":"Os não vinculados podem acessar, salvo sigilo.","E":"Não se exige despacho para processos públicos."},"fonte":"NSCGJ, Tomo I, arts. 1.224 e 1.225 (consolidação de 2017)","mastigado":"A resposta é a letra A. Qualquer pessoa vê na internet o andamento e as decisões. O processo inteiro pode ser aberto por advogados, defensores e promotores identificados no sistema, mesmo sem atuar nele, desde que não seja sigiloso.","teSitua":{"termos":[{"termo":"inteiro teor","significado":"texto completo de um ato ou documento."},{"termo":"acórdãos","significado":"decisões tomadas por órgãos colegiados dos tribunais."},{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, para proteger a intimidade das partes."}],"exemplo":"A advogada Tânia, que não atua no caso, consultou com seu certificado digital todos os documentos de uma ação pública de cobrança. Ao tentar abrir um processo de adoção, o acesso foi bloqueado por se tratar de segredo de justiça."}},{"id":"aut.legislacao_tj.processo_eletronico.0014","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, a indicação de que um processo eletrônico está submetido a segredo de justiça","alternativas":{"A":"pode ser feita pelo advogado no ajuizamento, sendo submetida à imediata análise pelo juiz e presumida válida até decisão judicial em sentido contrário.","B":"só pode ser feita pelo Corregedor Geral da Justiça.","C":"depende sempre de requerimento das duas partes.","D":"é feita pelo escrivão, sem possibilidade de revisão.","E":"não pode ser feita automaticamente pelo sistema."},"gabarito":"A","explicacao":"O art. 1.225, § 1º, admite a indicação do segredo: pelo advogado no ajuizamento (I), pelo órgão de origem na transmissão de recurso (II), por determinação do juiz ou relator (III) e automaticamente, por previsão legal (IV). A indicação é presumida válida até decisão em contrário (§ 2º), e a do advogado é submetida à imediata análise do juiz (§ 3º).","explicacoes":{"A":"Correta: art. 1.225, §§ 1º a 3º.","B":"Não há essa exclusividade.","C":"Não é necessário pedido das duas partes.","D":"O escrivão não é quem indica, e há revisão judicial.","E":"Há indicação automática por previsão legal (§ 1º, IV)."},"fonte":"NSCGJ, Tomo I, art. 1.225 (consolidação de 2017)","mastigado":"A resposta é a letra A. O próprio advogado pode marcar o processo como sigiloso ao entrar com a ação. Vale de imediato, mas o juiz analisa logo em seguida e pode tirar o sigilo se não for o caso.","teSitua":{"termos":[{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, permitida só às partes e advogados."},{"termo":"ajuizamento","significado":"ato de dar início ao processo na Justiça."},{"termo":"presumida válida","significado":"considerada correta até que se decida o contrário."}],"exemplo":"Ao ajuizar uma ação sobre a saúde mental do cliente, o advogado Pedro marcou o segredo de justiça no sistema. O processo ficou sigiloso de imediato, e o juiz, ao analisar, confirmou o sigilo."}},{"id":"aut.legislacao_tj.processo_eletronico.0015","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, o acesso à íntegra de processos digitais que não tramitem sob segredo de justiça a terceiro interessado será franqueado mediante","alternativas":{"A":"senha pessoal e intransferível, disponibilizada por 24 horas após sua emissão, mediante requerimento com qualificação e declaração de responsabilidade pelo conteúdo acessado.","B":"senha permanente, válida até o arquivamento do processo.","C":"simples pedido verbal ao balcão, sem identificação.","D":"autorização do Presidente do Tribunal.","E":"senha válida por 30 dias, sem necessidade de requerimento."},"gabarito":"A","explicacao":"O art. 1.226-A prevê senha pessoal e intransferível, válida por 24 horas após a emissão; o terceiro apresenta requerimento com qualificação e declaração de responsabilidade pessoal pelo conteúdo acessado (§ 1º); a senha é impressa pela unidade, uma por processo e interessado (§ 2º).","explicacoes":{"A":"Correta: art. 1.226-A, caput e § 1º.","B":"A senha vale por 24 horas.","C":"Exige-se requerimento com qualificação.","D":"A senha é fornecida pela unidade judicial.","E":"A senha vale por 24 horas e exige requerimento."},"fonte":"NSCGJ, Tomo I, art. 1.226-A (consolidação de 2017)","mastigado":"A resposta é a letra A. Quem não é parte nem advogado e quer ver o processo inteiro pede uma senha ao cartório, se identifica e assume responsabilidade pelo que acessar. A senha é só dele e dura vinte e quatro horas.","teSitua":{"termos":[{"termo":"terceiro interessado","significado":"pessoa que não é parte no processo, mas tem interesse em consultá-lo."},{"termo":"intransferível","significado":"que não pode ser passada a outra pessoa."}],"exemplo":"O jornalista Marcos quis ler a íntegra de uma ação pública contra uma prefeitura. Ele preencheu o requerimento no cartório, declarou responsabilidade pelo uso das informações e recebeu uma senha válida por 24 horas."}},{"id":"aut.legislacao_tj.processo_eletronico.0016","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, são dispensados os termos de conclusão e de vista nos autos digitais, gerando-se movimentação específica no momento do encaminhamento à fila de trabalho, de modo a identificar a data da remessa ao juiz, à Defensoria Pública e ao Ministério Público.","gabarito":"C","explicacao":"É o que dispõe o art. 1.240 e seu parágrafo único. Nos autos físicos, ao contrário, os termos de conclusão e de vista são obrigatórios e devem ter data (art. 98).","fonte":"NSCGJ, Tomo I, art. 1.240 (consolidação de 2017)","mastigado":"Certo. No processo eletrônico, o cartório não precisa lavrar termo dizendo que mandou o processo ao juiz ou ao promotor. O próprio sistema registra a data do envio na movimentação.","teSitua":{"termos":[{"termo":"termos de conclusão e de vista","significado":"anotações que registram o envio do processo ao juiz ou a alguém para manifestação."},{"termo":"fila de trabalho","significado":"lista do sistema onde ficam os processos aguardando determinada tarefa."}],"exemplo":"A escrevente Cíntia enviou um processo eletrônico ao gabinete do juiz. Ela não lavrou termo de conclusão: o sistema registrou automaticamente a movimentação com a data do envio."}},{"id":"aut.legislacao_tj.processo_eletronico.0017","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":4,"enunciado":"Nas intimações realizadas por meio de Portal Eletrônico, segundo as Normas de Serviço da Corregedoria Geral da Justiça, considera-se realizada a intimação","alternativas":{"A":"no dia em que o intimando efetivar a consulta eletrônica ao teor da intimação; não feita a consulta em até 10 dias corridos do envio, a intimação é considerada automaticamente realizada no término desse prazo.","B":"na data do envio, independentemente de consulta.","C":"somente quando o intimando assinar termo em cartório.","D":"30 dias após o envio, em qualquer caso.","E":"no dia da publicação no Diário Oficial do Estado."},"gabarito":"A","explicacao":"O art. 1.248-A considera realizada a intimação no dia da consulta eletrônica ao teor (II); se a consulta ocorrer em dia não útil, no primeiro dia útil seguinte (III); a consulta deve ocorrer em até 10 dias corridos do envio, sob pena de intimação automática no término desse prazo (IV), com certidão de não leitura (V). As instituições com prerrogativa de intimação pessoal são intimadas por portal próprio (art. 1.248).","explicacoes":{"A":"Correta: art. 1.248-A, II e IV.","B":"A intimação depende da consulta ou do decurso de 10 dias.","C":"Não há essa exigência.","D":"O prazo é de 10 dias corridos.","E":"A intimação por portal não depende de publicação no Diário Oficial."},"fonte":"NSCGJ, Tomo I, arts. 1.248 e 1.248-A (consolidação de 2017)","mastigado":"A resposta é a letra A. No portal eletrônico, a intimação acontece quando o promotor ou defensor abre a mensagem. Se não abrir em dez dias corridos, considera-se intimado no fim desse prazo, de qualquer jeito.","teSitua":{"termos":[{"termo":"Portal Eletrônico","significado":"área do sistema onde instituições recebem intimações eletrônicas."},{"termo":"intimando","significado":"pessoa ou órgão que deve ser intimado."},{"termo":"dias corridos","significado":"contagem que inclui todos os dias, úteis ou não."}],"exemplo":"Uma intimação foi enviada ao portal da Defensoria Pública em 1º de março. O defensor só abriu em 15 de março. Como passaram mais de dez dias corridos, a intimação foi considerada feita em 11 de março, com certidão de não leitura."}},{"id":"aut.legislacao_tj.processo_eletronico.0018","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"multipla","dificuldade":3,"enunciado":"Quando a citação ou intimação for realizada por oficial de justiça em processo eletrônico, segundo as Normas de Serviço da Corregedoria Geral da Justiça, considera-se juntado o mandado aos autos digitais, para fins de contagem de prazo,","alternativas":{"A":"a partir do momento em que o ofício de justiça digitaliza e libera o mandado positivo e libera a certidão do oficial, por este assinada eletronicamente.","B":"na data em que o oficial de justiça cumpriu a diligência.","C":"na data da expedição do mandado.","D":"5 dias após a devolução do mandado ao cartório.","E":"na data da publicação da intimação no Diário da Justiça."},"gabarito":"A","explicacao":"O art. 1.251 considera juntado o mandado, para fins do art. 231 do CPC, quando o ofício digitaliza e libera o mandado positivo e libera a certidão do oficial assinada eletronicamente. No mandado negativo, basta liberar a certidão (parágrafo único). Para citações pelo correio, vale a data da digitalização e liberação do AR físico ou da disponibilização do AR digital (art. 1.250).","explicacoes":{"A":"Correta: art. 1.251.","B":"O prazo conta da juntada, e não do cumprimento.","C":"A expedição não é o marco.","D":"Não há esse prazo adicional.","E":"No caso de mandado, o marco é a juntada aos autos digitais."},"fonte":"NSCGJ, Tomo I, arts. 1.250 e 1.251 (consolidação de 2017)","mastigado":"A resposta é a letra A. No processo eletrônico, o prazo de quem foi citado pelo oficial de justiça começa a contar a partir de quando o cartório coloca no sistema o mandado cumprido e a certidão do oficial. Antes disso, o mandado ainda não está juntado.","teSitua":{"termos":[{"termo":"mandado positivo","significado":"mandado cumprido com sucesso, com a pessoa encontrada."},{"termo":"contagem de prazo","significado":"cálculo do período para a prática de um ato."},{"termo":"oficial de justiça","significado":"servidor que cumpre fora do fórum as ordens do juiz."}],"exemplo":"O oficial de justiça citou o réu Carlos numa segunda-feira e devolveu o mandado na quarta. O cartório digitalizou e liberou o mandado e a certidão na quinta. O prazo de contestação foi contado a partir dessa liberação."}},{"id":"aut.legislacao_tj.processo_eletronico.0019","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, nos processos eletrônicos, as intimações e notificações serão realizadas por meio do Diário da Justiça Eletrônico, ressalvadas as exceções previstas em lei, e, na impossibilidade do uso do meio eletrônico, os atos urgentes serão praticados segundo os meios ordinários.","gabarito":"C","explicacao":"É o que dispõem os arts. 1.246 e 1.247. As cartas e mandados de citação contêm senha de acesso à íntegra dos autos digitais (art. 1.245).","fonte":"NSCGJ, Tomo I, arts. 1.245, 1.246 e 1.247 (consolidação de 2017)","mastigado":"Certo. No processo eletrônico, a regra é intimar pelo Diário da Justiça na internet, salvo exceções da lei. Se o meio eletrônico não puder ser usado, o ato urgente é feito pelos meios comuns, como oficial de justiça ou correio.","teSitua":{"termos":[{"termo":"Diário da Justiça Eletrônico","significado":"publicação oficial na internet onde saem os atos do Judiciário."},{"termo":"meios ordinários","significado":"formas tradicionais de comunicação, como correio e oficial de justiça."}],"exemplo":"A decisão que marcou uma audiência foi publicada no Diário da Justiça Eletrônico para intimar os advogados. Como uma testemunha não tinha acesso ao meio eletrônico, foi intimada por carta com aviso de recebimento."}},{"id":"aut.legislacao_tj.processo_eletronico.0020","subtopico":"legislacao_tj.nscgj.processo_eletronico","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, é obrigatória a utilização das tarjas coloridas disponibilizadas no sistema informatizado para identificação visual de situações processuais como justiça gratuita, réu preso, prioridade do idoso e segredo de justiça.","gabarito":"C","explicacao":"O art. 1.233 torna obrigatório o uso das tarjas do sistema para essas e outras situações (prioridade de pessoa com deficiência ou doença grave, urgente, atuação do Ministério Público, sigilo, vítima menor, Lei Maria da Penha etc.), sem prejuízo da anotação no campo próprio. Enquanto não disponíveis todas as tarjas, usam-se alertas (parágrafo único).","fonte":"NSCGJ, Tomo I, art. 1.233 (consolidação de 2017)","mastigado":"Certo. No processo eletrônico, certas situações têm de aparecer com uma etiqueta colorida no sistema, como réu preso, idoso, justiça gratuita e segredo de justiça. Assim todos percebem a situação de imediato.","teSitua":{"termos":[{"termo":"tarjas coloridas","significado":"marcas de cor no sistema que destacam situações especiais do processo."},{"termo":"justiça gratuita","significado":"benefício que dispensa a parte de pagar custas do processo."},{"termo":"réu preso","significado":"acusado que está detido durante o processo."}],"exemplo":"Ao cadastrar um processo criminal em que o acusado estava preso e a vítima era menor de idade, o escrevente Luís aplicou no sistema as tarjas de réu preso e de vítima menor, além de registrar as informações nos campos próprios."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0001","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça (Tomo I), as certidões em breve relatório ou de inteiro teor, cuja expedição compete exclusivamente aos ofícios de justiça,","alternativas":{"A":"serão expedidas no prazo de 5 dias, contados do recebimento do pedido, dependendo de despacho do juiz quando se tratar de processo em segredo de justiça.","B":"serão expedidas no prazo de 10 dias úteis, independentemente de despacho.","C":"serão expedidas imediatamente, no balcão, sem protocolo.","D":"dependem sempre de despacho do juiz, em qualquer processo.","E":"serão expedidas pelo distribuidor, no prazo de 48 horas."},"gabarito":"A","explicacao":"O art. 104 atribui exclusivamente aos ofícios de justiça a expedição de certidões, preferencialmente com base no sistema informatizado, com fé pública do escrivão (§ 1º). O prazo é de 5 dias do recebimento do pedido, com protocolo ao interessado (§ 2º); se houver requisição de autos do Arquivo Geral, conta-se do recebimento do feito (§ 4º); em processos sob segredo de justiça, depende de despacho do juiz (§ 5º).","explicacoes":{"A":"Correta: art. 104, §§ 2º e 5º.","B":"O prazo é de 5 dias, e há caso que depende de despacho.","C":"Há prazo e protocolo do pedido.","D":"Só depende de despacho o processo em segredo de justiça.","E":"A competência é exclusiva dos ofícios de justiça."},"fonte":"NSCGJ, Tomo I, art. 104 (consolidação de 2017)","mastigado":"A resposta é a letra A. Pediu certidão ao cartório, ela sai em até cinco dias, e o interessado recebe um protocolo do pedido. Se o processo for sigiloso, o juiz precisa autorizar antes.","teSitua":{"termos":[{"termo":"certidões em breve relatório","significado":"certidões que resumem as informações principais do processo."},{"termo":"inteiro teor","significado":"reprodução completa do conteúdo de um ato ou documento."},{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, permitida só às partes e advogados."}],"exemplo":"A advogada Joana pediu certidão de objeto e pé de um processo comum na segunda-feira e recebeu o protocolo. A certidão ficou pronta na sexta. Já a certidão de um processo de família, em segredo de justiça, dependeu de despacho do juiz."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0002","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, serão atendidos em 5 dias úteis os pedidos de certidões de objeto e pé formulados pelo correio eletrônico institucional de um ofício de justiça para outro, devendo a certidão ser encaminhada diretamente à unidade solicitante.","gabarito":"C","explicacao":"É o que dispõe o art. 104, § 3º. A transmissão eletrônica de pedidos e certidões de objeto e pé entre ofícios está prevista também no art. 113, V.","fonte":"NSCGJ, Tomo I, art. 104, § 3º; art. 113, V (consolidação de 2017)","mastigado":"Certo. Quando um cartório pede a outro, por e-mail oficial, uma certidão de objeto e pé, o cartório que recebeu tem cinco dias úteis para fazer e mandar a certidão direto para quem pediu.","teSitua":{"termos":[{"termo":"certidões de objeto e pé","significado":"certidões que informam o assunto do processo e a fase em que ele está."},{"termo":"correio eletrônico institucional","significado":"e-mail oficial do órgão ou do servidor."}],"exemplo":"O cartório da Vara de Execuções de Taubaté pediu por e-mail institucional ao cartório criminal de Jacareí uma certidão de objeto e pé. O cartório de Jacareí enviou a certidão por e-mail em quatro dias úteis."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0003","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"A requerimento escrito do credor, tratando-se de sentença cível transitada em julgado que reconheça obrigação de pagar quantia ou alimentos, as Normas de Serviço da Corregedoria Geral da Justiça preveem a expedição de certidão de teor da decisão para fins de protesto extrajudicial,","alternativas":{"A":"no prazo de 3 dias do recebimento do pedido, sendo levada a protesto sob a responsabilidade do credor.","B":"no prazo de 30 dias, a ser levada a protesto pelo próprio cartório judicial.","C":"somente após autorização do Corregedor Geral.","D":"no prazo de 10 dias, apenas se o devedor concordar.","E":"imediatamente, sem necessidade de requerimento."},"gabarito":"A","explicacao":"O art. 104-A prevê a certidão para protesto, indicando credor, devedor, número do processo, valor da dívida e a data em que decorreu o prazo para pagamento voluntário. Ela é expedida em 3 dias (§ 1º) e levada a protesto sob responsabilidade do credor (§ 3º). Comprovada a satisfação integral, o protesto é cancelado por ordem do juiz, a pedido do executado, mediante ofício expedido em 3 dias (§ 4º).","explicacoes":{"A":"Correta: art. 104-A, §§ 1º e 3º.","B":"O prazo é de 3 dias, e quem leva a protesto é o credor.","C":"Não há essa exigência.","D":"O prazo é de 3 dias, e não depende do devedor.","E":"Depende de requerimento escrito do credor."},"fonte":"NSCGJ, Tomo I, art. 104-A (consolidação de 2017)","mastigado":"A resposta é a letra A. Quem ganhou a ação e não recebeu pode pedir ao cartório uma certidão da sentença para protestar a dívida num tabelionato. O cartório tem três dias para entregar, e o próprio credor leva a certidão a protesto.","teSitua":{"termos":[{"termo":"transitada em julgado","significado":"decisão que se tornou definitiva, sem recurso possível."},{"termo":"protesto extrajudicial","significado":"registro da dívida em cartório de protesto, que torna pública a inadimplência."},{"termo":"credor","significado":"pessoa que tem um valor a receber."}],"exemplo":"Marta venceu uma ação de cobrança, e o devedor não pagou no prazo. Ela pediu por escrito a certidão para protesto, que o cartório expediu em três dias. Marta levou o documento ao tabelionato de protesto."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0004","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, constará de todos os mandados expedidos, além do número do processo e do número de ordem da carga,","alternativas":{"A":"o texto informando que é vedado ao oficial de justiça o recebimento de qualquer numerário diretamente da parte e que sua identificação será feita mediante carteira funcional, obrigatória em todas as diligências.","B":"a fotografia do oficial de justiça encarregado.","C":"o valor dos honorários do advogado da parte.","D":"a assinatura obrigatória do juiz, em todos os casos.","E":"o telefone pessoal do oficial de justiça."},"gabarito":"A","explicacao":"O art. 105 exige nos mandados o número do processo (I), o número de ordem da carga (II) e, ao pé, o texto sobre a vedação de recebimento de numerário pelo oficial diretamente da parte e a identificação por carteira funcional (III). Devem constar todos os endereços dos destinatários, inclusive do local de trabalho (§ 1º). A assinatura do juiz só é obrigatória nos casos do art. 85, § 1º.","explicacoes":{"A":"Correta: art. 105, III.","B":"Não há essa exigência.","C":"Não há essa exigência.","D":"Em regra, os mandados são assinados pelo escrivão por ordem do juiz (art. 85).","E":"Não há essa exigência."},"fonte":"NSCGJ, Tomo I, art. 105 (consolidação de 2017)","mastigado":"A resposta é a letra A. Todo mandado traz um aviso no rodapé: o oficial de justiça não pode receber dinheiro direto da parte e deve se identificar com a carteira funcional. Isso protege o cidadão contra golpes e cobranças indevidas.","teSitua":{"termos":[{"termo":"mandados","significado":"ordens escritas do juiz para que o oficial de justiça pratique um ato."},{"termo":"numerário","significado":"dinheiro em espécie entregue em mãos."},{"termo":"carteira funcional","significado":"documento oficial que identifica o servidor e seu cargo."}],"exemplo":"Ao receber o oficial de justiça para uma citação, Seu Antônio leu no rodapé do mandado que o oficial não pode receber dinheiro da parte e pediu para ver a carteira funcional dele, que foi apresentada."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0005","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os mandados de prisão não serão entregues aos oficiais de justiça, mas encaminhados ao Instituto de Identificação Ricardo Gumbleton Daunt (IIRGD).","gabarito":"C","explicacao":"É o que dispõe o parágrafo único do art. 108. Os demais mandados a cargo dos oficiais de justiça são distribuídos, na forma regulada pela Corregedoria Geral, aos lotados ou à disposição das comarcas ou varas (caput).","fonte":"NSCGJ, Tomo I, art. 108 e parágrafo único (consolidação de 2017)","mastigado":"Certo. O oficial de justiça não cumpre mandado de prisão. Esse mandado vai para o instituto de identificação da polícia, que cuida do registro e da circulação das ordens de prisão.","teSitua":{"termos":[{"termo":"mandados de prisão","significado":"ordens judiciais que determinam a prisão de alguém."},{"termo":"IIRGD","significado":"Instituto de Identificação da polícia paulista, responsável pelo registro de dados criminais."}],"exemplo":"O juiz decretou a prisão preventiva de um réu. A escrevente expediu o mandado de prisão e o encaminhou ao IIRGD, e não à central de mandados dos oficiais de justiça."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0006","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, mensalmente, o escrivão relacionará os mandados em poder dos oficiais de justiça além dos prazos legais ou fixados, comunicando ao Juiz Corregedor Permanente, para as providências cabíveis.","gabarito":"C","explicacao":"É a regra do art. 110. Nas certidões de expedição e de entrega dos mandados devem constar o nome do oficial a quem foi confiado o mandado e a data da carga (art. 109).","fonte":"NSCGJ, Tomo I, arts. 109 e 110 (consolidação de 2017)","mastigado":"Certo. Todo mês, o escrivão faz uma lista dos mandados que estão com os oficiais de justiça há mais tempo do que o permitido e manda para o juiz corregedor tomar providências.","teSitua":{"termos":[{"termo":"oficiais de justiça","significado":"servidores que cumprem fora do fórum as ordens do juiz, como citações e penhoras."},{"termo":"Juiz Corregedor Permanente","significado":"juiz encarregado de fiscalizar continuamente o cartório."}],"exemplo":"No início de março, o escrivão Paulo listou cinco mandados com os oficiais de justiça havia mais de trinta dias sem devolução e enviou a relação ao juiz corregedor, que cobrou os oficiais."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0007","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Nas comunicações oficiais por correio eletrônico entre ofícios de justiça, na ausência de confirmação de entrega e leitura pelo destinatário, as Normas de Serviço da Corregedoria Geral da Justiça estabelecem que","alternativas":{"A":"presumir-se-ão recebidas e lidas as mensagens no primeiro dia útil subsequente ao do envio, e, em medidas urgentes, o remetente fará contato telefônico e, se o caso, reenviará a mensagem, certificando nos autos.","B":"a mensagem será considerada não enviada, devendo ser expedida carta pelo correio.","C":"presumir-se-ão recebidas no quinto dia útil após o envio.","D":"a comunicação só produz efeito com confirmação expressa do juiz destinatário.","E":"o remetente deverá aguardar trinta dias antes de reiterar."},"gabarito":"A","explicacao":"O art. 118 presume recebidas e lidas as mensagens no primeiro dia útil subsequente ao envio. Em medidas urgentes, frustrada a entrega ou não confirmados recebimento e leitura até o dia seguinte, o remetente telefona ao destinatário e, se o caso, reenvia a mensagem, certificando tudo nos autos (parágrafo único). O remetente usa seu e-mail institucional, e não o da unidade (art. 115, I).","explicacoes":{"A":"Correta: art. 118 e parágrafo único.","B":"A mensagem é presumida recebida.","C":"A presunção é no primeiro dia útil subsequente.","D":"Não há essa exigência.","E":"Não há esse prazo; em urgência, há contato telefônico no dia seguinte."},"fonte":"NSCGJ, Tomo I, arts. 115 e 118 (consolidação de 2017)","mastigado":"A resposta é a letra A. Se o outro cartório não confirmar que recebeu e leu o e-mail, considera-se lido no primeiro dia útil seguinte. Se o assunto for urgente, quem mandou telefona e, se preciso, manda de novo, registrando tudo no processo.","teSitua":{"termos":[{"termo":"confirmação de entrega e leitura","significado":"aviso automático de que a mensagem chegou e foi aberta."},{"termo":"dia útil subsequente","significado":"próximo dia de expediente após o envio."},{"termo":"certificando","significado":"registrando oficialmente em certidão nos autos."}],"exemplo":"Numa quinta-feira, a escrevente Lara mandou um ofício urgente por e-mail a outra comarca. Sem confirmação na sexta, ela telefonou ao cartório destinatário, reenviou a mensagem e lavrou certidão no processo."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0008","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, a carta precatória será confeccionada em","alternativas":{"A":"3 vias, servindo uma delas de contrafé, e, quando o ato deprecado for a citação, será instruída com tantas cópias da petição inicial quantas sejam as pessoas a citar.","B":"2 vias, sem necessidade de cópias da inicial.","C":"via única, sempre eletrônica.","D":"4 vias, uma delas destinada ao Ministério Público.","E":"3 vias, sendo dispensado o pagamento da taxa judiciária."},"gabarito":"A","explicacao":"O art. 122 exige 3 vias, uma delas como contrafé; o pagamento da taxa de cumprimento deve ser demonstrado até a distribuição (§ 1º); e, na citação, uma cópia da inicial para cada pessoa a citar (§ 2º). As precatórias, quando possível, servem como mandado (art. 126).","explicacoes":{"A":"Correta: art. 122, caput e § 2º.","B":"São 3 vias e cópias para citação.","C":"Não é a regra das Normas.","D":"São 3 vias.","E":"A taxa judiciária deve ser comprovada até a distribuição (§ 1º)."},"fonte":"NSCGJ, Tomo I, arts. 122 e 126 (consolidação de 2017)","mastigado":"A resposta é a letra A. A carta precatória sai em três vias, e uma delas é entregue à pessoa como cópia, a contrafé. Se é para citar várias pessoas, vai uma cópia da petição inicial para cada uma.","teSitua":{"termos":[{"termo":"carta precatória","significado":"pedido de um juiz a outro, de outra comarca, para praticar um ato processual."},{"termo":"contrafé","significado":"cópia do documento entregue à pessoa citada ou intimada."},{"termo":"ato deprecado","significado":"ato que o juiz pede que outro juiz cumpra."}],"exemplo":"Para citar dois réus que moram em Recife, o cartório de Campinas expediu carta precatória em três vias, com duas cópias da petição inicial, uma para cada réu."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0009","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, o juízo deprecado devolverá a carta precatória, independentemente de cumprimento, quando não devidamente instruída e não houver regularização no prazo determinado.","gabarito":"C","explicacao":"É a regra do art. 124. Se o ato puder ser cumprido em endereço de outra jurisdição, o juízo deprecado encaminha a carta ao juízo competente e comunica o deprecante (art. 123).","fonte":"NSCGJ, Tomo I, arts. 123 e 124 (consolidação de 2017)","mastigado":"Certo. Se a carta precatória chega sem os documentos necessários e quem pediu não corrige no prazo, o juízo que recebeu devolve a carta sem cumprir. Se o endereço for de outra comarca, ele repassa a carta para lá.","teSitua":{"termos":[{"termo":"juízo deprecado","significado":"juízo que recebe a carta precatória para cumprir o ato."},{"termo":"devidamente instruída","significado":"acompanhada de todos os documentos e informações necessários."}],"exemplo":"Uma precatória para citação chegou a Sorocaba sem a cópia da petição inicial. O cartório pediu a regularização em dez dias. Como nada foi enviado, a carta foi devolvida ao juízo de origem sem cumprimento."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0010","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, é permitido ao servidor dos ofícios de justiça prestar informações por telefone aos advogados e às partes acerca dos atos e termos do processo, desde que se identifique.","gabarito":"E","explicacao":"O parágrafo único do art. 132 veda ao servidor dos ofícios de justiça prestar informações por telefone aos advogados, aos membros do Ministério Público, às partes e ao público em geral sobre atos e termos do processo. As intimações se fazem, sempre que possível, por meio eletrônico e pelo Diário da Justiça Eletrônico (caput).","fonte":"NSCGJ, Tomo I, art. 132 e parágrafo único (consolidação de 2017)","mastigado":"Errado. O servidor do cartório não pode dar informação sobre o processo por telefone, nem a advogado, nem a promotor, nem à parte. As comunicações oficiais são feitas por meio eletrônico e pelo Diário da Justiça.","teSitua":{"termos":[{"termo":"ofícios de justiça","significado":"cartórios judiciais que dão andamento aos processos."},{"termo":"atos e termos do processo","significado":"providências e registros feitos no andamento do processo."}],"exemplo":"Uma parte ligou para o cartório perguntando se o juiz já tinha decidido seu pedido. O escrevente Igor explicou, com educação, que não pode dar essa informação por telefone e orientou a consulta pelo site ou no balcão."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0011","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, os despachos, decisões interlocutórias e sentenças devem ser encaminhados à publicação no Diário da Justiça Eletrônico dentro do prazo máximo de","alternativas":{"A":"3 dias, a contar da devolução dos autos em cartório, prazo também observado para a intimação por meio eletrônico.","B":"5 dias, a contar da assinatura pelo juiz.","C":"10 dias, a contar da conclusão.","D":"24 horas, a contar da devolução dos autos.","E":"15 dias, a contar do registro."},"gabarito":"A","explicacao":"O art. 133 fixa o prazo máximo de 3 dias, contados da devolução dos autos em cartório, para encaminhar à publicação despachos, decisões e sentenças; o parágrafo único aplica o mesmo prazo à intimação por meio eletrônico.","explicacoes":{"A":"Correta: art. 133 e parágrafo único.","B":"O prazo é de 3 dias, contado da devolução dos autos.","C":"O prazo é de 3 dias.","D":"O prazo é de 3 dias.","E":"O prazo é de 3 dias."},"fonte":"NSCGJ, Tomo I, art. 133 (consolidação de 2017)","mastigado":"A resposta é a letra A. Quando o juiz devolve o processo com uma decisão, o cartório tem até três dias para mandá-la ao Diário da Justiça ou fazer a intimação eletrônica.","teSitua":{"termos":[{"termo":"decisões interlocutórias","significado":"decisões do juiz no meio do processo, que não o encerram."},{"termo":"Diário da Justiça Eletrônico","significado":"publicação oficial na internet onde saem os atos do Judiciário."}],"exemplo":"O juiz devolveu ao cartório, numa segunda-feira, um processo com decisão que deferiu uma perícia. A escrevente Bia encaminhou a decisão para publicação na quarta-feira, dentro dos três dias."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0012","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Nas intimações pela imprensa, segundo as Normas de Serviço da Corregedoria Geral da Justiça,","alternativas":{"A":"as decisões interlocutórias e sentenças serão publicadas somente na parte dispositiva, e, nos processos em segredo de justiça, constarão da publicação as iniciais das partes.","B":"as sentenças serão sempre publicadas na íntegra.","C":"os nomes completos das partes constarão sempre, inclusive em segredo de justiça.","D":"é dispensada a indicação do nome dos advogados.","E":"basta a publicação do número do processo."},"gabarito":"A","explicacao":"O art. 135, II, determina publicar decisões interlocutórias e sentenças só na parte dispositiva, e resumir ou transcrever atos ordinatórios e despachos com o necessário. O art. 138 manda constar as iniciais das partes nos processos sob segredo. O art. 134 exige número dos autos, objeto, nomes das partes, resumo do conteúdo e nomes dos advogados com o número da OAB.","explicacoes":{"A":"Correta: arts. 135, II, e 138.","B":"Publica-se apenas a parte dispositiva.","C":"No segredo de justiça, constam apenas as iniciais.","D":"Os advogados devem constar com o número da OAB (art. 134, III).","E":"Os requisitos do art. 134 devem ser observados."},"fonte":"NSCGJ, Tomo I, arts. 134, 135 e 138 (consolidação de 2017)","mastigado":"A resposta é a letra A. No Diário da Justiça sai só a parte final da sentença, o que foi decidido, e não o texto inteiro. Se o processo é sigiloso, aparecem apenas as iniciais das partes.","teSitua":{"termos":[{"termo":"intimações pela imprensa","significado":"comunicações de atos do processo feitas pelo Diário da Justiça."},{"termo":"parte dispositiva","significado":"trecho final da decisão, que diz o que foi decidido."},{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, para proteger a intimidade das partes."}],"exemplo":"Na publicação de uma sentença de divórcio, em segredo de justiça, apareceram apenas as iniciais M.S.P. e J.R.P., o nome dos advogados com a OAB e o trecho final da sentença decretando o divórcio."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0013","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, a publicação omissa quanto aos requisitos exigidos e que cause efetivo prejuízo a qualquer das partes será considerada nula, e, ocorrendo erro ou omissão de elemento indispensável, proceder-se-á imediatamente à retificação e nova publicação, independentemente de despacho ou de reclamação da parte.","gabarito":"C","explicacao":"É o que dispõem os arts. 136 e 137. Na nova publicação, junta-se aos autos cópia do ato incorretamente publicado (art. 137, parte final). Cabe aos escrivães conferir diariamente o teor das publicações (art. 142).","fonte":"NSCGJ, Tomo I, arts. 136, 137 e 142 (consolidação de 2017)","mastigado":"Certo. Se a publicação sai com erro que prejudica a parte, ela não vale. E o cartório não precisa esperar ordem do juiz ou reclamação: corrige e publica de novo assim que percebe o erro.","teSitua":{"termos":[{"termo":"publicação omissa","significado":"publicação que deixou de trazer informação obrigatória."},{"termo":"retificação","significado":"correção de um erro já publicado ou registrado."}],"exemplo":"A intimação de uma sentença saiu sem o nome do advogado do réu. Ao conferir o Diário, o escrivão percebeu o erro e, sem esperar despacho, mandou republicar corretamente, juntando aos autos a cópia da publicação errada."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0014","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, a designação de audiências é atribuição","alternativas":{"A":"exclusiva e indelegável do juiz, salvo nos juizados especiais.","B":"do escrivão judicial, conforme a pauta disponível.","C":"do escrevente responsável pela sala de audiências.","D":"do Juiz Corregedor Permanente, em todas as varas.","E":"das partes, de comum acordo."},"gabarito":"A","explicacao":"O art. 143 diz que a designação de audiências é atribuição exclusiva e indelegável do juiz, salvo nos juizados especiais. Havendo adiamento ou continuação, a nova data é marcada no próprio termo, com ciência imediata aos presentes (art. 144).","explicacoes":{"A":"Correta: art. 143.","B":"O escrivão não designa audiências.","C":"O escrevente não designa audiências.","D":"A designação cabe ao juiz do processo.","E":"As partes não designam audiências."},"fonte":"NSCGJ, Tomo I, arts. 143 e 144 (consolidação de 2017)","mastigado":"A resposta é a letra A. Só o juiz pode marcar audiência, e ele não pode passar essa tarefa a ninguém. A exceção é nos juizados especiais, onde a marcação pode ser feita de outra forma.","teSitua":{"termos":[{"termo":"designação de audiências","significado":"marcação da data e da hora em que a audiência vai acontecer."},{"termo":"indelegável","significado":"que não pode ser transferida a outra pessoa."},{"termo":"juizados especiais","significado":"unidades da Justiça para causas mais simples, com procedimento rápido."}],"exemplo":"Na Vara Cível de Botucatu, a escrevente Célia queria adiantar o serviço e marcar as audiências direto na agenda. O escrivão explicou que isso cabe só ao juiz. No Juizado Especial Cível ao lado, porém, a marcação segue regra própria."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0015","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, o servidor encarregado dos registros e audiências examinará os processos com audiência designada","alternativas":{"A":"10 dias antes das datas marcadas, para verificar se todas as providências de intimação ou requisição de partes e testemunhas foram tomadas.","B":"no próprio dia da audiência, uma hora antes.","C":"30 dias antes, apenas nos processos criminais.","D":"5 dias depois da audiência, para conferir a ata.","E":"apenas quando o juiz determinar."},"gabarito":"A","explicacao":"O art. 148 exige o exame dos processos 10 dias antes das audiências, para verificar se foram tomadas as providências de intimação ou requisição de partes e testemunhas; havendo irregularidade ou omissão, comunica-se imediatamente o servidor responsável.","explicacoes":{"A":"Correta: art. 148.","B":"O exame é feito 10 dias antes.","C":"O prazo é de 10 dias, para todos os processos.","D":"O exame é prévio.","E":"O exame é dever do servidor, sem depender de ordem."},"fonte":"NSCGJ, Tomo I, art. 148 (consolidação de 2017)","mastigado":"A resposta é a letra A. Dez dias antes de cada audiência, o servidor confere se as partes e testemunhas foram intimadas. Assim dá tempo de corrigir algum erro e a audiência não precisa ser adiada.","teSitua":{"termos":[{"termo":"requisição","significado":"pedido formal a outro órgão, como a requisição de um preso para a audiência."},{"termo":"testemunhas","significado":"pessoas chamadas para contar ao juiz o que sabem sobre os fatos."}],"exemplo":"A audiência estava marcada para o dia 20. No dia 10, o escrevente Mauro conferiu o processo e viu que uma testemunha não tinha sido intimada. Ele avisou o colega responsável, que expediu a intimação a tempo."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0016","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, os depoimentos registrados em meio audiovisual serão obrigatoriamente transcritos pelo ofício de justiça logo após a audiência.","gabarito":"E","explicacao":"O art. 152 diz que os depoimentos registrados em meio audiovisual não serão transcritos; havendo recurso, o escrivão certifica que o registro está em perfeito estado para reprodução. A transcrição pelo ofício só ocorre se houver recurso e for impossível o envio da documentação eletrônica (parágrafo único).","fonte":"NSCGJ, Tomo I, art. 152 (consolidação de 2017)","mastigado":"Errado. Depoimento gravado em vídeo não é passado para o papel. Só se transcreve se houver recurso e não for possível mandar a gravação eletrônica para o Tribunal.","teSitua":{"termos":[{"termo":"meio audiovisual","significado":"gravação em som e imagem."},{"termo":"transcritos","significado":"passados da gravação para o texto escrito."}],"exemplo":"Na audiência criminal, os depoimentos foram gravados em vídeo. Houve apelação, e o escrivão certificou que a gravação estava em perfeito estado, enviando-a ao Tribunal sem transcrever os depoimentos."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0017","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Quanto ao acesso aos autos, as Normas de Serviço da Corregedoria Geral da Justiça estabelecem que","alternativas":{"A":"o exame em balcão de autos não sujeitos a segredo de justiça é assegurado aos advogados, estagiários e ao público em geral, mesmo sem procuração, enquanto o exame de autos em segredo de justiça é restrito às partes e a seus procuradores constituídos.","B":"o exame de qualquer processo depende de procuração.","C":"o público em geral não pode examinar autos, mesmo sem segredo de justiça.","D":"estagiários sem inscrição na OAB podem examinar autos em segredo de justiça.","E":"é permitido desencartar peças para reprodução no balcão."},"gabarito":"A","explicacao":"O art. 157 assegura o exame em balcão de autos não sigilosos a advogados, estagiários e ao público, mesmo sem procuração, com apontamentos, cópias, escâner ou fotografia, vedado o desencarte de peças. O art. 160 restringe o exame dos autos sob segredo às partes e procuradores constituídos, vedado o acesso de estagiários não inscritos ou com inscrição vencida (§ 2º).","explicacoes":{"A":"Correta: arts. 157 e 160.","B":"O exame de autos não sigilosos independe de procuração.","C":"O público em geral tem acesso aos autos não sigilosos.","D":"É vedado o acesso desses estagiários (art. 160, § 2º).","E":"É vedado o desencarte (art. 157)."},"fonte":"NSCGJ, Tomo I, arts. 157 e 160 (consolidação de 2017)","mastigado":"A resposta é a letra A. Processo que não é sigiloso pode ser consultado no balcão por qualquer pessoa, que pode até fotografar. Processo em segredo de justiça só pode ser visto pelas partes e por seus advogados.","teSitua":{"termos":[{"termo":"procuração","significado":"documento pelo qual a parte autoriza o advogado a representá-la."},{"termo":"segredo de justiça","significado":"restrição de acesso ao processo, permitida só às partes e advogados."},{"termo":"procuradores constituídos","significado":"advogados que receberam procuração da parte no processo."}],"exemplo":"O estudante Renato pediu para ver uma ação de cobrança no balcão e fotografou as peças. Pouco depois, outra pessoa sem procuração pediu para ver uma ação de guarda de filhos, e o pedido foi negado por se tratar de segredo de justiça."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0018","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Segundo as Normas de Serviço da Corregedoria Geral da Justiça, a carga rápida dos autos físicos será concedida pelo escrivão ou escrevente responsável pelo atendimento","alternativas":{"A":"pelo período de uma hora, mediante formulário de controle, atendidos os requerimentos formulados até as 18h; não restituídos os autos no período, o escrivão representará em 24 horas ao Juiz Corregedor Permanente.","B":"pelo período de um dia, sem formulário.","C":"pelo período de duas horas, apenas a advogados com mais de cinco anos de inscrição.","D":"pelo período de uma hora, retendo-se a carteira da OAB do advogado como garantia.","E":"somente com autorização escrita do juiz em cada caso."},"gabarito":"A","explicacao":"O art. 165 prevê carga rápida por uma hora, com formulário de controle preenchido por advogado, estagiário constituído ou pessoa credenciada, recebidos os pedidos até as 18h (I); o formulário é juntado na devolução (II); não restituídos os autos, o escrivão representa em 24 horas ao Juiz Corregedor Permanente (III). É vedado reter documento de identificação do advogado (art. 166).","explicacoes":{"A":"Correta: art. 165, I a III.","B":"O período é de uma hora, com formulário.","C":"Não há essas condições.","D":"É vedada a retenção de documento do advogado (art. 166).","E":"Não depende de autorização do juiz em cada caso."},"fonte":"NSCGJ, Tomo I, arts. 165 e 166 (consolidação de 2017)","mastigado":"A resposta é a letra A. Na carga rápida, o advogado leva o processo físico por uma hora, para tirar cópias, preenchendo um formulário. O pedido deve ser feito até as dezoito horas. Se ele não devolver no tempo, o escrivão avisa o juiz em vinte e quatro horas.","teSitua":{"termos":[{"termo":"carga rápida","significado":"retirada dos autos por curto período, geralmente para cópia."},{"termo":"Juiz Corregedor Permanente","significado":"juiz que fiscaliza continuamente o cartório."}],"exemplo":"Às 15h, o advogado Pedro pediu carga rápida de um processo físico para tirar cópias. Preencheu o formulário e devolveu os autos às 15h50. A escrevente juntou o formulário aos autos e certificou o período de vista."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0019","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com as Normas de Serviço da Corregedoria Geral da Justiça, é vedada a retenção do documento de identificação do advogado ou do estagiário de Direito no ofício de justiça, para a finalidade de controle de carga de autos, em qualquer modalidade ou circunstância.","gabarito":"C","explicacao":"É a regra do art. 166. O controle da carga é feito por registro no sistema e no relatório de carga, com o número da carteira da OAB (art. 162, § 2º).","fonte":"NSCGJ, Tomo I, arts. 162 e 166 (consolidação de 2017)","mastigado":"Certo. O cartório não pode ficar com a carteira da OAB ou o documento do advogado como garantia de que ele vai devolver o processo. O controle é feito pelo registro da carga.","teSitua":{"termos":[{"termo":"retenção","significado":"ato de ficar com algo que pertence a outra pessoa."},{"termo":"carga de autos","significado":"retirada do processo do cartório, com registro de quem levou."}],"exemplo":"Para entregar os autos em carga, uma escrevente quis ficar com a carteira da OAB do advogado Lucas até a devolução. O escrivão a corrigiu, lembrando que essa retenção é proibida em qualquer caso."}},{"id":"aut.legislacao_tj.rotinas_cartorarias.0020","subtopico":"legislacao_tj.nscgj.rotinas_cartorarias","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos das Normas de Serviço da Corregedoria Geral da Justiça, sobre o arquivamento de processos, é correto afirmar que","alternativas":{"A":"nenhum processo será arquivado sem sentença definitiva ou terminativa, salvo os casos legais de suspensão por prazo indeterminado, e, publicada a decisão de arquivamento, os autos permanecerão no ofício por 30 dias antes da confecção dos pacotes de arquivo.","B":"o processo pode ser arquivado a qualquer tempo, por decisão do escrivão.","C":"os autos são remetidos ao arquivo no mesmo dia da sentença.","D":"as caixas de arquivo podem ser desdobradas com letras aditivas, como 1-A e 1-B.","E":"o desarquivamento independe do recolhimento de taxa."},"gabarito":"A","explicacao":"O art. 176 proíbe arquivar sem sentença definitiva ou terminativa, salvo suspensão legal por prazo indeterminado. Publicada a decisão de arquivamento, os autos ficam 30 dias no ofício e, depois, os pacotes são confeccionados em até 30 dias (art. 177). É vedado o uso de letras aditivas no desdobramento de caixas (art. 179, II), e o desarquivamento exige, ressalvadas exceções legais, o recolhimento da taxa (art. 181).","explicacoes":{"A":"Correta: arts. 176 e 177.","B":"O arquivamento depende de sentença ou de suspensão legal.","C":"Os autos permanecem 30 dias no ofício.","D":"É vedado o uso de letras aditivas (art. 179, II).","E":"O desarquivamento exige a taxa, salvo exceções legais (art. 181)."},"fonte":"NSCGJ, Tomo I, arts. 176, 177, 179 e 181 (consolidação de 2017)","mastigado":"A resposta é a letra A. Processo só vai para o arquivo depois de terminado por sentença, salvo nas suspensões previstas em lei. Mesmo assim, ele fica trinta dias no cartório antes de ser empacotado, caso alguém precise dele.","teSitua":{"termos":[{"termo":"sentença definitiva ou terminativa","significado":"decisão que encerra o processo, julgando ou não o mérito."},{"termo":"suspensão","significado":"paralisação temporária do processo, prevista em lei."},{"termo":"pacotes de arquivo","significado":"caixas padronizadas em que os processos encerrados são guardados."}],"exemplo":"A sentença de uma ação de cobrança transitou em julgado e o juiz mandou arquivar. Publicada a decisão em 2 de março, o processo ficou no cartório até 1º de abril e só então foi colocado na caixa de arquivo."}},{"id":"aut.legislacao_tj.teletrabalho_850.0001","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos da Resolução TJSP nº 850/2021, entende-se por teletrabalho a realização das atividades funcionais de servidores e magistrados fora das dependências físicas das unidades do Tribunal de Justiça, por meio de ambiente virtual.","gabarito":"C","explicacao":"É a definição do art. 1º da Resolução 850/2021. Entre os objetivos do teletrabalho estão reduzir tempo e custo de deslocamento, aumentar a produtividade e propiciar melhor qualidade de vida (art. 2º).","fonte":"Resolução TJSP 850/2021, art. 1º","mastigado":"Certo. Teletrabalho, para o TJSP, é fazer o trabalho do cargo fora do prédio do Tribunal, usando os sistemas virtuais. Vale tanto para servidores quanto para juízes.","teSitua":{"termos":[{"termo":"atividades funcionais","significado":"tarefas próprias do cargo ou da função exercida."},{"termo":"ambiente virtual","significado":"conjunto de sistemas eletrônicos acessados pela internet para realizar o trabalho."}],"exemplo":"A escrevente Simone trabalha em casa, em Guarulhos, acessando o sistema de processos do Tribunal pelo computador. Ela cumpre as tarefas do cartório sem ir ao fórum. Isso é teletrabalho nos termos da resolução."}},{"id":"aut.legislacao_tj.teletrabalho_850.0002","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 850/2021, o regime de teletrabalho, exercido de acordo com suas regras, assegura a quem o realize os mesmos direitos do regime de trabalho presencial,","alternativas":{"A":"inclusive auxílio-alimentação, exceção feita ao auxílio-transporte.","B":"inclusive auxílio-transporte, exceção feita ao auxílio-alimentação.","C":"inclusive auxílio-alimentação e auxílio-transporte.","D":"exceto auxílio-alimentação e auxílio-transporte.","E":"acrescidos de auxílio para despesas com internet e energia elétrica."},"gabarito":"A","explicacao":"O art. 3º assegura os mesmos direitos do trabalho presencial, inclusive auxílio-alimentação, exceto auxílio-transporte. O art. 8º, § 2º, repete que o dia em teletrabalho vale para todos os fins, incluído o auxílio-alimentação e excluído o auxílio-transporte. O Tribunal não arca com custo de bens ou serviços do servidor (art. 20).","explicacoes":{"A":"Correta: art. 3º e art. 8º, § 2º.","B":"É o contrário: mantém-se o auxílio-alimentação e exclui-se o auxílio-transporte.","C":"O auxílio-transporte é excluído.","D":"O auxílio-alimentação é mantido.","E":"O Tribunal não arca com nenhum custo de bens ou serviços (art. 20)."},"fonte":"Resolução TJSP 850/2021, art. 3º e art. 8º, § 2º","mastigado":"A resposta é a letra A. Quem trabalha de casa mantém os mesmos direitos de quem vai ao fórum, inclusive o vale-refeição. Só perde o auxílio-transporte, porque não precisa se deslocar. Despesas como internet ficam por conta do servidor.","teSitua":{"termos":[{"termo":"auxílio-alimentação","significado":"valor pago ao servidor para ajudar nas despesas com refeição."},{"termo":"auxílio-transporte","significado":"valor pago para ajudar nas despesas de deslocamento até o trabalho."}],"exemplo":"Ao entrar em teletrabalho, o escrevente Rodrigo continuou recebendo o auxílio-alimentação normalmente. O auxílio-transporte foi cortado, já que ele não se desloca mais até o fórum."}},{"id":"aut.legislacao_tj.teletrabalho_850.0003","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Resolução TJSP nº 850/2021, quanto aos equipamentos e à estrutura necessários ao teletrabalho, é correto afirmar que","alternativas":{"A":"o servidor deverá providenciá-los às suas expensas e sob sua responsabilidade, e o regime não será permitido se implicar qualquer despesa ao Tribunal.","B":"o Tribunal fornecerá computador e internet a todos os servidores em teletrabalho.","C":"o Tribunal reembolsará metade das despesas com energia elétrica.","D":"o servidor poderá levar para casa a estação de trabalho do fórum, sem autorização.","E":"o Tribunal arcará com os custos de aquisição de software e impressoras."},"gabarito":"A","explicacao":"O art. 4º veda o teletrabalho que implique qualquer despesa ao Tribunal; o art. 5º obriga servidores e magistrados a providenciar, às suas expensas, mesas, cadeiras, computadores, internet e demais itens; e o art. 20 diz que o Tribunal não arcará com custo algum na aquisição de bens ou serviços. É permitido apenas o suporte remoto da STI para configuração e instalação de softwares (art. 20, parágrafo único).","explicacoes":{"A":"Correta: arts. 4º e 5º.","B":"O Tribunal não fornece esses itens (arts. 5º e 20).","C":"Não há reembolso (art. 20).","D":"Não há essa previsão; a estação do fórum pode ser desativada e devolvida à STI (art. 10, § 5º).","E":"O Tribunal não arca com custos de bens ou serviços (art. 20)."},"fonte":"Resolução TJSP 850/2021, arts. 4º, 5º e 20","mastigado":"A resposta é a letra A. Quem quer trabalhar de casa monta a própria estrutura: computador, cadeira, internet, tudo por conta própria. O teletrabalho não pode gerar nenhuma despesa para o Tribunal.","teSitua":{"termos":[{"termo":"às suas expensas","significado":"com o próprio dinheiro, sem reembolso."},{"termo":"estação de trabalho","significado":"posto com computador e mesa disponível ao servidor no prédio do Tribunal."},{"termo":"software","significado":"programa de computador usado no trabalho."}],"exemplo":"Antes de começar o teletrabalho, a escrevente Ivone comprou um monitor, uma cadeira adequada e contratou internet mais rápida. Tudo foi pago por ela, porque o Tribunal não reembolsa nenhum desses gastos."}},{"id":"aut.legislacao_tj.teletrabalho_850.0004","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":2,"enunciado":"Pela Resolução TJSP nº 850/2021, o teletrabalho de servidores sujeita-se à exigência de que as atividades sejam, exclusivamente, relativas a processamentos digitais.","gabarito":"C","explicacao":"É a regra do art. 9º, I. Além disso, o art. 17 restringe o teletrabalho a tarefas que permitam mensuração objetiva do desempenho, e o art. 8º, § 1º, exclui atividades que devam ser executadas exclusivamente nos prédios do Tribunal.","fonte":"Resolução TJSP 850/2021, art. 9º, I","mastigado":"Certo. Em teletrabalho, o servidor só pode fazer tarefas de processos digitais. O que depende de papel ou de presença física no fórum não pode ser feito de casa.","teSitua":{"termos":[{"termo":"processamentos digitais","significado":"tarefas feitas em processos eletrônicos, dentro dos sistemas informatizados."}],"exemplo":"No cartório de Heloísa ainda há alguns processos físicos. Ela, em teletrabalho, cuida apenas dos processos digitais, enquanto os colegas que estão no fórum cuidam dos autos em papel."}},{"id":"aut.legislacao_tj.teletrabalho_850.0005","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Uma vara de primeiro grau, que não é gabinete, tem 9 servidores no quadro. Nos termos da Resolução TJSP nº 850/2021, o número máximo de servidores que podem estar em teletrabalho nessa unidade é de","alternativas":{"A":"5 servidores, pois o limite é de 50% do quadro, arredondada a fração para o número inteiro imediatamente superior.","B":"4 servidores, pois o limite é de 50% do quadro, desprezada a fração.","C":"6 servidores, pois o limite é de 70% do quadro, desprezada a fração.","D":"7 servidores, pois o limite é de 70% do quadro, arredondada a fração para cima.","E":"9 servidores, pois não há limite nas unidades de primeiro grau."},"gabarito":"A","explicacao":"Nas unidades de primeiro grau, exceto gabinetes, o limite é de até 50% do quadro, arredondadas as frações para o primeiro inteiro imediatamente superior (art. 9º, III). Metade de 9 é 4,5, que se arredonda para 5. O limite de 70% vale para unidades vinculadas à Presidência, Vice-Presidência, Corregedoria e Presidências de Seção (inciso II).","explicacoes":{"A":"Correta: art. 9º, III (9 × 50% = 4,5, arredondado para 5).","B":"A fração é arredondada para cima, não desprezada.","C":"O limite de 70% é das unidades vinculadas à Presidência e órgãos de cúpula (inciso II).","D":"O limite de 70% não se aplica à vara de primeiro grau.","E":"Há limite de 50% no primeiro grau."},"fonte":"Resolução TJSP 850/2021, art. 9º, II e III","mastigado":"A resposta é a letra A. Na vara de primeiro grau, até metade dos servidores pode trabalhar de casa. Metade de nove dá quatro e meio, e a regra manda arredondar para cima: cinco servidores.","teSitua":{"termos":[{"termo":"primeiro grau","significado":"primeira instância da Justiça, onde atuam os juízes de direito nas varas."},{"termo":"quadro","significado":"conjunto de servidores lotados na unidade."},{"termo":"fração","significado":"parte não inteira de um número, como 0,5."}],"exemplo":"A 3ª Vara Cível de Sorocaba tem 9 servidores. Seis querem teletrabalho, mas só 5 podem ser autorizados. O chefe escolhe os de perfil mais adequado e pode propor revezamento, sempre respeitando o limite diário."}},{"id":"aut.legislacao_tj.teletrabalho_850.0006","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 850/2021, nos gabinetes, o número de servidores em teletrabalho será definido pelo Juiz ou Desembargador.","gabarito":"C","explicacao":"É o que diz o art. 9º, IV. Os limites percentuais de 70% e 50% (incisos II e III) não se aplicam aos gabinetes.","fonte":"Resolução TJSP 850/2021, art. 9º, IV","mastigado":"Certo. No gabinete de um juiz ou desembargador, não vale o limite de porcentagem. Quem decide quantos assessores trabalham de casa é o próprio magistrado.","teSitua":{"termos":[{"termo":"gabinetes","significado":"unidades de apoio direto ao juiz ou desembargador, com assessores e assistentes."},{"termo":"Desembargador","significado":"juiz do Tribunal de Justiça, que julga recursos na segunda instância."}],"exemplo":"O desembargador Laércio tem cinco assistentes em seu gabinete e autorizou que quatro trabalhem de casa. Como se trata de gabinete, a decisão sobre o número cabe a ele, sem o limite de metade do quadro."}},{"id":"aut.legislacao_tj.teletrabalho_850.0007","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a Resolução TJSP nº 850/2021, o intervalo para almoço do servidor em teletrabalho","alternativas":{"A":"será de 30 minutos, admitida tolerância de até 15 minutos, e deverá ocorrer obrigatoriamente entre 12h e 14h, vedado nesse período o agendamento de reuniões ou contato, salvo urgência.","B":"será livremente fixado pelo servidor, em qualquer horário.","C":"será de 1 hora, entre 11h e 15h.","D":"será de 15 minutos, sem tolerância, entre 12h e 13h.","E":"poderá ser dispensado, se o servidor cumprir a meta."},"gabarito":"A","explicacao":"O art. 9º, VIII, fixa intervalo de 30 minutos, com tolerância de até 15 minutos, obrigatoriamente entre 12h e 14h, vedados reuniões ou contato nesse período, salvo urgência. O contato entre servidor e gestor deve ocorrer em dias úteis, no horário do expediente forense (inciso VII).","explicacoes":{"A":"Correta: art. 9º, VIII.","B":"O horário é fixado pela resolução, entre 12h e 14h.","C":"O intervalo é de 30 minutos, entre 12h e 14h.","D":"O intervalo é de 30 minutos, com tolerância de 15.","E":"O intervalo é obrigatório."},"fonte":"Resolução TJSP 850/2021, art. 9º, VII e VIII","mastigado":"A resposta é a letra A. Quem trabalha de casa almoça em meia hora, com até quinze minutos de folga, sempre entre meio-dia e duas da tarde. Nesse horário, o chefe não pode marcar reunião nem chamar o servidor, a não ser em urgência.","teSitua":{"termos":[{"termo":"tolerância","significado":"margem de tempo a mais admitida sem prejuízo."},{"termo":"salvo situação de urgência","significado":"exceto quando houver necessidade imediata que não pode esperar."}],"exemplo":"O gestor de Natália queria marcar reunião às 12h30. Como ela estava no intervalo de almoço, que deve ocorrer entre 12h e 14h, a reunião foi remarcada para as 14h30, pois não havia urgência."}},{"id":"aut.legislacao_tj.teletrabalho_850.0008","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 850/2021, a frequência do servidor em teletrabalho e o alcance de sua meta de produtividade têm o seguinte tratamento:","alternativas":{"A":"a frequência é registrada com o log in e o log off no sistema, equivalente ao registro de ponto, e a superação da meta não implica horas extras nem banco de horas.","B":"a frequência é dispensada, bastando o cumprimento mensal da meta.","C":"a superação da meta gera direito a banco de horas.","D":"a superação da meta gera pagamento de gratificação de horas extras.","E":"a frequência é registrada por relatório semanal enviado por e-mail ao gestor."},"gabarito":"A","explicacao":"O art. 9º, IX, determina que a frequência seja registrada pelo log in e log off no sistema, equivalendo ao ponto. O inciso X diz que o alcance da meta equivale ao cumprimento da jornada e que sua superação não gera horas extras nem banco de horas.","explicacoes":{"A":"Correta: art. 9º, IX e X.","B":"A frequência é registrada pelo log in e log off.","C":"A superação da meta não forma banco de horas (inciso X).","D":"A superação da meta não gera horas extras (inciso X).","E":"O registro é o log in e log off no sistema."},"fonte":"Resolução TJSP 850/2021, art. 9º, IX e X","mastigado":"A resposta é a letra A. Entrar e sair do sistema funciona como bater o ponto. Bater a meta equivale a cumprir a jornada, e fazer mais do que a meta não dá direito a hora extra nem a folga acumulada.","teSitua":{"termos":[{"termo":"log in e o log off","significado":"registro de entrada e de saída no sistema informatizado."},{"termo":"banco de horas","significado":"acúmulo de horas trabalhadas a mais para compensar depois com folga."},{"termo":"meta de produtividade","significado":"quantidade de trabalho que o servidor deve entregar no período."}],"exemplo":"Juliano, em teletrabalho, terminou a meta do mês em três semanas e continuou produzindo. Ele não ganha horas extras nem banco de horas por isso. Seu ponto continua sendo o registro de entrada e saída no sistema."}},{"id":"aut.legislacao_tj.teletrabalho_850.0009","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":3,"enunciado":"Pela Resolução TJSP nº 850/2021, entre o gestor da unidade ou a chefia imediata e o servidor em teletrabalho deverão ser realizadas reuniões virtuais, segundo acordo prévio, com periodicidade mínima semestral.","gabarito":"E","explicacao":"O art. 9º, VI, exige reuniões virtuais com periodicidade mínima mensal. A afirmativa troca o prazo. As reuniões servem para avaliação e acompanhamento dos trabalhos e, quando possível, interação com os demais membros da unidade (parágrafo único). O relatório semestral é outro instituto, enviado pelo gestor à SGP (art. 15).","fonte":"Resolução TJSP 850/2021, art. 9º, VI e parágrafo único","mastigado":"Errado. As reuniões virtuais entre o chefe e quem está em teletrabalho devem acontecer pelo menos uma vez por mês, e não por semestre. O que é semestral é o relatório que o gestor manda à área de pessoas.","teSitua":{"termos":[{"termo":"periodicidade mínima","significado":"frequência mínima com que algo deve acontecer."},{"termo":"chefia imediata","significado":"superior direto a quem o servidor responde."}],"exemplo":"A gestora Paula marca, todo mês, uma reunião por vídeo com cada servidor em teletrabalho para avaliar o andamento das tarefas. Se esperasse seis meses para fazer isso, estaria descumprindo a resolução."}},{"id":"aut.legislacao_tj.teletrabalho_850.0010","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":2,"enunciado":"Segundo a Resolução TJSP nº 850/2021, o teletrabalho","alternativas":{"A":"tem caráter facultativo, é realizado no interesse e a critério da Administração e depende de requerimento com autorização prévia do Desembargador, Juiz ou gestor da unidade.","B":"é direito subjetivo de todo servidor efetivo.","C":"é obrigatório para os escreventes técnicos judiciários.","D":"depende apenas de comunicação do servidor ao gestor, sem autorização.","E":"vigora pelo prazo máximo de 1 ano, renovável."},"gabarito":"A","explicacao":"O art. 10 qualifica o teletrabalho como facultativo, no interesse e a critério da Administração, dependente de requerimento em formulário próprio com autorização prévia do magistrado ou gestor, compromisso de cumprir os deveres e declaração de que o local atende às exigências. A participação é informada à SGP em até 10 dias úteis e vigora por tempo indeterminado (§ 1º).","explicacoes":{"A":"Correta: art. 10, caput.","B":"Não é direito subjetivo; fica a critério da Administração.","C":"É facultativo, não obrigatório.","D":"Exige requerimento e autorização prévia.","E":"Vigora por tempo indeterminado (§ 1º)."},"fonte":"Resolução TJSP 850/2021, art. 10, caput e § 1º","mastigado":"A resposta é a letra A. Ninguém é obrigado a trabalhar de casa, e ninguém tem direito garantido a isso. O servidor pede, o chefe autoriza se for bom para o serviço, e a autorização vale por tempo indeterminado enquanto as condições se mantiverem.","teSitua":{"termos":[{"termo":"caráter facultativo","significado":"que depende de escolha; não é obrigatório."},{"termo":"a critério da Administração","significado":"conforme a avaliação de conveniência feita pela Administração."},{"termo":"direito subjetivo","significado":"direito que a pessoa pode exigir, sem depender da vontade de outro."}],"exemplo":"A escrevente Laura preencheu o formulário de teletrabalho, obteve a autorização do juiz e declarou que sua casa atende às exigências. Sua participação foi comunicada à Secretaria de Gestão de Pessoas e vale por tempo indeterminado."}},{"id":"aut.legislacao_tj.teletrabalho_850.0011","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com a Resolução TJSP nº 850/2021, as autorizações para realização de teletrabalho dos servidores serão publicadas no Diário da Justiça Eletrônico, e os nomes dos autorizados serão disponibilizados no Portal da Transparência, com atualização mínima semestral.","gabarito":"C","explicacao":"É o que dispõem os §§ 2º e 3º do art. 10. A publicidade das autorizações permite o controle social do regime.","fonte":"Resolução TJSP 850/2021, art. 10, §§ 2º e 3º","mastigado":"Certo. O teletrabalho não é segredo: a autorização sai no Diário da Justiça, e a lista de quem trabalha de casa fica no Portal da Transparência, atualizada pelo menos a cada seis meses.","teSitua":{"termos":[{"termo":"Diário da Justiça Eletrônico","significado":"publicação oficial na internet onde saem os atos do Judiciário."},{"termo":"Portal da Transparência","significado":"página pública na internet com informações sobre gestão e pessoal do órgão."}],"exemplo":"O cidadão Gustavo quis saber quais servidores do fórum de sua cidade estão em teletrabalho. Ele consultou o Portal da Transparência do Tribunal, onde a lista é atualizada ao menos semestralmente."}},{"id":"aut.legislacao_tj.teletrabalho_850.0012","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 850/2021, é vedada a participação em teletrabalho do servidor que","alternativas":{"A":"esteja no primeiro ano do estágio probatório.","B":"tenha sofrido penalidade disciplinar há mais de 5 anos.","C":"tenha sido removido há mais de 1 ano.","D":"tenha alcançado conceito positivo na avaliação de desempenho mais recente.","E":"resida em município diverso daquele em que está lotado, com autorização da Administração."},"gabarito":"A","explicacao":"O art. 11 veda o teletrabalho a quem: tenha contraindicação de saúde comprovada por laudo (I); tenha sofrido penalidade disciplinar nos 2 anos anteriores (II); tenha sido desligado do teletrabalho por metas ou regras nos últimos 6 meses (III); tenha sido relotado por remoção nos últimos 6 meses (IV); não tenha conceito positivo na última avaliação (V); esteja no primeiro ano do estágio probatório (VI). O art. 10, § 4º, admite autorização para residir em local diverso da lotação.","explicacoes":{"A":"Correta: art. 11, VI.","B":"A vedação é para penalidade nos 2 anos anteriores (inciso II).","C":"A vedação é para remoção nos últimos 6 meses (inciso IV).","D":"A vedação é para quem não alcançou conceito positivo (inciso V).","E":"Residir em local diverso pode ser autorizado (art. 10, § 4º)."},"fonte":"Resolução TJSP 850/2021, art. 11","mastigado":"A resposta é a letra A. Quem acabou de entrar e ainda está no primeiro ano do estágio probatório não pode trabalhar de casa. Também ficam de fora quem foi punido nos últimos dois anos e quem foi removido nos últimos seis meses.","teSitua":{"termos":[{"termo":"estágio probatório","significado":"período inicial em que o servidor novo é avaliado antes de adquirir estabilidade."},{"termo":"penalidade disciplinar","significado":"punição aplicada ao servidor por falta funcional."},{"termo":"conceito positivo","significado":"resultado favorável na avaliação de desempenho."}],"exemplo":"Tomou posse em março e, em agosto, Carlos pediu teletrabalho. O pedido foi negado, porque ele está no primeiro ano do estágio probatório. Poderá pedir de novo depois de completar esse primeiro ano."}},{"id":"aut.legislacao_tj.teletrabalho_850.0013","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":2,"enunciado":"Um escrevente em teletrabalho pede ao irmão, que não é servidor, que o ajude a cumprir a meta mensal, movimentando processos em seu nome. Segundo a Resolução TJSP nº 850/2021, essa conduta","alternativas":{"A":"viola o dever de cumprir diretamente as atividades, sendo vedada a utilização de terceiros, servidores ou não, para cumprir as metas.","B":"é permitida, desde que a meta seja alcançada com qualidade.","C":"é permitida, se o irmão assinar termo de confidencialidade.","D":"só é vedada se o terceiro for outro servidor.","E":"é permitida, desde que comunicada à SGP."},"gabarito":"A","explicacao":"O art. 12, VII, impõe ao servidor cumprir diretamente as atividades, vedada a utilização de terceiros, servidores ou não, para cumprir as metas. A conduta também afronta o dever de preservar o sigilo dos dados (VI) e o termo de confidencialidade (X).","explicacoes":{"A":"Correta: art. 12, VII.","B":"O cumprimento da meta não autoriza o uso de terceiros.","C":"Não há essa exceção; o dever é pessoal.","D":"A vedação alcança terceiros servidores ou não.","E":"Não há previsão de comunicação que torne a conduta lícita."},"fonte":"Resolução TJSP 850/2021, art. 12, VI, VII e X","mastigado":"A resposta é a letra A. O trabalho em casa é pessoal. O servidor não pode pedir a ninguém, nem a parente nem a colega, que faça as tarefas por ele, e ainda estaria expondo dados sigilosos dos processos.","teSitua":{"termos":[{"termo":"terceiros","significado":"pessoas diferentes do próprio servidor."},{"termo":"meta mensal","significado":"quantidade de trabalho que o servidor deve entregar no mês."}],"exemplo":"Atrasado com a meta, o escrevente Leandro deixou o irmão usar seu login para movimentar processos. Descoberto, ele terá de prestar esclarecimentos e pode ser desligado do teletrabalho, além de responder disciplinarmente."}},{"id":"aut.legislacao_tj.teletrabalho_850.0014","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Diante de denúncia motivada e identificada de descumprimento dos deveres do teletrabalho, o servidor, nos termos da Resolução TJSP nº 850/2021, deverá prestar esclarecimentos ao gestor da unidade no prazo de","alternativas":{"A":"2 dias úteis, podendo o gestor suspender o teletrabalho e comunicar o fato à SGP.","B":"5 dias úteis, sendo vedada a suspensão do teletrabalho antes de processo disciplinar.","C":"10 dias úteis, cabendo à Presidência decidir.","D":"48 horas corridas, com afastamento automático.","E":"15 dias, sob pena de demissão."},"gabarito":"A","explicacao":"O art. 13 prevê que, em caso de descumprimento dos deveres ou de denúncia motivada e identificada, o servidor preste esclarecimentos ao gestor em 2 dias úteis, podendo o gestor suspender o teletrabalho e comunicar à SGP.","explicacoes":{"A":"Correta: art. 13.","B":"O prazo é de 2 dias úteis, e o gestor pode suspender o teletrabalho.","C":"O prazo é de 2 dias úteis, e quem pode suspender é o gestor.","D":"O prazo é de 2 dias úteis, sem afastamento automático.","E":"O prazo é de 2 dias úteis, e a consequência é a possível suspensão do teletrabalho."},"fonte":"Resolução TJSP 850/2021, art. 13","mastigado":"A resposta é a letra A. Se houver suspeita de que o servidor não está cumprindo as regras, ele tem dois dias úteis para se explicar ao chefe. Conforme a explicação, o chefe pode suspender o teletrabalho e avisar a área de pessoas.","teSitua":{"termos":[{"termo":"denúncia motivada e identificada","significado":"comunicação de irregularidade com razões e com o nome de quem denuncia."},{"termo":"SGP","significado":"Secretaria de Gestão de Pessoas do Tribunal de Justiça."}],"exemplo":"Uma advogada se identificou e informou que o servidor Fábio não atendia o telefone de contato durante o expediente. O gestor pediu explicações, e Fábio teve dois dias úteis para responder. Insatisfeito com a resposta, o gestor suspendeu o teletrabalho."}},{"id":"aut.legislacao_tj.teletrabalho_850.0015","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Resolução TJSP nº 850/2021, a produtividade do servidor em teletrabalho deverá ser superior à produtividade aferida na atividade presencial da unidade, ficando dispensados desse acréscimo os servidores em teletrabalho nos termos do capítulo que trata de pessoas com deficiência, necessidades especiais ou doença grave.","gabarito":"C","explicacao":"O art. 18, caput, exige produtividade superior à presencial, e o § 3º, acrescido pela Resolução 864/2022, dispensa desse acréscimo os servidores em teletrabalho com base no Capítulo IV.","fonte":"Resolução TJSP 850/2021, art. 18, caput e § 3º","mastigado":"Certo. Quem trabalha de casa tem de produzir mais do que a média de quem está no fórum. A exceção é para quem está em teletrabalho por deficiência, doença grave ou por cuidar de filho nessas condições.","teSitua":{"termos":[{"termo":"produtividade","significado":"quantidade de trabalho entregue em determinado período."},{"termo":"necessidades especiais","significado":"condições que exigem apoio ou adaptação para o trabalho ou a vida diária."},{"termo":"doença grave","significado":"enfermidade séria, das previstas em lei, que justifica condições especiais."}],"exemplo":"No cartório de Márcia, cada servidor presencial cumpre em média 300 atos por mês. Quem está em teletrabalho deve superar essa marca. Já Otávio, em teletrabalho por ter filho com deficiência, está dispensado desse acréscimo."}},{"id":"aut.legislacao_tj.teletrabalho_850.0016","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Desligado do teletrabalho, o servidor, segundo a Resolução TJSP nº 850/2021, terá o prazo de","alternativas":{"A":"até 5 dias úteis para retorno ao trabalho presencial, mantido, no período, o dever de cumprir as atividades do plano de trabalho.","B":"até 30 dias corridos para retorno, sem obrigação de cumprir metas.","C":"24 horas para retorno, sob pena de falta injustificada.","D":"até 10 dias úteis para retorno, dispensado o cumprimento das atividades.","E":"até 2 dias úteis para retorno, contados da comunicação à SGP."},"gabarito":"A","explicacao":"O art. 19, § 1º, concede até 5 dias úteis para o retorno ao presencial, mantido o dever de cumprir as atividades do plano de trabalho. O desligamento pode ocorrer a pedido, a qualquer tempo; por fim do teletrabalho na unidade; por necessidade de serviço presencial; por não atingimento de metas; a critério do gestor ou da Presidência; ou por alteração de posto ou cargo (art. 19, I a VI).","explicacoes":{"A":"Correta: art. 19, § 1º.","B":"O prazo é de até 5 dias úteis, com dever de cumprir as atividades.","C":"O prazo é de até 5 dias úteis.","D":"O prazo é de até 5 dias úteis, e as atividades continuam devidas.","E":"Dois dias úteis é o prazo para esclarecimentos (art. 13)."},"fonte":"Resolução TJSP 850/2021, art. 19, I a VI e § 1º","mastigado":"A resposta é a letra A. Quando o teletrabalho acaba, o servidor tem até cinco dias úteis para voltar ao fórum. Nesses dias, continua trabalhando de casa normalmente, cumprindo o plano de trabalho.","teSitua":{"termos":[{"termo":"desligado do teletrabalho","significado":"retirado do regime de trabalho remoto, voltando ao presencial."},{"termo":"plano de trabalho","significado":"documento com as atividades, metas e reuniões combinadas entre chefia e servidor."}],"exemplo":"Na segunda-feira, a gestora informou a Elisa que ela seria desligada do teletrabalho por necessidade de serviço presencial. Elisa continuou cumprindo as tarefas de casa e voltou ao fórum na sexta-feira, dentro dos cinco dias úteis."}},{"id":"aut.legislacao_tj.teletrabalho_850.0017","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Resolução TJSP nº 850/2021, a chefia imediata, em conjunto com o gestor da unidade, deve elaborar com o servidor o plano de trabalho, que deverá contemplar, entre outros itens,","alternativas":{"A":"as metas a serem alcançadas e a periodicidade em que o servidor deverá comparecer ao local de trabalho.","B":"o valor do auxílio-transporte a ser pago.","C":"a lista de equipamentos que o Tribunal fornecerá.","D":"a autorização para que terceiros auxiliem no cumprimento das metas.","E":"o número de horas extras a serem pagas pela superação das metas."},"gabarito":"A","explicacao":"O art. 14, II, manda o plano de trabalho contemplar: descrição das atividades (a); metas (b); periodicidade de comparecimento ao local de trabalho (c); e cronograma de reuniões para revisão de metas e avaliação (d). O plano pode ser alterado a qualquer tempo, no interesse da Administração (parágrafo único).","explicacoes":{"A":"Correta: art. 14, II, b e c.","B":"Não há auxílio-transporte no teletrabalho (art. 3º).","C":"O Tribunal não fornece equipamentos (art. 20).","D":"É vedada a utilização de terceiros (art. 12, VII).","E":"Não há horas extras pela superação da meta (art. 9º, X)."},"fonte":"Resolução TJSP 850/2021, art. 14, II e parágrafo único","mastigado":"A resposta é a letra A. O plano de trabalho é combinado entre chefe e servidor e diz o que ele vai fazer, quanto precisa entregar, de quanto em quanto tempo deve ir ao fórum e quando haverá reuniões de acompanhamento.","teSitua":{"termos":[{"termo":"chefia imediata","significado":"superior direto a quem o servidor responde."},{"termo":"plano de trabalho","significado":"documento que define atividades, metas, comparecimentos e reuniões do teletrabalho."},{"termo":"periodicidade","significado":"frequência com que algo se repete."}],"exemplo":"Ao entrar em teletrabalho, Valéria elaborou com a chefe o plano de trabalho: ela cuidará das expedições, terá meta de 350 atos por mês, irá ao fórum uma vez por semana e terá reunião mensal com a chefe."}},{"id":"aut.legislacao_tj.teletrabalho_850.0018","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Resolução TJSP nº 850/2021, os magistrados titulares de comarcas de entrância final que optarem pelo regime de teletrabalho deverão comparecer ao fórum","alternativas":{"A":"pelo menos 3 dias úteis por semana.","B":"pelo menos 4 dias úteis por semana.","C":"pelo menos 1 dia útil por semana.","D":"pelo menos 2 dias úteis por semana.","E":"apenas quando houver audiência designada."},"gabarito":"A","explicacao":"O art. 24, caput, exige comparecimento mínimo de 3 dias úteis por semana dos titulares de entrância final e dos titulares de entrância intermediária com mais de 3 varas. Para entrância intermediária com 3 ou menos varas, entrância inicial e juízes substitutos, o mínimo é de 4 dias (§ 1º). Nos dias remotos, o magistrado deve estar na comarca onde autorizado a residir (§ 3º).","explicacoes":{"A":"Correta: art. 24, caput.","B":"Quatro dias é o mínimo das comarcas menores e dos substitutos (§ 1º).","C":"O mínimo é de 3 dias úteis.","D":"O mínimo é de 3 dias úteis.","E":"Há comparecimento mínimo semanal."},"fonte":"Resolução TJSP 850/2021, art. 24, caput, §§ 1º e 3º","mastigado":"A resposta é a letra A. O juiz de comarca grande pode trabalhar de casa, mas precisa ir ao fórum pelo menos três dias úteis por semana. Nas comarcas menores e para juízes substitutos, o mínimo sobe para quatro dias.","teSitua":{"termos":[{"termo":"magistrados titulares","significado":"juízes que ocupam de forma permanente a vara em que atuam."},{"termo":"entrância final","significado":"categoria das comarcas maiores no Estado, como a Capital e grandes cidades."}],"exemplo":"O juiz Marcos é titular de uma vara na comarca de Campinas, de entrância final, e optou pelo teletrabalho. Ele vai ao fórum às segundas, terças e quartas, e nos demais dias trabalha de casa, na própria comarca."}},{"id":"aut.legislacao_tj.teletrabalho_850.0019","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Resolução TJSP nº 850/2021, o magistrado diretor do fórum deverá zelar para que seja garantida, em cada dia útil da escala, a presença de pelo menos 1/3 do número total de magistrados em exercício no fórum, regra que não se aplica às comarcas de vara única.","gabarito":"C","explicacao":"O art. 25, § 1º, fixa o piso de 1/3 dos magistrados presentes em cada dia útil, e o § 2º afasta esse piso nas comarcas de vara única, que observam apenas o comparecimento mínimo do art. 24, § 1º. A escala é submetida à Presidência e à Corregedoria (caput) e publicada no sítio do Tribunal (§ 4º).","fonte":"Resolução TJSP 850/2021, art. 25, §§ 1º, 2º e 4º","mastigado":"Certo. Em fóruns com vários juízes, todo dia útil pelo menos um terço deles precisa estar presente. Na comarca de vara única, como só há um juiz, vale apenas a regra de comparecimento mínimo dele.","teSitua":{"termos":[{"termo":"magistrado diretor","significado":"juiz responsável pela administração do fórum."},{"termo":"escala","significado":"lista que define quais juízes estarão presentes em cada dia."},{"termo":"vara única","significado":"comarca com uma só vara, que concentra todos os tipos de processo."}],"exemplo":"No fórum de Jundiaí há nove juízes. A diretora do fórum monta a escala de modo que, em todos os dias úteis, pelo menos três estejam presentes. Na comarca vizinha, de vara única, a juíza segue só a regra de quatro dias por semana."}},{"id":"aut.legislacao_tj.teletrabalho_850.0020","subtopico":"legislacao_tj.resolucoes.teletrabalho_850","tipo":"certo_errado","dificuldade":3,"enunciado":"Pela Resolução TJSP nº 850/2021, servidores com deficiência, necessidades especiais ou doença grave, ou que tenham filhos ou dependentes legais nessa condição, poderão requerer diretamente à Presidência do Tribunal a concessão de condição especial de trabalho, que dependerá de compensação laboral posterior e implicará redução proporcional da remuneração.","gabarito":"E","explicacao":"O art. 32 permite o requerimento direto à Presidência, independentemente de compensação laboral posterior e sem prejuízo da remuneração. Para manter a condição especial, deve-se apresentar laudo médico anualmente (§ 5º). Entre as modalidades estão o teletrabalho, a designação provisória para outra comarca, o apoio à unidade e a jornada especial (art. 29).","fonte":"Resolução TJSP 850/2021, arts. 29 e 32, caput e § 5º","mastigado":"Errado. O servidor com deficiência, doença grave ou que cuida de filho nessas condições pode pedir condição especial de trabalho direto à Presidência, sem precisar compensar horas depois e sem perder salário. Basta renovar o laudo médico todo ano.","teSitua":{"termos":[{"termo":"condição especial de trabalho","significado":"regime adaptado, como teletrabalho ou jornada especial, para quem tem deficiência, doença grave ou dependente nessa situação."},{"termo":"dependentes legais","significado":"pessoas que dependem juridicamente do servidor, como filhos menores ou tutelados."},{"termo":"compensação laboral","significado":"obrigação de repor horas ou trabalho em outro momento."}],"exemplo":"A escrevente Cecília tem um filho com autismo que faz terapias diárias. Ela pediu à Presidência condição especial de trabalho, com laudo técnico, e obteve teletrabalho sem redução de salário. Todo ano ela apresenta novo laudo para manter o benefício."}}]`);export{e as default};